//! Posting list encoding and decoding for xerj FTS.
//!
//! ## Format
//!
//! Posting lists are split into **128-doc blocks** (matching Lucene's default).
//! Within each block, doc IDs are delta-encoded and PFOR-packed using the
//! `bitpacking` crate for SIMD-accelerated bit-manipulation.
//!
//! Per-term layout written into the `.post` blob (see
//! [`PostingsWriter::encode_term`]):
//!
//! ```text
//! ┌─────────────────────────────────────────┐
//! │  Block 0: packed doc_id deltas          │
//! │           packed term_freqs (positioned)│
//! │           positions (vbyte, positioned) │
//! ├─────────────────────────────────────────┤
//! │  Block 1 …                              │
//! ├─────────────────────────────────────────┤
//! │  Residual (< 128 docs, vbyte)           │
//! └─────────────────────────────────────────┘
//! ```
//!
//! ## Block framing: ZPS2 (current) and ZPS1 (legacy)
//!
//! The `.post` envelope magic doubles as the inner-framing version.  A `ZPS2`
//! file uses the framing below; a `ZPS1` file uses the older
//! `[num_bits ≥ 1][u32 byte_len][payload]` framing, which the reader still
//! decodes (see [`PostCodec`]).
//!
//! ZPS2 packed streams (doc-id deltas, term freqs) are frame-of-reference
//! coded per block — the same shape tantivy uses for sorted blocks (a vint
//! base plus bit-packed residuals; `postings/compression/mod.rs`
//! `uncompress_block_sorted` in tantivy @ 6182c6062) — with three extra rules
//! that remove bytes the old framing paid even when they carried no
//! information:
//!
//! ```text
//!   [width: u8]        0 = every lane equals `min`, no payload follows
//!                     1..=32 = bit width of (value − min) lanes
//!   [min: vbyte]       the frame's base, added back on decode
//!   [payload]          128 × width / 8 bytes — length DERIVED, never stored
//! ```
//!
//! An all-equal block (dense-field doc-id deltas of 1, a term whose freqs are
//! all k) costs 2–3 bytes total instead of the 21 the old framing paid.  The
//! old `u32 byte_len` was pure overhead: it is always `128 × width / 8`.
//!
//! The frame's `min` is subtracted when that narrows the width, and also on
//! narrow blocks (≤ [`ZPS2_FOR_MAX_EQUAL_WIDTH`] bits) where it normalises
//! level-shifted repeats into identical payloads for the outer zstd pass.
//! On WIDE equal-width blocks the subtraction only rewrites lanes zstd would
//! have matched verbatim, so those emit `min = 0` with raw lanes — see the
//! constant's doc comment for the measured story.
//!
//! ## Term-frequency elision
//!
//! A positioned term whose `total_term_frequency == doc_frequency` has, by
//! construction, `term_freq == 1` in every document (df positive ints
//! summing to df).  The writer omits the term's ENTIRE freq stream — full
//! blocks and residual vbytes alike — and the reader re-derives the same
//! predicate from the `.meta` record it already loaded (tantivy gates its
//! freq block on `term_has_freq`, `postings/serializer.rs::write_block`;
//! Lucene 50 elides per term when ttf == df).  Docs-only fields have always
//! done this via `store_positions = false`.
//!
//! Residual docs (< 128) at the end use variable-byte encoding.  In docs-only
//! mode (`store_positions = false`) the freq and position sub-blocks are
//! omitted and the reader synthesises `term_freq = 1`.
//!
//! The per-term `(doc_frequency, total_term_frequency, offset)` header lives in
//! the FST term dictionary / `.meta` file, **not** inline in the `.post` blob.
//!
//! ## Skip-list acceleration: NOT implemented
//!
//! There is **no on-disk skip table**.  [`PostingsWriter::encode_term`] computes
//! a [`SkipEntry`] vector in memory (one entry every [`SKIP_INTERVAL`] blocks)
//! but it is **never serialised** — the caller in `xerj-fts::index` discards it,
//! and the whole `.post` blob is wrapped in a Zstd envelope, so intra-blob byte
//! offsets would not be usable as seek targets anyway.  Consequently
//! [`PostingsReader::advance_to`] performs a **linear scan**, not a skip-list
//! seek.  Traversal is correct, just unaccelerated; the [`SkipEntry`] machinery
//! is scaffolding for a future block-skip implementation.

use byteorder::{LittleEndian, ReadBytesExt, WriteBytesExt};
use std::io::{self, Cursor};

/// Number of docs per PFOR block (must be a multiple of 128 for bitpacking).
pub const BLOCK_SIZE: usize = 128;

/// Cadence at which [`PostingsWriter::encode_term`] emits an in-memory
/// [`SkipEntry`].  NOTE: these entries are never persisted or consulted — see
/// the module docs' "Skip-list acceleration: NOT implemented" note.
pub const SKIP_INTERVAL: usize = 8; // every 1024 docs

// ── Term metadata ─────────────────────────────────────────────────────────────

/// Metadata stored in the term dictionary alongside the FST key.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct TermPostings {
    /// Number of documents that contain this term (≡ Lucene's `docFreq`).
    pub doc_frequency: u32,
    /// Sum of term frequency across all documents (≡ Lucene's `totalTermFreq`).
    pub total_term_frequency: u64,
    /// Byte offset into the postings file where this term's data starts.
    pub postings_offset: u64,
    /// Byte length of the postings data for this term.
    pub postings_length: u32,
}

impl TermPostings {
    /// Serialise to a fixed-size 20-byte record.
    pub fn encode(&self) -> [u8; 20] {
        let mut buf = [0u8; 20];
        let mut c = Cursor::new(buf.as_mut_slice());
        c.write_u32::<LittleEndian>(self.doc_frequency).unwrap();
        c.write_u64::<LittleEndian>(self.total_term_frequency)
            .unwrap();
        c.write_u64::<LittleEndian>(self.postings_offset).unwrap();
        // last 4 bytes: length — split from offset to stay 20 B
        // rewrite cleanly:
        let mut out = [0u8; 20];
        out[0..4].copy_from_slice(&self.doc_frequency.to_le_bytes());
        out[4..12].copy_from_slice(&self.total_term_frequency.to_le_bytes());
        out[12..20].copy_from_slice(&self.postings_offset.to_le_bytes());
        out
    }

    /// Parse from the 20-byte record produced by [`encode`].
    /// `postings_length` and `postings_offset` are stored separately in the
    /// FST value (offset only fits in 64 bits); length is stored here.
    pub fn decode(buf: &[u8]) -> io::Result<Self> {
        if buf.len() < 20 {
            return Err(io::Error::new(
                io::ErrorKind::InvalidData,
                "buffer too short for TermPostings",
            ));
        }
        let mut c = Cursor::new(buf);
        let doc_frequency = c.read_u32::<LittleEndian>()?;
        let total_term_frequency = c.read_u64::<LittleEndian>()?;
        let postings_offset = c.read_u64::<LittleEndian>()?;
        Ok(Self {
            doc_frequency,
            total_term_frequency,
            postings_offset,
            postings_length: 0, // filled by caller from separate source
        })
    }
}

// ── Skip table entry ──────────────────────────────────────────────────────────

/// A single would-be skip pointer into a term's block stream.
///
/// **Currently unused scaffolding.**  [`PostingsWriter::encode_term`] builds a
/// `Vec<SkipEntry>` but the value is discarded by its only caller and is never
/// written to the `.post` file, so no reader ever consults it.  It exists to
/// mark the intended shape of a future block-skip index; see the module docs.
#[derive(Debug, Clone)]
pub struct SkipEntry {
    /// Highest doc ID in the preceding block range.
    pub max_doc_id: u32,
    /// Byte offset of the first byte of the corresponding block.
    pub byte_offset: u32,
}

// ── PostingsWriter ────────────────────────────────────────────────────────────

/// Accumulated posting data for one term during index construction.
///
/// `positions` is empty (capacity 0, no heap allocation) when the writer
/// is configured with `store_positions = false` — the common case for
/// `keyword`, `ip`, numeric, and status-like log fields.  Skipping
/// positions here turns each posting from `32 + 24 + Vec<u32>` bytes
/// down to just `32 + 24` bytes of stack, and eliminates the per-occurrence
/// `Vec::push` that dominates ingest time for high-cardinality
/// repeating-value fields (e.g. nginx `method` with 27 000 occurrences
/// of `"GET"` per segment, each currently allocating a 1-element position
/// list into a growable Vec).
#[derive(Default)]
struct RawPosting {
    doc_id: u32,
    term_freq: u32,
    positions: Vec<u32>,
}

/// Accumulates postings for all terms in one field/segment, then serialises
/// them into the compact block format.
pub struct PostingsWriter {
    /// Per-term posting data, sorted by doc_id within each term.
    postings: std::collections::BTreeMap<String, Vec<RawPosting>>,
    /// When `false`, `add_occurrence` discards positions and `encode_term`
    /// writes a zero-length positions block per 128-doc block.  Saves ~60 %
    /// of `.post` bytes on keyword fields.
    store_positions: bool,
}

impl PostingsWriter {
    pub fn new() -> Self {
        Self {
            postings: std::collections::BTreeMap::new(),
            store_positions: true,
        }
    }

    /// Build a writer that omits positions.  Use for `keyword`, numeric,
    /// and other exact-match fields — they never answer phrase queries.
    pub fn new_no_positions() -> Self {
        Self {
            postings: std::collections::BTreeMap::new(),
            store_positions: false,
        }
    }

    pub fn store_positions(&self) -> bool {
        self.store_positions
    }

    /// Record one occurrence of `term` in `doc_id` at the given `position`.
    ///
    /// When the writer was constructed without positions, `position` is
    /// ignored and no heap growth happens in the `positions` Vec.
    pub fn add_occurrence(&mut self, term: &str, doc_id: u32, position: u32) {
        // Lookup-first to avoid the `term.to_owned()` String allocation
        // that `entry()` forced on EVERY occurrence (13M+ allocs per 1M
        // docs at flush time).  Misses (first occurrence of a term) pay
        // one extra BTreeMap descent — postings are Zipf-shaped, so hits
        // dominate.
        if let Some(list) = self.postings.get_mut(term) {
            if let Some(last) = list.last_mut() {
                if last.doc_id == doc_id {
                    last.term_freq += 1;
                    if self.store_positions {
                        last.positions.push(position);
                    }
                    return;
                }
            }
            list.push(RawPosting {
                doc_id,
                term_freq: 1,
                positions: if self.store_positions {
                    vec![position]
                } else {
                    Vec::new()
                },
            });
            return;
        }
        self.postings.insert(
            term.to_owned(),
            vec![RawPosting {
                doc_id,
                term_freq: 1,
                positions: if self.store_positions {
                    vec![position]
                } else {
                    Vec::new()
                },
            }],
        );
    }

    /// Append a whole run of already-decoded postings for `term`.
    ///
    /// This is the merge path's ingest entry point.  `add_occurrence` is the
    /// INDEXING entry point: it takes one token at a time because that is
    /// what an analyzer produces.  A merge has no analyzer — it has one
    /// [`DecodedPosting`] per (term, document) straight out of a source
    /// segment's posting list — so replaying it occurrence by occurrence
    /// would pay a `BTreeMap<String, _>` descent per TOKEN.  Taking the run
    /// in one call pays one descent per (term, source segment) instead:
    /// measured at roughly half the replay's CPU on a 100 MiB corpus, and it
    /// also moves each posting's position vector in rather than copying it.
    ///
    /// Positions are dropped when this writer omits them.  `term_freq` is
    /// stored as given — the `.post` format records the frequency and the
    /// position count as separate fields, and a merge must reproduce both
    /// exactly as the source segment had them.
    ///
    /// Two obligations on the caller, both of which a merge satisfies by
    /// construction:
    ///
    /// * a document may appear at most ONCE per term across every run (each
    ///   merged ordinal comes from exactly one source document, and a posting
    ///   list holds one entry per document), because this appends without
    ///   coalescing equal doc ids;
    /// * runs may arrive out of doc order — a merged segment interleaves its
    ///   inputs' documents — so [`Self::sort_postings_by_doc`] MUST run before
    ///   `encode_term`.
    pub fn extend_postings(&mut self, term: &str, run: Vec<DecodedPosting>) {
        if run.is_empty() {
            return;
        }
        let store_positions = self.store_positions;
        let convert = move |posting: DecodedPosting| RawPosting {
            doc_id: posting.doc_id,
            term_freq: posting.term_freq,
            positions: if store_positions {
                posting.positions
            } else {
                Vec::new()
            },
        };
        match self.postings.get_mut(term) {
            Some(list) => {
                list.reserve(run.len());
                list.extend(run.into_iter().map(convert));
            }
            None => {
                self.postings
                    .insert(term.to_owned(), run.into_iter().map(convert).collect());
            }
        }
    }

    /// Restore the ascending-doc-id invariant every posting list must hold
    /// before it is encoded.
    ///
    /// The indexing path never needs this: it walks documents in ordinal
    /// order, so each list is built ascending.  The merge path replays
    /// several source segments whose surviving documents interleave in the
    /// merged ordinal space, so a shared term's list arrives as k ascending
    /// runs.  `encode_block_doc_ids` delta-encodes with a plain `-`, which
    /// would underflow on an out-of-order pair.
    ///
    /// `sort_by_key` is the stable, run-detecting sort, so k concatenated
    /// ascending runs cost O(n log k), not O(n log n); lists that are already
    /// ordered are detected by the scan below and never sorted at all.
    pub fn sort_postings_by_doc(&mut self) {
        for list in self.postings.values_mut() {
            if list.windows(2).any(|pair| pair[0].doc_id > pair[1].doc_id) {
                list.sort_by_key(|posting| posting.doc_id);
            }
        }
    }

    /// Direct `(doc_frequency, total_term_frequency)` lookup for ONE term.
    ///
    /// O(log T + postings(term)) — use this in per-term loops.  The segment
    /// writer (`write_field_static`) previously resolved stats via
    /// `term_stats().find(term)`, which walks the term map from the start
    /// *and sums every earlier term's postings* on each call — O(T² × P)
    /// across the write loop.  Invisible on 625-doc flush segments, but a
    /// merged segment over a float field (≈1 distinct term per doc) spun
    /// 100 % CPU for HOURS at 3 M docs, pinning rayon workers and starving
    /// every search + flush behind it (the read-under-write collapse).
    pub fn stats_for(&self, term: &str) -> Option<(u32, u64)> {
        self.postings.get(term).map(|postings| {
            let doc_freq = postings.len() as u32;
            let ttf: u64 = postings.iter().map(|p| p.term_freq as u64).sum();
            (doc_freq, ttf)
        })
    }

    /// Returns an iterator over `(term, doc_frequency, total_term_frequency)`
    /// without consuming self (for building the FST term dictionary).
    pub fn term_stats(&self) -> impl Iterator<Item = (&str, u32, u64)> {
        self.postings.iter().map(|(term, postings)| {
            let doc_freq = postings.len() as u32;
            let ttf: u64 = postings.iter().map(|p| p.term_freq as u64).sum();
            (term.as_str(), doc_freq, ttf)
        })
    }

    /// Encode the posting list for `term` into `output`.
    ///
    /// Returns `(postings_offset, skip_table)` where `postings_offset` is
    /// the byte position of the encoded data within `output` at the time of
    /// writing (caller tracks the global byte offset).
    ///
    /// NOTE: the returned `skip_table` is **not** written into `output` and is
    /// currently discarded by the caller — only the packed blocks and residual
    /// are serialised.  See the module docs' "Skip-list acceleration: NOT
    /// implemented" note.
    pub fn encode_term(&self, term: &str, output: &mut Vec<u8>) -> Option<(u64, Vec<SkipEntry>)> {
        let postings = self.postings.get(term)?;

        let start_offset = output.len() as u64;
        let mut skip_table: Vec<SkipEntry> = Vec::new();
        let mut block_count = 0usize;
        let mut i = 0usize;
        let n = postings.len();
        // Term-frequency elision: df positive integers summing to df iff
        // every one of them is 1.  The reader re-derives this SAME predicate
        // from the `.meta` record (ttf == df), so the decision costs no
        // bytes on disk and the two sides cannot drift.
        let ttf: u64 = postings.iter().map(|p| p.term_freq as u64).sum();
        let freq_omitted = self.store_positions && ttf == n as u64;
        // Track the last doc_id written, so that delta[0] of the next block
        // is the gap from the previous block's final doc.  The reader
        // (`decode_next_full_block`) assumes that the first delta in each
        // block is relative to `last_doc_id`, not absolute.
        let mut prev_block_last_doc_id: u32 = 0;

        while i + BLOCK_SIZE <= n {
            // Full block
            let block = &postings[i..i + BLOCK_SIZE];

            if block_count.is_multiple_of(SKIP_INTERVAL) {
                skip_table.push(SkipEntry {
                    max_doc_id: block[BLOCK_SIZE - 1].doc_id,
                    byte_offset: (output.len() - start_offset as usize) as u32,
                });
            }

            encode_block_doc_ids(block, output, prev_block_last_doc_id);
            if self.store_positions && !freq_omitted {
                encode_block_freqs(block, output);
            }
            if self.store_positions {
                encode_block_positions(block, output);
            }
            // docs-only mode: emit nothing after the packed doc-id block.
            // The reader is told about the mode via the field meta and
            // skips the freq/position decode paths entirely.

            prev_block_last_doc_id = block[BLOCK_SIZE - 1].doc_id;
            i += BLOCK_SIZE;
            block_count += 1;
        }

        // Residual (< BLOCK_SIZE docs) — delta-encoded from the last full
        // block's final doc_id as well.
        if i < n {
            let residual = &postings[i..];
            encode_residual(
                residual,
                output,
                prev_block_last_doc_id,
                self.store_positions,
                freq_omitted,
            );
        }

        Some((start_offset, skip_table))
    }

    pub fn terms(&self) -> impl Iterator<Item = &str> {
        self.postings.keys().map(|s| s.as_str())
    }

    pub fn is_empty(&self) -> bool {
        self.postings.is_empty()
    }
}

impl Default for PostingsWriter {
    fn default() -> Self {
        Self::new()
    }
}

// ── Block encoding helpers ────────────────────────────────────────────────────

/// Width at or below which a block always takes the frame-of-reference
/// form, even when subtracting `min` would not narrow the width.
///
/// The whole-file zstd envelope is the second compression stage, and the
/// two stages interact in opposite directions by block width (measured on
/// the 100k `benchmarks/index-size` harness, A/B against both always-FOR
/// and never-FOR-at-equal-width encoders):
///
/// * NARROW blocks (≤ 4 bits): the packed payload is a short, highly
///   regular bit pattern.  FOR normalises level-shifted repeats — freqs
///   5/6 and freqs 9/10 both pack to the same `[0,1,0,1,…]` lanes — so
///   equal payloads recur across blocks and zstd matches them exactly.
///   Skipping the subtraction at equal width cost `body.post` 16 KB.
/// * WIDE blocks: the lanes are quasi-random bits, so the only cross-block
///   repetition zstd can find is payload EQUALITY, which subtracting a
///   varying per-block `min` destroys.  FOR-at-equal-width inflated the
///   compressed `top_doc` field 12.7 % while its uncompressed stream
///   shrank — pure post-compression loss.
const ZPS2_FOR_MAX_EQUAL_WIDTH: u8 = 4;

/// Bit-pack a 128-element `u32` array into the output buffer in the ZPS2
/// framing: `[width: u8][min: vbyte][payload]` with the payload omitted
/// entirely when every lane equals `min` (width 0).  Frame-of-reference
/// subtracts `min` first, so the width tracks the block's SPREAD, not its
/// maximum — a block of freqs 100..=110 packs at 4 bits, not 7.
fn pack_u32_block_v2(values: &[u32; BLOCK_SIZE], output: &mut Vec<u8>) {
    use bitpacking::BitPacker;
    let min = *values.iter().min().unwrap_or(&0);
    let max = *values.iter().max().unwrap_or(&0);
    let spread = max - min;

    if spread == 0 {
        output.push(0u8);
        vbyte_encode(min, output);
        return;
    }

    let num_bits_framed = (32 - spread.leading_zeros()) as u8;
    let num_bits_raw = (32 - max.leading_zeros()) as u8; // 1..=32, max > 0 here
    let (min, num_bits) =
        if num_bits_framed < num_bits_raw || num_bits_raw <= ZPS2_FOR_MAX_EQUAL_WIDTH {
            (min, num_bits_framed)
        } else {
            (0, num_bits_raw)
        };
    output.push(num_bits);
    vbyte_encode(min, output);

    let mut lanes = [0u32; BLOCK_SIZE];
    for (lane, &value) in lanes.iter_mut().zip(values.iter()) {
        *lane = value - min;
    }
    // bitpacking::BitPacker4x::BLOCK_LEN == 128; byte_len is derived on read.
    let byte_len = BLOCK_SIZE * num_bits as usize / 8;
    let mut compressed = vec![0u8; byte_len];
    bitpacking::BitPacker4x::new().compress(&lanes, &mut compressed, num_bits);
    output.extend_from_slice(&compressed);
}

/// Decode a 128-element block previously written by `pack_u32_block_v2`.
/// Reads the cursor forward past the data and fills `out`.
fn unpack_u32_block_v2(
    data: &[u8],
    cursor: &mut Cursor<&[u8]>,
    out: &mut [u32; BLOCK_SIZE],
) -> io::Result<()> {
    use bitpacking::BitPacker;
    let num_bits = cursor.read_u8()?;
    let min = vbyte_decode(cursor)?;
    if num_bits == 0 {
        *out = [min; BLOCK_SIZE];
        return Ok(());
    }
    if num_bits > 32 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            "postings block: invalid bit width",
        ));
    }
    let byte_len = BLOCK_SIZE * num_bits as usize / 8;
    let start = cursor.position() as usize;
    let end = start + byte_len;
    if end > data.len() {
        return Err(io::Error::new(
            io::ErrorKind::UnexpectedEof,
            "postings data truncated",
        ));
    }
    bitpacking::BitPacker4x::new().decompress(&data[start..end], out, num_bits);
    for value in out.iter_mut() {
        *value = value.wrapping_add(min);
    }
    cursor.set_position(end as u64);
    Ok(())
}

/// Decode a 128-element block in the legacy ZPS1 framing
/// `[num_bits ≥ 1][u32 byte_len][payload]`.  Old segments stay readable.
fn unpack_u32_block_v1(
    data: &[u8],
    cursor: &mut Cursor<&[u8]>,
    out: &mut [u32; BLOCK_SIZE],
) -> io::Result<()> {
    use bitpacking::BitPacker;
    let num_bits = cursor.read_u8()?;
    let byte_len = cursor.read_u32::<LittleEndian>()? as usize;
    let start = cursor.position() as usize;
    let end = start + byte_len;
    if end > data.len() {
        return Err(io::Error::new(
            io::ErrorKind::UnexpectedEof,
            "postings data truncated",
        ));
    }
    let compressed = &data[start..end];
    bitpacking::BitPacker4x::new().decompress(compressed, out, num_bits);
    cursor.set_position(end as u64);
    Ok(())
}

fn encode_block_doc_ids(block: &[RawPosting], output: &mut Vec<u8>, prev_last_doc_id: u32) {
    debug_assert_eq!(block.len(), BLOCK_SIZE);

    // Delta-encode doc IDs.  The first delta is relative to the previous
    // block's final doc_id (or 0 for the very first block) so the reader
    // can reconstruct absolute positions by running-sum across blocks.
    let mut deltas = [0u32; BLOCK_SIZE];
    deltas[0] = block[0].doc_id - prev_last_doc_id;
    for j in 1..BLOCK_SIZE {
        deltas[j] = block[j].doc_id - block[j - 1].doc_id;
    }

    pack_u32_block_v2(&deltas, output);
}

fn encode_block_freqs(block: &[RawPosting], output: &mut Vec<u8>) {
    debug_assert_eq!(block.len(), BLOCK_SIZE);

    let mut freqs = [0u32; BLOCK_SIZE];
    for (i, p) in block.iter().enumerate() {
        freqs[i] = p.term_freq;
    }

    pack_u32_block_v2(&freqs, output);
}

fn encode_block_positions(block: &[RawPosting], output: &mut Vec<u8>) {
    // Positions: variable-byte encode per-document, delta within document.
    // No length prefix — the reader decodes exactly BLOCK_SIZE documents'
    // (count + deltas) groups, which pins the stream's end; the u32 the old
    // framing spent per block was information the structure already had.
    for posting in block {
        vbyte_encode(posting.positions.len() as u32, output);
        let mut prev = 0u32;
        for &pos in &posting.positions {
            vbyte_encode(pos - prev, output);
            prev = pos;
        }
    }
}

fn encode_residual(
    residual: &[RawPosting],
    output: &mut Vec<u8>,
    prev_last_doc_id: u32,
    store_positions: bool,
    freq_omitted: bool,
) {
    // Mark as residual with a sentinel: count byte
    output.push(residual.len() as u8);

    // The residual continues the delta chain from the last full block.
    let mut prev_doc = prev_last_doc_id;
    for posting in residual {
        let delta = posting.doc_id - prev_doc;
        prev_doc = posting.doc_id;
        vbyte_encode(delta, output);

        // docs-only mode: skip freq and positions.  Reader synthesises
        // term_freq = 1 when decoding this field.  `freq_omitted` is the
        // positioned variant of the same elision — a term with ttf == df
        // has term_freq 1 everywhere, so there is nothing to store.
        if store_positions && !freq_omitted {
            vbyte_encode(posting.term_freq, output);
        }
        if store_positions {
            vbyte_encode(posting.positions.len() as u32, output);
            let mut prev_pos = 0u32;
            for &pos in &posting.positions {
                vbyte_encode(pos - prev_pos, output);
                prev_pos = pos;
            }
        }
    }
}

// ── Variable-byte encoding ────────────────────────────────────────────────────

/// Encodes `value` as a variable-byte integer into `buf`.
pub fn vbyte_encode(mut value: u32, buf: &mut Vec<u8>) {
    loop {
        let byte = (value & 0x7F) as u8;
        value >>= 7;
        if value == 0 {
            buf.push(byte | 0x80); // high bit = last byte
            break;
        } else {
            buf.push(byte);
        }
    }
}

/// Decodes a variable-byte integer from `cursor`.
pub fn vbyte_decode(cursor: &mut Cursor<&[u8]>) -> io::Result<u32> {
    let mut result = 0u32;
    let mut shift = 0u32;
    loop {
        let byte = cursor.read_u8()?;
        result |= ((byte & 0x7F) as u32) << shift;
        if byte & 0x80 != 0 {
            return Ok(result);
        }
        shift += 7;
        if shift >= 35 {
            return Err(io::Error::new(io::ErrorKind::InvalidData, "vbyte overflow"));
        }
    }
}

/// Encodes `value` as a variable-byte `u64` into `buf`.
///
/// Same convention as [`vbyte_encode`] (high bit set on the final byte) so
/// the pair is self-consistent; this is the wider lane the `.meta` ZFM5
/// record streams need, where `total_term_frequency` and `postings_offset`
/// exceed the `u32` vbyte range on multi-GB `.post` files.
pub fn uvarint_encode(mut value: u64, buf: &mut Vec<u8>) {
    loop {
        let byte = (value & 0x7F) as u8;
        value >>= 7;
        if value == 0 {
            buf.push(byte | 0x80); // high bit = last byte
            break;
        } else {
            buf.push(byte);
        }
    }
}

/// Decodes a variable-byte `u64` from `cursor`.
pub fn uvarint_decode(cursor: &mut Cursor<&[u8]>) -> io::Result<u64> {
    let mut result = 0u64;
    let mut shift = 0u32;
    loop {
        let byte = cursor.read_u8()?;
        result |= ((byte & 0x7F) as u64) << shift;
        if byte & 0x80 != 0 {
            return Ok(result);
        }
        shift += 7;
        if shift >= 70 {
            return Err(io::Error::new(
                io::ErrorKind::InvalidData,
                "uvarint overflow",
            ));
        }
    }
}

/// Decode one document's position group — a vbyte count followed by that
/// many delta-encoded positions.
fn decode_position_group(cursor: &mut Cursor<&[u8]>) -> io::Result<Vec<u32>> {
    let count = vbyte_decode(cursor)? as usize;
    let mut positions = Vec::with_capacity(count);
    let mut prev = 0u32;
    for _ in 0..count {
        let delta = vbyte_decode(cursor)?;
        prev += delta;
        positions.push(prev);
    }
    Ok(positions)
}

// ── PostingsReader ────────────────────────────────────────────────────────────

/// Inner framing of a term's postings blob — set by the `.post` envelope
/// magic the segment was written with (see `xerj_fts::index`).
///
/// `V2` is the ZPS2 framing (frame-of-reference blocks, derived lengths,
/// width-0 constant blocks).  `freq_omitted` marks a positioned term whose
/// `ttf == df`, whose freq stream was therefore never written; the reader
/// synthesises `term_freq = 1`, exactly as docs-only fields always have.
///
/// `V1` is the legacy ZPS1 framing; segments written before the ZPS2 bump
/// decode through it unchanged.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum PostCodec {
    V1,
    V2 { freq_omitted: bool },
}

impl PostCodec {
    /// The codec decision a ZPS2 reader makes for one term from facts the
    /// `.meta` record already carries.  The writer applies the identical
    /// predicate at encode time, so the two cannot drift.
    pub fn v2_for(has_positions: bool, total_term_frequency: u64, doc_frequency: u32) -> Self {
        PostCodec::V2 {
            freq_omitted: has_positions && total_term_frequency == doc_frequency as u64,
        }
    }
}

/// Iterator over decoded doc IDs from a posting list.
pub struct PostingsReader<'a> {
    data: &'a [u8],
    cursor: Cursor<&'a [u8]>,
    /// Total doc count for this term (determines how many blocks to decode).
    doc_frequency: u32,
    /// Docs consumed so far.
    docs_read: u32,
    /// Current block's decoded doc IDs (up to BLOCK_SIZE).
    block_docs: Vec<u32>,
    /// Current block's decoded term freqs.
    block_freqs: Vec<u32>,
    /// Current block's decoded positions per doc.
    block_positions: Vec<Vec<u32>>,
    /// Index within the current block.
    block_idx: usize,
    /// Number of full blocks.
    num_full_blocks: usize,
    /// Full blocks processed so far.
    blocks_processed: usize,
    /// Whether we are in the residual section.
    in_residual: bool,
    /// Residual entries (decoded all at once).
    residual: Vec<DecodedPosting>,
    /// Index within the residual.
    residual_idx: usize,
    /// Last doc ID seen (for delta decoding across blocks).
    last_doc_id: u32,
    /// `true` when the posting list contains freq + position blocks.
    /// `false` for docs-only fields (keyword, numeric, ip), in which
    /// case the reader synthesises `term_freq = 1` and empty positions
    /// for every posting.
    has_positions: bool,
    /// Inner block framing (ZPS1 legacy vs ZPS2) + freq-elision marker.
    codec: PostCodec,
}

#[derive(Debug, Clone)]
pub struct DecodedPosting {
    pub doc_id: u32,
    pub term_freq: u32,
    pub positions: Vec<u32>,
}

impl<'a> PostingsReader<'a> {
    /// Create a reader over the raw posting bytes for one term.
    /// Defaults to the positioned format.  For docs-only fields use
    /// [`PostingsReader::new_with_positions`] with `has_positions =
    /// false` — the reader will skip freq / position decoding and
    /// synthesise `term_freq = 1` for every posting.
    pub fn new(data: &'a [u8], doc_frequency: u32) -> Self {
        Self::new_with_positions(data, doc_frequency, true)
    }

    /// Like [`new`] but explicit about whether the posting list carries
    /// term frequencies + positions.
    ///
    /// This constructs the **legacy ZPS1** reader.  Segments written with
    /// the ZPS2 envelope must go through [`Self::new_with_codec`] — the
    /// block framing differs — which is what `FtsIndexReader`'s postings
    /// factory does for every caller.
    pub fn new_with_positions(data: &'a [u8], doc_frequency: u32, has_positions: bool) -> Self {
        Self::new_with_codec(data, doc_frequency, has_positions, PostCodec::V1)
    }

    /// Like [`new_with_positions`] but explicit about the inner block
    /// framing, so a ZPS2 segment (FOR blocks, derived lengths, optional
    /// freq elision) and a legacy ZPS1 segment decode through the same
    /// iterator.
    pub fn new_with_codec(
        data: &'a [u8],
        doc_frequency: u32,
        has_positions: bool,
        codec: PostCodec,
    ) -> Self {
        let num_full_blocks = doc_frequency as usize / BLOCK_SIZE;
        Self {
            data,
            cursor: Cursor::new(data),
            doc_frequency,
            docs_read: 0,
            block_docs: Vec::new(),
            block_freqs: Vec::new(),
            block_positions: Vec::new(),
            block_idx: 0,
            num_full_blocks,
            blocks_processed: 0,
            in_residual: false,
            residual: Vec::new(),
            residual_idx: 0,
            last_doc_id: 0,
            has_positions,
            codec,
        }
    }

    /// Advance to the next posting. Returns `None` when exhausted.
    ///
    /// An inherent cursor method rather than an `Iterator` impl: decoding
    /// borrows the reader's internal buffers, which doesn't fit `Iterator`'s
    /// `Item` lifetime, so `next` stays inherent by design.
    #[allow(clippy::should_implement_trait)]
    pub fn next(&mut self) -> Option<DecodedPosting> {
        if self.docs_read >= self.doc_frequency {
            return None;
        }

        // Need to load the next block?
        if !self.in_residual && self.block_idx >= self.block_docs.len() {
            if self.blocks_processed < self.num_full_blocks {
                self.decode_next_full_block().ok()?;
            } else {
                // Switch to residual
                self.decode_residual().ok()?;
                self.in_residual = true;
            }
        }

        if self.in_residual {
            if self.residual_idx >= self.residual.len() {
                return None;
            }
            let posting = self.residual[self.residual_idx].clone();
            self.residual_idx += 1;
            self.docs_read += 1;
            return Some(posting);
        }

        let doc_id = self.block_docs[self.block_idx];
        let term_freq = self.block_freqs[self.block_idx];
        let positions = self.block_positions[self.block_idx].clone();
        self.block_idx += 1;
        self.docs_read += 1;

        Some(DecodedPosting {
            doc_id,
            term_freq,
            positions,
        })
    }

    fn decode_next_full_block(&mut self) -> io::Result<()> {
        // Read doc_id deltas
        let mut deltas = [0u32; BLOCK_SIZE];
        match self.codec {
            PostCodec::V1 => unpack_u32_block_v1(self.data, &mut self.cursor, &mut deltas)?,
            PostCodec::V2 { .. } => unpack_u32_block_v2(self.data, &mut self.cursor, &mut deltas)?,
        }

        // Reconstruct absolute doc IDs
        let mut doc_ids = vec![0u32; BLOCK_SIZE];
        doc_ids[0] = self.last_doc_id + deltas[0];
        for j in 1..BLOCK_SIZE {
            doc_ids[j] = doc_ids[j - 1] + deltas[j];
        }
        self.last_doc_id = doc_ids[BLOCK_SIZE - 1];

        // A positioned term whose freq stream was elided (ttf == df) or a
        // docs-only field: every frequency is 1 by construction, so the
        // block's freq bytes simply are not there.
        let freq_stored = self.has_positions && !self.freq_omitted();
        let (freqs, positions) = if self.has_positions {
            let freqs = if freq_stored {
                let mut freqs = [0u32; BLOCK_SIZE];
                match self.codec {
                    PostCodec::V1 => unpack_u32_block_v1(self.data, &mut self.cursor, &mut freqs)?,
                    PostCodec::V2 { .. } => {
                        unpack_u32_block_v2(self.data, &mut self.cursor, &mut freqs)?
                    }
                }
                freqs.to_vec()
            } else {
                vec![1u32; BLOCK_SIZE]
            };
            (freqs, self.decode_block_positions()?)
        } else {
            // Docs-only mode: synthesise freq=1 and empty positions.
            let freqs = vec![1u32; BLOCK_SIZE];
            let positions: Vec<Vec<u32>> = vec![Vec::new(); BLOCK_SIZE];
            (freqs, positions)
        };

        self.block_docs = doc_ids.to_vec();
        self.block_freqs = freqs;
        self.block_positions = positions;
        self.block_idx = 0;
        self.blocks_processed += 1;

        Ok(())
    }

    /// `true` when this term's freq stream was never written — either a
    /// docs-only field or (ZPS2) a positioned term with `ttf == df`.
    fn freq_omitted(&self) -> bool {
        match self.codec {
            PostCodec::V1 => false,
            PostCodec::V2 { freq_omitted } => freq_omitted || !self.has_positions,
        }
    }

    /// Decode one block's positions (BLOCK_SIZE documents' worth of
    /// `count + deltas` vbyte groups).
    ///
    /// ZPS1 prefixes the stream with a `u32` byte length and the groups
    /// decode from that slice; ZPS2 dropped the prefix — the group count is
    /// structurally exactly BLOCK_SIZE, so the groups decode straight off
    /// the main cursor and pin its end themselves.
    fn decode_block_positions(&mut self) -> io::Result<Vec<Vec<u32>>> {
        let mut positions: Vec<Vec<u32>> = Vec::with_capacity(BLOCK_SIZE);
        match self.codec {
            PostCodec::V1 => {
                let pos_byte_len = self.cursor.read_u32::<LittleEndian>()? as usize;
                let pos_start = self.cursor.position() as usize;
                let pos_end = pos_start + pos_byte_len;
                if pos_end > self.data.len() {
                    return Err(io::Error::new(
                        io::ErrorKind::UnexpectedEof,
                        "postings positions truncated",
                    ));
                }
                let mut pos_cursor = Cursor::new(&self.data[pos_start..pos_end]);
                for _ in 0..BLOCK_SIZE {
                    positions.push(decode_position_group(&mut pos_cursor)?);
                }
                self.cursor.set_position(pos_end as u64);
            }
            PostCodec::V2 { .. } => {
                for _ in 0..BLOCK_SIZE {
                    positions.push(decode_position_group(&mut self.cursor)?);
                }
            }
        }
        Ok(positions)
    }

    fn decode_residual(&mut self) -> io::Result<()> {
        let count = self.cursor.read_u8()? as usize;
        let mut result = Vec::with_capacity(count);
        let mut prev_doc = self.last_doc_id;

        for _ in 0..count {
            let doc_delta = vbyte_decode(&mut self.cursor)?;
            let doc_id = prev_doc + doc_delta;
            prev_doc = doc_id;

            let (term_freq, positions) = if self.has_positions {
                // An elided freq stream (ttf == df) means every posting's
                // frequency is 1 — the residual's freq vbytes were never
                // written either, mirroring `encode_residual`.
                let term_freq = if self.freq_omitted() {
                    1u32
                } else {
                    vbyte_decode(&mut self.cursor)?
                };
                let pos_count = vbyte_decode(&mut self.cursor)? as usize;
                let mut positions = Vec::with_capacity(pos_count);
                let mut prev_pos = 0u32;
                for _ in 0..pos_count {
                    let delta = vbyte_decode(&mut self.cursor)?;
                    prev_pos += delta;
                    positions.push(prev_pos);
                }
                (term_freq, positions)
            } else {
                (1u32, Vec::new())
            };

            result.push(DecodedPosting {
                doc_id,
                term_freq,
                positions,
            });
        }

        self.residual = result;
        self.residual_idx = 0;
        Ok(())
    }

    /// Advance to the first posting whose `doc_id >= target`.
    ///
    /// This is a **linear scan** — it calls [`Self::next`] until a doc_id at or
    /// past `target` is reached (or the list is exhausted).  There is no
    /// skip-list acceleration: the `.post` blob carries no on-disk skip table
    /// (see the module docs), so no block-level seek is possible.  Correct, but
    /// O(n) in the number of postings skipped.
    pub fn advance_to(&mut self, target: u32) -> Option<DecodedPosting> {
        loop {
            match self.next() {
                Some(p) if p.doc_id >= target => return Some(p),
                Some(_) => continue,
                None => return None,
            }
        }
    }
}

// ── Tests ─────────────────────────────────────────────────────────────────────

#[cfg(test)]
mod tests {
    use super::*;

    fn build_postings(pairs: &[(u32, u32, &[u32])]) -> (Vec<u8>, u32, u64) {
        let mut writer = PostingsWriter::new();
        for &(doc_id, _freq, positions) in pairs {
            for &pos in positions {
                writer.add_occurrence("test", doc_id, pos);
            }
        }
        let mut data = Vec::new();
        writer.encode_term("test", &mut data);
        let doc_freq = pairs.len() as u32;
        let ttf: u64 = pairs.iter().map(|&(_, freq, _)| freq as u64).sum();
        (data, doc_freq, ttf)
    }

    /// The reader a ZPS2 segment constructs for writer output: V2 framing
    /// with the freq-elision predicate the writer itself applied.
    fn v2_reader(data: &[u8], doc_freq: u32, ttf: u64) -> PostingsReader<'_> {
        PostingsReader::new_with_codec(data, doc_freq, true, PostCodec::v2_for(true, ttf, doc_freq))
    }

    #[test]
    fn roundtrip_small_posting_list() {
        let postings: Vec<(u32, u32, &[u32])> =
            vec![(1, 2, &[0, 5]), (3, 1, &[2]), (7, 3, &[0, 1, 2])];
        let (data, doc_freq, ttf) = build_postings(&postings);
        let mut reader = v2_reader(&data, doc_freq, ttf);

        let p = reader.next().unwrap();
        assert_eq!(p.doc_id, 1);
        assert_eq!(p.term_freq, 2);
        assert_eq!(p.positions, vec![0, 5]);

        let p = reader.next().unwrap();
        assert_eq!(p.doc_id, 3);

        let p = reader.next().unwrap();
        assert_eq!(p.doc_id, 7);
        assert_eq!(p.term_freq, 3);

        assert!(reader.next().is_none());
    }

    #[test]
    fn roundtrip_full_block() {
        // Create exactly 128 docs
        let mut writer = PostingsWriter::new();
        for i in 0u32..128 {
            writer.add_occurrence("term", i * 2, i); // even doc ids, one position each
        }
        let mut data = Vec::new();
        writer.encode_term("term", &mut data);

        // Every frequency is 1 => ttf == df => the freq stream is elided and
        // this exercises the synthesised-freq path on a full block.
        let mut reader = v2_reader(&data, 128, 128);
        let mut last_doc = u32::MAX;
        let mut count = 0u32;
        while let Some(p) = reader.next() {
            assert!(
                p.doc_id < last_doc || last_doc == u32::MAX || p.doc_id > last_doc,
                "doc IDs must be monotonically increasing"
            );
            if last_doc != u32::MAX {
                assert!(p.doc_id > last_doc);
            }
            assert_eq!(p.term_freq, 1, "elided freqs decode as 1");
            assert_eq!(p.positions, vec![count], "positions still round-trip");
            last_doc = p.doc_id;
            count += 1;
        }
        assert_eq!(count, 128);
    }

    #[test]
    fn vbyte_roundtrip() {
        for &v in &[0u32, 1, 127, 128, 255, 16383, 16384, u32::MAX / 2] {
            let mut buf = Vec::new();
            vbyte_encode(v, &mut buf);
            let decoded = vbyte_decode(&mut Cursor::new(buf.as_slice())).unwrap();
            assert_eq!(decoded, v, "vbyte failed for {}", v);
        }
    }

    /// `advance_to` is a *linear* scan (there is no on-disk skip table — see
    /// the module docs).  This asserts it still lands on the correct posting:
    /// the first doc_id at or past the target, across a block boundary, and
    /// that it returns `None` once the list is exhausted.
    #[test]
    fn advance_to_linear_scans_correctly() {
        // 200 docs => one full 128-doc block + a 72-doc residual.
        // doc_id = i * 3, so ids are 0, 3, 6, … 597.
        let mut writer = PostingsWriter::new();
        for i in 0u32..200 {
            writer.add_occurrence("term", i * 3, i);
        }
        let mut data = Vec::new();
        writer.encode_term("term", &mut data);

        // Target lands exactly on a doc (150 = 50 * 3), inside the first block.
        let mut reader = v2_reader(&data, 200, 200);
        let hit = reader.advance_to(150).expect("expected a hit at/after 150");
        assert_eq!(hit.doc_id, 150, "must return the exact match when present");

        // Target between two docs (301 is not a multiple of 3) crossing into
        // the residual section => first doc strictly greater is 303.
        let mut reader = v2_reader(&data, 200, 200);
        let hit = reader.advance_to(301).expect("expected a hit at/after 301");
        assert_eq!(hit.doc_id, 303, "must return the first doc_id >= target");

        // Target past the end yields None.
        let mut reader = v2_reader(&data, 200, 200);
        assert!(
            reader.advance_to(600).is_none(),
            "advance past the last doc must exhaust the reader"
        );
    }

    /// The writer always emits the ZPS2 framing now; a hand-built legacy
    /// ZPS1 blob must still decode through `PostCodec::V1`.  The fixture is
    /// one docs-only full block whose lanes are [0, 1, 1, …] — the first
    /// delta is the gap from the previous block's last doc (0), so the
    /// lanes reconstruct docs 0..=127.
    #[test]
    fn zps1_legacy_block_bytes_still_decode() {
        let mut data: Vec<u8> = Vec::new();
        data.push(1u8); // num_bits = 1
        data.extend_from_slice(&16u32.to_le_bytes()); // byte_len = 128 * 1 / 8
                                                      // 1-bit lanes: lane 0 = 0, lanes 1..=127 = 1 => 0xFE then 0xFF × 15.
        data.push(0xFE);
        data.extend(std::iter::repeat_n(0xFFu8, 15));
        // No residual: df is an exact multiple of BLOCK_SIZE.

        let mut reader = PostingsReader::new_with_positions(&data, 128, false);
        let mut expected = 0u32;
        let mut count = 0u32;
        while let Some(p) = reader.next() {
            assert_eq!(
                p.doc_id, expected,
                "contiguous deltas of 1 reconstruct 0..127"
            );
            assert_eq!(p.term_freq, 1, "docs-only synthesises freq 1");
            expected += 1;
            count += 1;
        }
        assert_eq!(count, 128);
    }

    /// A ZPS2 constant block — dense doc IDs, so every delta is 1 — encodes
    /// to `[width 0][vbyte 1]` and nothing else, where ZPS1 paid
    /// 5 header/payload-formality bytes plus a 16-byte payload.
    #[test]
    fn zps2_constant_block_collapses_to_width_zero() {
        let mut writer = PostingsWriter::new();
        for i in 1u32..=128 {
            writer.add_occurrence("term", i, i);
        }
        let mut data = Vec::new();
        writer.encode_term("term", &mut data);

        assert_eq!(&data[..2], &[0u8, 0x81], "width-0 block then vbyte(1)");
        // Positions (128 groups of count=1, delta=i+1) dominate what is left;
        // the doc-id stream itself is over after two bytes.
        assert!(
            data.len() < 4 * 128,
            "whole blob must stay well under the old framing's ~21 B/doc block"
        );

        let mut reader = v2_reader(&data, 128, 128);
        for expected in 1u32..=128 {
            let p = reader.next().expect("128 postings");
            assert_eq!(p.doc_id, expected);
        }
        assert!(reader.next().is_none());
    }

    /// Frame-of-reference packs the block's SPREAD, not its maximum: a freq
    /// stream of 100..=101 needs 7 bits raw, 1 bit after subtracting min.
    #[test]
    fn zps2_for_packs_spread_not_max() {
        let mut writer = PostingsWriter::new();
        for i in 0u32..128 {
            // doc i gets freq alternating 100/101 via that many occurrences
            // of a distinct position count: freq = 100 + (i % 2).
            let freq = 100 + (i % 2);
            for pos in 0u32..freq {
                writer.add_occurrence("term", i * 10, pos);
            }
        }
        let mut data = Vec::new();
        writer.encode_term("term", &mut data);

        // Doc-id deltas: first 10 (0-0), then 10 repeatedly => constant 10
        // after the first lane… all lanes are 10 except lane 0 which is
        // doc 0 => delta 0? No: block[0].doc_id - 0 = 0, then +10 each.
        // spread = 10 => width 4.  Freq lanes: min 100, spread 1 => width 1.
        // Walk: [width][vbyte min][payload] for docids then freqs.
        let mut cursor = Cursor::new(data.as_slice());
        let docid_width = cursor.read_u8().unwrap();
        let docid_min = vbyte_decode(&mut cursor).unwrap();
        assert_eq!((docid_width, docid_min), (4u8, 0u32), "docid lanes 0..=10");
        cursor.set_position(cursor.position() + 128 * 4 / 8);

        let freq_width = cursor.read_u8().unwrap();
        let freq_min = vbyte_decode(&mut cursor).unwrap();
        assert_eq!((freq_width, freq_min), (1u8, 100u32), "freq lanes 100/101");

        let ttf: u64 = (0..128u32).map(|i| (100 + (i % 2)) as u64).sum();
        let df = 128u32;
        let mut reader = v2_reader(&data, df, ttf);
        for i in 0u32..128 {
            let p = reader.next().expect("128 postings");
            assert_eq!(p.doc_id, i * 10);
            assert_eq!(p.term_freq, 100 + (i % 2));
            assert_eq!(p.positions.len(), (100 + (i % 2)) as usize);
        }
        assert!(reader.next().is_none());
    }

    /// A WIDE block whose min and max share a binade gains no width from the
    /// frame subtraction — deltas [1, 100, 100, …] need 7 bits either way —
    /// so the encoder must emit `min = 0` with raw lanes, keeping the
    /// payload bytes identical to what ZPS1 carried (the outer zstd pass
    /// matches them across blocks; FOR-always measurably inflated the
    /// compressed `top_doc` field on the 100k harness).
    #[test]
    fn zps2_skips_for_on_wide_equal_width_blocks() {
        let mut writer = PostingsWriter::new();
        // doc 1 then gaps of 100: lanes [1, 100, 100, …], min 1, max 100 —
        // 7 bits framed (spread 99) and 7 bits raw, and 7 > the narrow cap.
        let mut doc = 1u32;
        for i in 0u32..128 {
            writer.add_occurrence("term", doc, i);
            doc += 100;
        }
        let mut data = Vec::new();
        writer.encode_term("term", &mut data);

        // [width 7][vbyte 0] — NOT [width 7][vbyte 1]: same width either
        // way and too wide for FOR's pattern-normalisation to pay, so the
        // raw lanes are kept for zstd to match.
        assert_eq!(&data[..2], &[7u8, 0x80], "wide equal-width block stays raw");

        let mut reader = v2_reader(&data, 128, 128);
        let mut expected = 1u32;
        for _ in 0..128 {
            let p = reader.next().expect("128 postings");
            assert_eq!(p.doc_id, expected);
            expected += 100;
        }
        assert!(reader.next().is_none());
    }

    /// The NARROW counterpart: an equal-width block at or below the cap
    /// takes the frame even though the width is unchanged, because FOR
    /// normalises level-shifted repeats into identical payloads.  Deltas
    /// [1, 15, 15, …] are 4 bits framed or raw — the frame is chosen.
    #[test]
    fn zps2_frames_narrow_equal_width_blocks() {
        let mut writer = PostingsWriter::new();
        let mut doc = 1u32;
        for i in 0u32..128 {
            writer.add_occurrence("term", doc, i);
            doc += 15;
        }
        let mut data = Vec::new();
        writer.encode_term("term", &mut data);

        assert_eq!(
            &data[..2],
            &[4u8, 0x81],
            "narrow equal-width block takes the frame (min = 1)"
        );

        let mut reader = v2_reader(&data, 128, 128);
        let mut expected = 1u32;
        for _ in 0..128 {
            let p = reader.next().expect("128 postings");
            assert_eq!(p.doc_id, expected);
            expected += 15;
        }
        assert!(reader.next().is_none());
    }

    /// Two terms over the same documents: one all freq 1 (ttf == df), one
    /// with a single freq-2 document.  The elided term's blob must be
    /// strictly smaller and both must round-trip with exact term_freqs.
    #[test]
    fn freq_elision_shrinks_and_roundtrips() {
        const ONE_POSITION: &[u32] = &[0];
        const TWO_POSITIONS: &[u32] = &[0, 1];
        let elided: Vec<(u32, u32, &[u32])> = (0u32..300).map(|i| (i, 1, ONE_POSITION)).collect();
        let mut repeated = elided.clone();
        repeated[5] = (5, 2, TWO_POSITIONS);

        let (data_elided, df_e, ttf_e) = build_postings(&elided);
        let (data_repeated, df_r, ttf_r) = build_postings(&repeated);
        assert_eq!((df_e, ttf_e), (300, 300));
        assert_eq!((df_r, ttf_r), (300, 301));
        assert!(
            data_elided.len() < data_repeated.len(),
            "elided freq stream must save bytes ({} vs {})",
            data_elided.len(),
            data_repeated.len()
        );

        let mut reader = v2_reader(&data_elided, df_e, ttf_e);
        for i in 0u32..300 {
            let p = reader.next().expect("300 postings");
            assert_eq!(p.term_freq, 1, "elided freqs synthesise 1");
            assert_eq!(p.doc_id, i);
        }
        assert!(reader.next().is_none());

        let mut reader = v2_reader(&data_repeated, df_r, ttf_r);
        for i in 0u32..300 {
            let p = reader.next().expect("300 postings");
            assert_eq!(p.term_freq, if i == 5 { 2 } else { 1 });
        }
        assert!(reader.next().is_none());
    }
}

//! FTS inverted index: writer and reader for one segment.
//!
//! ## On-disk layout
//!
//! For each indexed field `<field-component>` a segment produces four files:
//!
//! ```text
//! seg-<id>.<field-component>.fst       — FST term dictionary
//!                              value = byte offset into .post file
//! seg-<id>.<field-component>.post      — concatenated posting lists
//! seg-<id>.<field-component>.meta      — FieldStats + per-term metadata
//! seg-<id>.<field-component>.norms     — encoded per-doc field lengths
//! seg-<id>.fts-layout-v2               — exact marker when components are encoded
//! seg-<id>.fts-layout-v3               — exact marker when a literal would
//!                                        case-fold into another field on NTFS
//! ```
//!
//! Short portable field names are used literally for on-disk compatibility;
//! all other logical field names map to a bounded digest component. Layout v3
//! also digests a name whose Windows case-identity is not the name itself
//! (`page_Id`, `ı`, `ß`), so two fields cannot share one side-car file.
//!
//! The FST key is the term text (UTF-8 bytes, lexicographically sorted by construction).
//! The FST output value is the byte offset in the `.post` file.
//! `TermPostings` metadata (doc_freq, ttf) is stored in the `.meta` JSON.

use crate::{
    analyzer::AnalyzerRegistry,
    bm25::FieldStats,
    postings::{PostingsWriter, TermPostings},
};
use anyhow::{bail, Context, Result};
use byteorder::{LittleEndian, ReadBytesExt, WriteBytesExt};
use fst::{Map, MapBuilder};
use memmap2::Mmap;
use serde::Deserialize;
use sha2::{Digest, Sha256};
use std::{
    borrow::Cow,
    collections::HashMap,
    fs::{self, File},
    io::{BufWriter, Write},
    path::{Path, PathBuf},
    sync::Arc,
};

/// Longest field name that can remain literal inside an FTS side-car filename.
///
/// The complete filename also carries a segment UUID, separators, an extension,
/// and sometimes `.tmp`. Keeping the user-controlled component at 128 bytes
/// leaves comfortable room below the common 255-byte component limit.
const MAX_LITERAL_FIELD_COMPONENT_BYTES: usize = 128;

/// Namespace for field names that cannot safely be used as portable filesystem
/// components. Literal names in this namespace are encoded too, so a user field
/// cannot alias another field's digest-derived component.
const ENCODED_FIELD_COMPONENT_PREFIX: &str = "__xerj_fts_field_sha256_";

/// Immutable per-segment discriminator for encoded field filename components.
///
/// This name has no FTS side-car extension, so it cannot equal any v1 file:
/// every historical file is `<segment>.<raw-field>.(fst|post|meta|norms)`.
/// It retains the segment prefix so publication manifests, rollback, orphan
/// recovery, and retirement treat it as part of the same artifact family.
const FTS_FILENAME_LAYOUT_V2_MARKER_SUFFIX: &str = "fts-layout-v2";
const FTS_FILENAME_LAYOUT_V2_MARKER_BYTES: &[u8] = b"XERJ_FTS_FILENAME_LAYOUT_V2\n";

/// Layout v3. Same digest function as v2 for names v2 already hashed. Names
/// v2 kept as literals, but which NTFS case-folds onto a different literal,
/// are hashed too. The marker is the only authority: a v2 segment that stored
/// `page_Id` literally must still open as v2.
const FTS_FILENAME_LAYOUT_V3_MARKER_SUFFIX: &str = "fts-layout-v3";
const FTS_FILENAME_LAYOUT_V3_MARKER_BYTES: &[u8] = b"XERJ_FTS_FILENAME_LAYOUT_V3\n";

/// Which filename function a segment's side-cars were written with.
///
/// Chosen from the marker file alone. Existence of a side-car is never
/// evidence: a v1 literal can alias a v2 digest component.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum FilenameLayout {
    /// No marker. Paths are the raw field name when that stays inside the
    /// segment directory.
    Legacy,
    /// `fts-layout-v2`. Unsafe names are SHA-256 components; mixed-case
    /// portable names stay literal.
    Encoded,
    /// `fts-layout-v3`. v2's digests, plus a digest for any remaining literal
    /// whose Windows case-identity is not the field name itself.
    CaseDistinguished,
}

fn segment_filename_layout_v2_marker_path(segment_dir: &Path, segment_id: &str) -> PathBuf {
    segment_dir.join(format!(
        "{segment_id}.{FTS_FILENAME_LAYOUT_V2_MARKER_SUFFIX}"
    ))
}

fn segment_filename_layout_v3_marker_path(segment_dir: &Path, segment_id: &str) -> PathBuf {
    segment_dir.join(format!(
        "{segment_id}.{FTS_FILENAME_LAYOUT_V3_MARKER_SUFFIX}"
    ))
}

enum LayoutMarkerRead {
    Absent,
    Exact,
}

fn read_layout_marker(path: &Path, expected: &[u8]) -> Result<LayoutMarkerRead> {
    match fs::read(path) {
        Ok(bytes) if bytes == expected => Ok(LayoutMarkerRead::Exact),
        Ok(_) => bail!("corrupt FTS filename-layout discriminator {:?}", path),
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(LayoutMarkerRead::Absent),
        Err(error) => Err(error)
            .with_context(|| format!("reading FTS filename-layout discriminator {:?}", path)),
    }
}

/// v3 wins when its marker is present. A corrupt marker fails closed and does
/// not fall through to an older layout. File-family existence is never
/// layout evidence.
fn segment_filename_layout(segment_dir: &Path, segment_id: &str) -> Result<FilenameLayout> {
    let v3 = segment_filename_layout_v3_marker_path(segment_dir, segment_id);
    if matches!(
        read_layout_marker(&v3, FTS_FILENAME_LAYOUT_V3_MARKER_BYTES)?,
        LayoutMarkerRead::Exact
    ) {
        return Ok(FilenameLayout::CaseDistinguished);
    }
    let v2 = segment_filename_layout_v2_marker_path(segment_dir, segment_id);
    if matches!(
        read_layout_marker(&v2, FTS_FILENAME_LAYOUT_V2_MARKER_BYTES)?,
        LayoutMarkerRead::Exact
    ) {
        return Ok(FilenameLayout::Encoded);
    }
    Ok(FilenameLayout::Legacy)
}

/// Per-segment record of the analyzer each field's postings were built with
/// (#937). Written by [`FtsIndexWriter::finish`] as JSON
/// `{"fields":{"<field>":"<analyzer>"}}`, but ONLY when some field was
/// indexed with an analyzer other than `standard` — an index that declares
/// no analyzers produces byte- and directory-identical flushes to a
/// pre-#937 build.
///
/// The consumer is the engine's merge gate (`fts_merge_readers`): a merge
/// may replay input postings verbatim only when they were produced by the
/// same analyzer the merge output would use. Segments written by pre-#937
/// builds have no marker; their text postings are `standard` by
/// construction, which is exactly what absence reports.
const FTS_ANALYZER_MARKER_SUFFIX: &str = "ftsan";

fn segment_analyzer_marker_path(segment_dir: &Path, segment_id: &str) -> PathBuf {
    segment_dir.join(format!("{segment_id}.{FTS_ANALYZER_MARKER_SUFFIX}"))
}

/// The per-field analyzers a segment's FTS side-cars were written with.
///
/// `None` (file absent or unreadable) means "no field deviates from
/// `standard`" — the pre-#937 state. An unreadable marker on a segment
/// that WAS written with a declared analyzer can only come from
/// post-publication corruption; reporting `None` keeps the merge gate
/// conservative in the direction of re-analysis whenever the expected
/// analyzer is not `standard`, and is exactly yesterday's behaviour when
/// it is.
pub fn segment_recorded_analyzers(
    segment_dir: &Path,
    segment_id: &str,
) -> Option<HashMap<String, String>> {
    #[derive(serde::Deserialize)]
    struct Marker {
        fields: HashMap<String, String>,
    }
    let bytes = fs::read(segment_analyzer_marker_path(segment_dir, segment_id)).ok()?;
    let parsed: Marker = serde_json::from_slice(&bytes).ok()?;
    Some(parsed.fields)
}

fn is_windows_reserved_device_name(field: &str) -> bool {
    let stem = field.split('.').next().unwrap_or(field);
    if ["CON", "PRN", "AUX", "NUL"]
        .iter()
        .any(|reserved| stem.eq_ignore_ascii_case(reserved))
    {
        return true;
    }
    let bytes = stem.as_bytes();
    bytes.len() == 4
        && (bytes[..3].eq_ignore_ascii_case(b"COM") || bytes[..3].eq_ignore_ascii_case(b"LPT"))
        && matches!(bytes[3], b'1'..=b'9')
}

/// Return the bounded, portable component used for every side-car of `field`.
///
/// Existing short field names that are portable across supported filesystems
/// remain byte-for-byte compatible with the historical on-disk layout.
/// Everything else is represented by a SHA-256 digest. In particular, path
/// separators, traversal-like names, platform-reserved punctuation, controls,
/// and overlong names can never create a child path or exceed a normal
/// filesystem's component limit. Unicode, `@`, and internal spaces are valid
/// portable literals; trailing spaces and dots are not portable to Windows.
/// Preserving literals also preserves a limitation layout v2 left in place:
/// distinct portable names can alias on a filesystem that case-folds.
/// Layout v3 digests any literal whose Windows case-identity is not the name
/// itself, so `page_Id` and `page_id` (and the NTFS pairs `ı`/`i`, `ß`/`ss`,
/// `ſ`/`s`) cannot share a file. Digest-derived names remain distinct by
/// exact UTF-8 bytes modulo a SHA-256 collision. Unicode normalization
/// (NFC versus NFD) is still not encoded.
fn field_file_component(field: &str) -> Cow<'_, str> {
    if portable_literal_field(field) {
        return Cow::Borrowed(field);
    }
    Cow::Owned(digest_field_component(field))
}

fn portable_literal_field(field: &str) -> bool {
    !field.is_empty()
        && field.len() <= MAX_LITERAL_FIELD_COMPONENT_BYTES
        && field != "."
        && field != ".."
        && !field.starts_with(ENCODED_FIELD_COMPONENT_PREFIX)
        && !is_windows_reserved_device_name(field)
        && !field.ends_with(' ')
        && !field.ends_with('.')
        && field.chars().all(|character| {
            !character.is_control()
                && !matches!(
                    character,
                    '/' | '\\' | '<' | '>' | ':' | '"' | '|' | '?' | '*'
                )
        })
}

fn digest_field_component(field: &str) -> String {
    let digest = Sha256::digest(field.as_bytes());
    format!("{ENCODED_FIELD_COMPONENT_PREFIX}{digest:x}")
}

/// Layout v3 component. Unsafe names hash exactly as in v2 (the digest is of
/// the field's UTF-8 bytes, not of the v2 component). A portable literal is
/// hashed only when NTFS would treat it as the same file as a different
/// spelling.
fn field_file_component_v3(field: &str) -> Cow<'_, str> {
    if field_needs_case_distinguished_component(field) {
        Cow::Owned(digest_field_component(field))
    } else {
        field_file_component(field)
    }
}

/// `true` when v2 would keep `field` as a literal AND that literal's Windows
/// case-identity is a different string.
///
/// The identity is Unicode lowercase plus the NTFS upcase-table exceptions
/// that lowercase does not collapse: U+0131 `ı` → `i`, U+017F `ſ` → `s`,
/// U+212A `K` → `k`, U+00DF `ß` → `ss`. A name that is already that identity
/// (`page_id`, `i`, `ss`) stays a literal. Every other spelling of the same
/// identity is a digest, so the two cannot land on one NTFS file. Hashing the
/// exact bytes also keeps `Page` and `PAGE` apart from each other.
fn field_needs_case_distinguished_component(field: &str) -> bool {
    portable_literal_field(field) && !windows_case_identity_is_self(field)
}

fn windows_case_identity_is_self(field: &str) -> bool {
    if field.is_ascii() {
        return !field.bytes().any(|byte| byte.is_ascii_uppercase());
    }
    windows_case_identity(field) == field
}

fn windows_case_identity(field: &str) -> String {
    let mut identity = String::with_capacity(field.len());
    for character in field.chars() {
        push_windows_case_folded(character, &mut identity);
    }
    identity
}

fn push_windows_case_folded(character: char, out: &mut String) {
    match character {
        '\u{0131}' => out.push('i'),
        '\u{017f}' => out.push('s'),
        '\u{212a}' => out.push('k'),
        '\u{00df}' => out.push_str("ss"),
        other => {
            for lower in other.to_lowercase() {
                match lower {
                    '\u{0131}' => out.push('i'),
                    '\u{017f}' => out.push('s'),
                    '\u{212a}' => out.push('k'),
                    '\u{00df}' => out.push_str("ss"),
                    folded => out.push(folded),
                }
            }
        }
    }
}

/// Temp path beside `path` whose name cannot collide with another field's
/// temp in this process, including on a case-folding volume. The FST temp
/// used to be `{segment}.{component}.fst.tmp` with no nonce: two components
/// that NTFS treats as one name shared that temp, the first rename consumed
/// it, and the second failed with `ERROR_FILE_NOT_FOUND` inside
/// `publishing FTS side-cars`.
fn unique_temp_sibling(path: &Path) -> PathBuf {
    static NONCE: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(1);
    let nonce = NONCE.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    let file_name = path
        .file_name()
        .map(|name| name.to_string_lossy().into_owned())
        .unwrap_or_else(|| "file".to_string());
    path.with_file_name(format!("{file_name}.tmp.{}.{nonce}", std::process::id()))
}

/// Removes `path` on drop unless [`DeleteOnDrop::disarm`] ran. The FST temp
/// is not a [`xerj_common::fsio::StagedFile`] until `stage_written_file`
/// returns; a panic inside `MapBuilder` would otherwise leave the temp behind.
struct DeleteOnDrop {
    path: PathBuf,
    armed: bool,
}

impl DeleteOnDrop {
    fn arm(path: PathBuf) -> Self {
        Self { path, armed: true }
    }

    fn disarm(&mut self) {
        self.armed = false;
    }
}

impl Drop for DeleteOnDrop {
    fn drop(&mut self) {
        if self.armed {
            let _ = fs::remove_file(&self.path);
        }
    }
}

fn panic_payload_message(payload: &Box<dyn std::any::Any + Send>) -> String {
    // Take `&Box<_>`, not `&(dyn Any + Send)`. A function argument of the
    // trait-object type unsizes the box itself, so `downcast_ref` looks for
    // `&str` inside a payload whose concrete type is the box and misses the
    // string `panic!` actually boxed.
    if let Some(message) = payload.downcast_ref::<&str>() {
        (*message).to_owned()
    } else if let Some(message) = payload.downcast_ref::<String>() {
        message.clone()
    } else {
        "non-string panic payload".to_owned()
    }
}

/// `true` when `file_name` is an FTS side-car, layout marker, analyzer marker,
/// or unpublished temp belonging to `segment_id`. Stored-segment files
/// (`.seg`, `.sidx`, `.ids`, `.dv`) are not.
fn is_segment_fts_artifact(segment_id: &str, file_name: &str) -> bool {
    let Some(rest) = file_name
        .strip_prefix(segment_id)
        .and_then(|suffix| suffix.strip_prefix('.'))
    else {
        return false;
    };
    if rest.is_empty() {
        return false;
    }
    if rest.contains(".tmp.") {
        return true;
    }
    matches!(rest, "fts-layout-v2" | "fts-layout-v3" | "ftsan")
        || matches!(
            rest.rsplit_once('.').map(|(_, extension)| extension),
            Some("fst" | "post" | "meta" | "norms")
        )
}

/// Remove this segment's FTS side-cars, filename-layout markers, analyzer
/// marker, and unpublished temps. `.seg`, `.sidx`, `.ids`, and `.dv` stay.
///
/// `Ok(())` means none of those FTS names remain, so the stored segment can
/// be published and searched by a stored-document scan. `Err` names every
/// path that could not be removed, with that path's OS error — a partial
/// family must not be published.
pub fn discard_segment_fts_files(segment_dir: &Path, segment_id: &str) -> std::io::Result<()> {
    let entries = match fs::read_dir(segment_dir) {
        Ok(entries) => entries,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(()),
        Err(error) => return Err(error),
    };
    let mut failures: Vec<String> = Vec::new();
    for entry in entries {
        let entry = entry?;
        let file_name = entry.file_name();
        let file_name = file_name.to_string_lossy();
        if !is_segment_fts_artifact(segment_id, &file_name) {
            continue;
        }
        let path = entry.path();
        if let Err(error) = fs::remove_file(&path) {
            if error.kind() != std::io::ErrorKind::NotFound {
                failures.push(format!("{}: {error}", path.display()));
            }
        }
    }
    if failures.is_empty() {
        Ok(())
    } else {
        Err(std::io::Error::other(format!(
            "could not remove FTS side-cars for segment {segment_id}: {}",
            failures.join("; ")
        )))
    }
}

/// Derive one FTS side-car path from controlled components only.
fn field_sidecar_path(
    segment_dir: &Path,
    segment_id: &str,
    field_name: &str,
    extension: &str,
) -> PathBuf {
    let field_component = field_file_component(field_name);
    segment_dir.join(format!("{segment_id}.{field_component}.{extension}"))
}

fn field_sidecar_path_for_layout(
    segment_dir: &Path,
    segment_id: &str,
    field_name: &str,
    extension: &str,
    layout: FilenameLayout,
) -> PathBuf {
    match layout {
        FilenameLayout::CaseDistinguished => {
            let field_component = field_file_component_v3(field_name);
            segment_dir.join(format!("{segment_id}.{field_component}.{extension}"))
        }
        FilenameLayout::Encoded | FilenameLayout::Legacy => {
            field_sidecar_path(segment_dir, segment_id, field_name, extension)
        }
    }
}

/// Return the exact pre-fix raw path only when it remains one child of the
/// segment directory on this host.
///
/// This reader-only bridge keeps already-published Linux fields such as a raw
/// backslash, a reserved digest-prefix literal, or a formerly accepted long
/// component readable after upgrade. It never creates a path and it refuses
/// slash/backslash-as-separator shapes through the parent equality check.
fn legacy_field_sidecar_path(
    segment_dir: &Path,
    segment_id: &str,
    field_name: &str,
    extension: &str,
) -> Option<PathBuf> {
    let candidate = segment_dir.join(format!("{segment_id}.{field_name}.{extension}"));
    (candidate.parent() == Some(segment_dir)).then_some(candidate)
}

// ── FieldIndexConfig ──────────────────────────────────────────────────────────

/// Per-field indexing configuration.
#[derive(Debug, Clone)]
pub struct FieldIndexConfig {
    /// Name of the analyzer to use for this field.
    pub analyzer: String,
    /// Whether to store positions (required for phrase queries).
    pub store_positions: bool,
    /// Whether to store term vectors (for highlight / more-like-this).
    pub store_term_vectors: bool,
}

impl Default for FieldIndexConfig {
    fn default() -> Self {
        Self {
            analyzer: "standard".to_owned(),
            store_positions: true,
            store_term_vectors: false,
        }
    }
}

// ── Meta file structures ──────────────────────────────────────────────────────

#[derive(Debug, Clone)]
struct FieldMeta {
    stats: FieldStats,
    terms: HashMap<String, SerialTermPostings>,
    /// When `false` the posting lists for this field omit both freq
    /// blocks and position blocks — each posting is just the doc_id.
    /// Readers must treat term_freq as 1 for every match.  Stored on
    /// disk as part of the `ZFM2` header.  Legacy `ZFM1` segments are
    /// implicitly `has_positions = true`.
    has_positions: bool,
    /// Format version used to read the field's FST values.
    ///
    /// * `FstValueFormat::PostingsOffset` — legacy ZFM1/ZFM2.  The FST
    ///   value is the byte offset into the `.post` file where this
    ///   term's postings start.  All of `{doc_freq, ttf, length}` are
    ///   looked up in `terms` keyed by the term string.
    /// * `FstValueFormat::MetaByteOffset` — ZFM3.  The FST value is the
    ///   byte offset of this term's 24-byte `{df, ttf, offset, length}`
    ///   record inside the `.meta` binary array.  The `.meta` file no
    ///   longer stores the term string — a 22 B/term saving on
    ///   high-cardinality keyword fields.
    fst_value_format: FstValueFormat,
    /// Raw bytes of the ZFM3 flat 24-byte-per-term records (in the same
    /// sorted-by-term order the FST enumerates).  Empty for ZFM1/ZFM2
    /// where metadata lives inside `terms`.
    flat_records: Vec<u8>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum FstValueFormat {
    /// Legacy: FST value is `postings_offset`.
    PostingsOffset,
    /// ZFM3: FST value is the byte offset of this term's record in the
    /// `.meta` flat array.  `meta[value..value+24]` holds
    /// `{doc_frequency: u32, total_term_frequency: u64,
    /// postings_offset: u64, postings_length: u32}`.
    MetaByteOffset,
}

/// Serializable version of TermPostings (all fields stored).
#[derive(Debug, Clone, Copy)]
struct SerialTermPostings {
    doc_frequency: u32,
    total_term_frequency: u64,
    postings_offset: u64,
    postings_length: u32,
}

impl From<&TermPostings> for SerialTermPostings {
    fn from(tp: &TermPostings) -> Self {
        Self {
            doc_frequency: tp.doc_frequency,
            total_term_frequency: tp.total_term_frequency,
            postings_offset: tp.postings_offset,
            postings_length: tp.postings_length,
        }
    }
}

impl From<SerialTermPostings> for TermPostings {
    fn from(s: SerialTermPostings) -> Self {
        Self {
            doc_frequency: s.doc_frequency,
            total_term_frequency: s.total_term_frequency,
            postings_offset: s.postings_offset,
            postings_length: s.postings_length,
        }
    }
}

// Binary `.meta` file format (V4 M4.7 — replaces pretty-JSON serde).
//
// Pretty-JSON was ~120 B/term (field names, quotes, indentation, newlines)
// on a dataset where the actual data per term is 24 B.  On the 66.5 M
// nginx battle that ballooned `.meta` to 8.37 GB = 126 B/doc across 2253
// segments × ~10 fields.  The binary format below is 4-20 B/term
// depending on term length — a 6-20× reduction.
//
// Layout:
//
// ```
// "ZFM1"  4 bytes magic  (legacy — implies has_positions = true)
// "ZFM2"  4 bytes magic  (adds 1-byte has_positions flag after num_terms)
// "ZFM3"  4 bytes magic  (drops term names — FST value = meta byte offset)
// u64    total_docs             (FieldStats.total_docs)
// u64    total_field_length     (FieldStats.total_field_length)
// u32    num_terms
// [ZFM2 + ZFM3] u8   has_positions
// ZFM1/ZFM2 per term (num_terms times):
//     u16  term_len
//     term_len bytes             (UTF-8 term)
//     u32  doc_frequency
//     u64  total_term_frequency
//     u64  postings_offset
//     u32  postings_length
// ZFM3 per term (fixed 24 bytes each, no term string):
//     u32  doc_frequency
//     u64  total_term_frequency
//     u64  postings_offset
//     u32  postings_length
// ```
const META_MAGIC_V1: &[u8; 4] = b"ZFM1";
const META_MAGIC_V2: &[u8; 4] = b"ZFM2";
const META_MAGIC_V3: &[u8; 4] = b"ZFM3";
/// ZFM4 = ZFM3 records section wrapped in a Zstd-19 envelope.  The
/// header bytes (magic + total_docs + total_field_length + num_terms +
/// has_positions) stay uncompressed so they're cheap to read; only
/// the per-term fixed-24-byte records (which dominate the file at
/// high-cardinality fields — 60 % of segment bytes on the bench)
/// get compressed.  Records are highly redundant (small u32/u64s,
/// monotonic offsets) so Zstd-19 typically squeezes 6-10× on them.
/// On read we decompress once into the same in-memory `flat_records`
/// `Vec<u8>` ZFM3 already populates, so the lookup hot path is
/// completely unchanged.
const META_MAGIC_V4: &[u8; 4] = b"ZFM4";
/// ZFM5 = the ZFM4 records section replaced by four columnar varint
/// streams before the Zstd envelope.  ZFM4 kept the fixed 24-byte
/// `{df u32, ttf u64, off u64, len u32}` record stride; Zstd cannot
/// match across that stride's alternating widths, so on the 100 k-doc
/// harness segment `doc_id.meta` (100 k unique terms, every one
/// `ttf == df`, every postings gap zero) still cost 138.7 KB on disk
/// for ~200 B of information.  ZFM5 stores, per term, only varints of
/// what actually varies:
///
/// ```text
///   df stream     num_terms × uvarint(doc_frequency)
///   [ttf stream]  num_terms × uvarint(ttf − df)   — elided when every
///                 term in the field has ttf == df (keyword-shaped fields)
///   gap stream    num_terms × uvarint(off − prev_off − prev_len)
///   len stream    num_terms × uvarint(postings_length)
/// ```
///
/// Measured on that segment the `.meta` family drops 200,826 → 13,774 B
/// (−93.1 %), and the win scales with term cardinality, which is exactly
/// the shape of the 66.5 M-doc nginx battle's id fields.  Peer pattern:
/// tantivy's `TermInfoValueWriter::serialize_block`
/// (`src/termdict/sstable_termdict/mod.rs:92-105`, MIT — postings-peers
/// corpus) writes block-leading absolute range starts once and then only
/// per-term `VInt(doc_freq)` + `VInt(range.len)`, reconstructing offsets
/// by accumulation.  ZFM5 keeps an explicit gap varint rather than
/// assuming contiguity — one byte per term pre-compression, and the
/// decoder never has to trust that every writer packed tightly.
///
/// On read the streams are expanded once at open time into the same
/// in-memory `flat_records` 24-byte-stride `Vec<u8>` ZFM3/ZFM4 build, so
/// the FST byte-offset lookup hot path is completely unchanged.
const META_MAGIC_V5: &[u8; 4] = b"ZFM5";
/// Postings file wrapped in a whole-file LZ4 envelope — magic prefix
/// lets the reader auto-detect and decompress while legacy `.post`
/// files (no prefix) continue to work via the raw mmap path.
const POST_MAGIC_LZ4: &[u8; 4] = b"ZPL1";
/// Postings file wrapped in a Zstd envelope, with the LEGACY ZPS1 inner
/// block framing (`[num_bits ≥ 1][u32 byte_len][payload]`, freq stream
/// always present on positioned fields).  Still written by no current
/// code path; the read side keeps these segments decodable.
const POST_MAGIC_ZSTD: &[u8; 4] = b"ZPS1";
/// Postings file wrapped in a Zstd envelope with the ZPS2 inner block
/// framing: frame-of-reference packed blocks (`[width][vbyte min]`,
/// width 0 = constant block, payload length derived), positions without
/// the derivable `u32` length prefix, and the freq stream omitted
/// entirely for a term whose `ttf == df`.  The envelope magic doubles as
/// the inner-framing version — same envelope layout as ZPS1, so only the
/// decode-time codec choice differs.  See `xerj_fts::postings`'s module
/// docs for the framing and the peer citations.
const POST_MAGIC_ZSTD_V2: &[u8; 4] = b"ZPS2";
/// Zstd compression level used for the durable segment artifacts
/// (`.meta` ZFM4, `.post` ZPS1).  Reverted from 19 to 3: this constant
/// is invoked at **flush** time, not just merge, so the ~25 MB/s/core
/// throughput of level 19 is not "out of band" — it stalls the back-
/// pressure-critical flush path.  Level 3 (~250 MB/s/core) restores
/// 1 M+ docs/s sustained ingest at a ~5 % steady-state disk cost
/// (merge-dominated long-term storage barely changes; only the
/// freshest tier-0 segments are larger before they merge).  See
/// `engine/reports/2026-04-25T21-50-00_ingest_perf_regression_zstd19.md`.
///
/// This is the **flush** level and the writer default. A merge-time caller
/// raises it via [`FtsIndexWriter::with_zstd_level`] to honour the operator's
/// `compression.level` (#318) — merge is off the ingest critical path, which
/// is exactly the distinction the paragraph above is about.
pub const ZSTD_DURABLE_LEVEL: i32 = 3;
const ZFM3_RECORD_LEN: usize = 4 + 8 + 8 + 4; // 24 bytes: df, ttf, off, len

/// Header byte length for a ZFM3 file (magic + total_docs + total_field_length
/// + num_terms + has_positions).
const ZFM3_HEADER_LEN: usize = 4 + 8 + 8 + 4 + 1;

/// Header byte length for a ZFM5 file (ZFM3 header + the `flags` byte).
const ZFM5_HEADER_LEN: usize = ZFM3_HEADER_LEN + 1;

/// Encode a `.meta` file in the ZFM3 flat format.
///
/// `sorted_terms` must be the same term-sorted order used to insert
/// into the FST; the i-th term's record lives at byte offset
/// `ZFM3_HEADER_LEN + i * ZFM3_RECORD_LEN`, which is what the FST
/// value stores for that term.  Drops the ~20 B/term term-string
/// duplication that ZFM1/ZFM2 carried, since the `.fst` already owns
/// the authoritative sorted dictionary.
/// Encode a `.meta` file in the ZFM4 format = ZFM3 header + Zstd
/// envelope around the records section.  See `META_MAGIC_V4` for the
/// motivation; on a 100 k-doc XERJ bench segment this drops the two
/// largest meta files (`.k.meta`, `.name.meta`) from 2.25 MB each to
/// ~250 KB — the single biggest disk-efficiency win.
///
/// Layout:
/// ```text
///   "ZFM4" 4
///   total_docs           u64
///   total_field_length   u64
///   num_terms            u32
///   has_positions        u8
///   uncompressed_len     u32  (= num_terms * 24, sanity check)
///   compressed_len       u32  (= len(zstd_payload), tail follows)
///   zstd_payload         compressed_len bytes
/// ```
/// Kept for the test fixtures that need a real on-disk ZFM4 segment —
/// the writer default moved to ZFM5, and the ZFM4 decode arm (upgrade
/// path for segments written between M4.7 and ZFM5) must stay exercised.
#[cfg(test)]
fn encode_field_meta_v4(
    stats: &FieldStats,
    has_positions: bool,
    sorted_terms: &[String],
    term_postings: &HashMap<String, TermPostings>,
    zstd_level: i32,
) -> Result<Vec<u8>> {
    let num_terms = sorted_terms.len();
    // Build the records section in the same byte layout that ZFM3
    // would write — that way `flat_records` in memory is identical to
    // the ZFM3 path and `lookup_term` works unchanged.
    let mut records: Vec<u8> = Vec::with_capacity(num_terms * ZFM3_RECORD_LEN);
    for term in sorted_terms {
        let tp = term_postings
            .get(term)
            .expect("sorted_terms must match term_postings keys");
        records.write_u32::<LittleEndian>(tp.doc_frequency).unwrap();
        records
            .write_u64::<LittleEndian>(tp.total_term_frequency)
            .unwrap();
        records
            .write_u64::<LittleEndian>(tp.postings_offset)
            .unwrap();
        records
            .write_u32::<LittleEndian>(tp.postings_length)
            .unwrap();
    }
    let uncompressed_len = records.len() as u32;
    let compressed =
        zstd::bulk::compress(&records, zstd_level).with_context(|| "ZFM4 zstd compress")?;
    let mut out: Vec<u8> = Vec::with_capacity(ZFM3_HEADER_LEN + 4 + 4 + compressed.len());
    out.extend_from_slice(META_MAGIC_V4);
    out.write_u64::<LittleEndian>(stats.total_docs).unwrap();
    out.write_u64::<LittleEndian>(stats.total_field_length)
        .unwrap();
    out.write_u32::<LittleEndian>(num_terms as u32).unwrap();
    out.push(if has_positions { 1u8 } else { 0u8 });
    out.write_u32::<LittleEndian>(uncompressed_len).unwrap();
    out.write_u32::<LittleEndian>(compressed.len() as u32)
        .unwrap();
    out.extend_from_slice(&compressed);
    Ok(out)
}

/// `flags` bit assignments for the ZFM5 header.
const ZFM5_FLAG_TTF_STREAM: u8 = 0x01;

/// Encode a `.meta` file in the ZFM5 format — see [`META_MAGIC_V5`].
///
/// Same header contract as ZFM4 (`num_terms`, `uncompressed_len` sanity
/// check) so the decode side can share its validation, with one extra
/// `flags` byte recording whether the ttf stream is present.
fn encode_field_meta_v5(
    stats: &FieldStats,
    has_positions: bool,
    sorted_terms: &[String],
    term_postings: &HashMap<String, TermPostings>,
    zstd_level: i32,
) -> Result<Vec<u8>> {
    use crate::postings::uvarint_encode;
    let num_terms = sorted_terms.len();
    // The ttf stream is all-or-nothing per field, decided up front: a
    // per-term "needs an entry" decision made in scan order would leave
    // the terms before the first ttf != df term without their zero
    // entries, and the reader splits sections by fixed counts.
    let mut ttf_stream_needed = false;
    for term in sorted_terms {
        let tp = term_postings
            .get(term)
            .ok_or_else(|| anyhow::anyhow!("field meta is missing postings for term '{term}'"))?;
        if tp.total_term_frequency < tp.doc_frequency as u64 {
            // A panic here aborted the flush task (`resume_unwind`) during
            // indexing. rc.97 reports described that as a panic in the fst
            // merge: this encode runs while the merged field's FST is built.
            bail!(
                "total_term_frequency {} is below doc_frequency {} for term '{term}'",
                tp.total_term_frequency,
                tp.doc_frequency
            );
        }
        if tp.total_term_frequency != tp.doc_frequency as u64 {
            ttf_stream_needed = true;
        }
    }
    let flags = if ttf_stream_needed {
        ZFM5_FLAG_TTF_STREAM
    } else {
        0u8
    };
    let mut dfs: Vec<u8> = Vec::with_capacity(num_terms);
    let mut ttf_deltas: Vec<u8> = Vec::new();
    let mut gaps: Vec<u8> = Vec::with_capacity(num_terms);
    let mut lens: Vec<u8> = Vec::with_capacity(num_terms);
    let mut prev_end = 0u64;
    for term in sorted_terms {
        let tp = term_postings
            .get(term)
            .ok_or_else(|| anyhow::anyhow!("field meta is missing postings for term '{term}'"))?;
        uvarint_encode(tp.doc_frequency as u64, &mut dfs);
        if ttf_stream_needed {
            uvarint_encode(
                tp.total_term_frequency - tp.doc_frequency as u64,
                &mut ttf_deltas,
            );
        }
        if tp.postings_offset < prev_end {
            return Err(anyhow::anyhow!(
                "ZFM5 requires monotone postings offsets (term '{term}' at {} after {})",
                tp.postings_offset,
                prev_end
            ));
        }
        uvarint_encode(tp.postings_offset - prev_end, &mut gaps);
        uvarint_encode(tp.postings_length as u64, &mut lens);
        prev_end = tp.postings_offset + tp.postings_length as u64;
    }
    let mut streams = dfs;
    streams.extend_from_slice(&ttf_deltas);
    streams.extend_from_slice(&gaps);
    streams.extend_from_slice(&lens);
    let compressed =
        zstd::bulk::compress(&streams, zstd_level).with_context(|| "ZFM5 zstd compress")?;
    let uncompressed_len = (num_terms * ZFM3_RECORD_LEN) as u32;
    let mut out: Vec<u8> = Vec::with_capacity(ZFM5_HEADER_LEN + 8 + compressed.len());
    out.extend_from_slice(META_MAGIC_V5);
    out.write_u64::<LittleEndian>(stats.total_docs).unwrap();
    out.write_u64::<LittleEndian>(stats.total_field_length)
        .unwrap();
    out.write_u32::<LittleEndian>(num_terms as u32).unwrap();
    out.push(if has_positions { 1u8 } else { 0u8 });
    out.push(flags);
    out.write_u32::<LittleEndian>(uncompressed_len).unwrap();
    out.write_u32::<LittleEndian>(compressed.len() as u32)
        .unwrap();
    out.extend_from_slice(&compressed);
    Ok(out)
}

fn decode_field_meta_binary(bytes: &[u8]) -> Result<FieldMeta> {
    use std::io::Cursor;
    if bytes.len() < 4 {
        return Err(anyhow::anyhow!("field meta: too short"));
    }
    // ZFM5 path — columnar varint streams under the Zstd envelope,
    // expanded once at open time into the ZFM3 flat-record layout.
    if &bytes[..4] == META_MAGIC_V5 {
        use crate::postings::uvarint_decode;
        // Header + flags + the two trailing length u32s
        let zfm5_prefix = ZFM5_HEADER_LEN + 4 + 4;
        if bytes.len() < zfm5_prefix {
            return Err(anyhow::anyhow!("field meta: ZFM5 truncated header"));
        }
        let mut cur = Cursor::new(&bytes[4..zfm5_prefix]);
        let total_docs = cur.read_u64::<LittleEndian>()?;
        let total_field_length = cur.read_u64::<LittleEndian>()?;
        let num_terms = cur.read_u32::<LittleEndian>()? as usize;
        let has_positions = cur.read_u8()? != 0;
        let flags = cur.read_u8()?;
        let uncompressed_len = cur.read_u32::<LittleEndian>()? as usize;
        let compressed_len = cur.read_u32::<LittleEndian>()? as usize;
        let expected_uncompressed = num_terms
            .checked_mul(ZFM3_RECORD_LEN)
            .ok_or_else(|| anyhow::anyhow!("field meta: ZFM5 num_terms overflow ({num_terms})"))?;
        if uncompressed_len != expected_uncompressed {
            return Err(anyhow::anyhow!(
                "field meta: ZFM5 length mismatch (uncompressed_len={uncompressed_len}, num_terms*24={expected_uncompressed})"
            ));
        }
        if bytes.len() != zfm5_prefix + compressed_len {
            return Err(anyhow::anyhow!(
                "field meta: ZFM5 payload length mismatch (expected {compressed_len} bytes, got {})",
                bytes.len() - zfm5_prefix
            ));
        }
        let streams = zstd::bulk::decompress(
            &bytes[zfm5_prefix..],
            // A u64 varint is at most 10 bytes, so 4 sections bound the
            // streams at 40 B/term; anything larger is corruption.
            num_terms.saturating_mul(4 * 10).max(64),
        )
        .with_context(|| "ZFM5 zstd decompress")?;
        let mut scur = Cursor::new(streams.as_slice());
        let mut read_section = |count: usize| -> Result<Vec<u64>> {
            (0..count)
                .map(|_| {
                    uvarint_decode(&mut scur).map_err(|error| {
                        anyhow::anyhow!("field meta: ZFM5 stream truncated ({error})")
                    })
                })
                .collect()
        };
        let dfs = read_section(num_terms)?;
        let ttf_deltas = if flags & ZFM5_FLAG_TTF_STREAM != 0 {
            read_section(num_terms)?
        } else {
            vec![0u64; num_terms]
        };
        let gap_section = read_section(num_terms)?;
        let len_section = read_section(num_terms)?;
        if scur.position() as usize != streams.len() {
            return Err(anyhow::anyhow!(
                "field meta: ZFM5 trailing stream bytes ({} of {})",
                streams.len() - scur.position() as usize,
                streams.len()
            ));
        }
        let mut flat_records: Vec<u8> = Vec::with_capacity(expected_uncompressed);
        let mut offset = 0u64;
        for i in 0..num_terms {
            let df = u32::try_from(dfs[i])
                .map_err(|_| anyhow::anyhow!("field meta: ZFM5 df exceeds u32"))?;
            // The delta is an untrusted varint up to u64::MAX — an
            // unchecked add would wrap in release (panic in dev) and
            // hand the ZPS2 freq-elision predicate a ttf < df, so this
            // lane fails closed exactly like the offset lanes below.
            let ttf = (df as u64)
                .checked_add(ttf_deltas[i])
                .ok_or_else(|| anyhow::anyhow!("field meta: ZFM5 ttf overflow"))?;
            offset = offset
                .checked_add(gap_section[i])
                .ok_or_else(|| anyhow::anyhow!("field meta: ZFM5 offset overflow"))?;
            let len = u32::try_from(len_section[i])
                .map_err(|_| anyhow::anyhow!("field meta: ZFM5 postings_length exceeds u32"))?;
            flat_records.write_u32::<LittleEndian>(df).unwrap();
            flat_records.write_u64::<LittleEndian>(ttf).unwrap();
            flat_records.write_u64::<LittleEndian>(offset).unwrap();
            flat_records.write_u32::<LittleEndian>(len).unwrap();
            offset = offset
                .checked_add(len as u64)
                .ok_or_else(|| anyhow::anyhow!("field meta: ZFM5 offset overflow"))?;
        }
        if flat_records.len() != expected_uncompressed {
            return Err(anyhow::anyhow!(
                "field meta: ZFM5 record expansion mismatch (got {}, expected {expected_uncompressed})",
                flat_records.len()
            ));
        }
        return Ok(FieldMeta {
            stats: FieldStats {
                total_docs,
                total_field_length,
            },
            terms: HashMap::new(),
            has_positions,
            fst_value_format: FstValueFormat::MetaByteOffset,
            flat_records,
        });
    }
    // ZFM4 path — Zstd-compressed records section.  Decompresses
    // once at open time into the same `flat_records` Vec<u8> ZFM3
    // populates, so the per-query lookup path is unchanged.
    if &bytes[..4] == META_MAGIC_V4 {
        // Header + the two trailing length u32s = 4 + 8 + 8 + 4 + 1 + 4 + 4
        let zfm4_prefix = ZFM3_HEADER_LEN + 4 + 4;
        if bytes.len() < zfm4_prefix {
            return Err(anyhow::anyhow!("field meta: ZFM4 truncated header"));
        }
        let mut cur = Cursor::new(&bytes[4..zfm4_prefix]);
        let total_docs = cur.read_u64::<LittleEndian>()?;
        let total_field_length = cur.read_u64::<LittleEndian>()?;
        let num_terms = cur.read_u32::<LittleEndian>()? as usize;
        let has_positions = cur.read_u8()? != 0;
        let uncompressed_len = cur.read_u32::<LittleEndian>()? as usize;
        let compressed_len = cur.read_u32::<LittleEndian>()? as usize;
        let expected_uncompressed = num_terms * ZFM3_RECORD_LEN;
        if uncompressed_len != expected_uncompressed {
            return Err(anyhow::anyhow!(
                "field meta: ZFM4 length mismatch (uncompressed_len={uncompressed_len}, num_terms*24={expected_uncompressed})"
            ));
        }
        if bytes.len() < zfm4_prefix + compressed_len {
            return Err(anyhow::anyhow!(
                "field meta: ZFM4 payload truncated (expected {compressed_len} bytes, got {})",
                bytes.len() - zfm4_prefix
            ));
        }
        let payload = &bytes[zfm4_prefix..zfm4_prefix + compressed_len];
        let flat_records = zstd::bulk::decompress(payload, uncompressed_len)
            .with_context(|| "ZFM4 zstd decompress")?;
        if flat_records.len() != uncompressed_len {
            return Err(anyhow::anyhow!(
                "field meta: ZFM4 decompressed size mismatch (got {}, expected {uncompressed_len})",
                flat_records.len()
            ));
        }
        return Ok(FieldMeta {
            stats: FieldStats {
                total_docs,
                total_field_length,
            },
            terms: HashMap::new(),
            has_positions,
            fst_value_format: FstValueFormat::MetaByteOffset,
            flat_records,
        });
    }
    // ZFM3 path — flat 24-byte records, no term strings stored.
    if &bytes[..4] == META_MAGIC_V3 {
        if bytes.len() < ZFM3_HEADER_LEN {
            return Err(anyhow::anyhow!("field meta: ZFM3 truncated header"));
        }
        let mut cur = Cursor::new(&bytes[4..ZFM3_HEADER_LEN]);
        let total_docs = cur.read_u64::<LittleEndian>()?;
        let total_field_length = cur.read_u64::<LittleEndian>()?;
        let num_terms = cur.read_u32::<LittleEndian>()? as usize;
        let has_positions = cur.read_u8()? != 0;
        let expected = ZFM3_HEADER_LEN + num_terms * ZFM3_RECORD_LEN;
        if bytes.len() < expected {
            return Err(anyhow::anyhow!(
                "field meta: ZFM3 body truncated (expected {expected}, got {})",
                bytes.len()
            ));
        }
        return Ok(FieldMeta {
            stats: FieldStats {
                total_docs,
                total_field_length,
            },
            // ZFM3 doesn't populate `terms` — lookups go through
            // `flat_records` via the FST byte-offset value instead.
            terms: HashMap::new(),
            has_positions,
            fst_value_format: FstValueFormat::MetaByteOffset,
            flat_records: bytes[ZFM3_HEADER_LEN..expected].to_vec(),
        });
    }

    // ZFM1 / ZFM2 path — term names + metadata interleaved.
    let is_v2 = if &bytes[..4] == META_MAGIC_V2 {
        true
    } else if &bytes[..4] == META_MAGIC_V1 {
        false
    } else {
        return Err(anyhow::anyhow!("field meta: missing ZFM1/ZFM2/ZFM3 magic"));
    };
    let mut cur = Cursor::new(&bytes[4..]);
    let total_docs = cur.read_u64::<LittleEndian>()?;
    let total_field_length = cur.read_u64::<LittleEndian>()?;
    let num_terms = cur.read_u32::<LittleEndian>()? as usize;
    let has_positions = if is_v2 {
        cur.read_u8()? != 0
    } else {
        true // legacy default
    };
    let mut terms: HashMap<String, SerialTermPostings> = HashMap::with_capacity(num_terms);
    for _ in 0..num_terms {
        let term_len = cur.read_u16::<LittleEndian>()? as usize;
        let pos = cur.position() as usize + 4;
        if bytes.len() < pos + term_len {
            return Err(anyhow::anyhow!("field meta: truncated term"));
        }
        let term_bytes = &bytes[pos..pos + term_len];
        let term = std::str::from_utf8(term_bytes)
            .map_err(|e| anyhow::anyhow!("field meta: bad utf8: {e}"))?
            .to_owned();
        cur.set_position((pos + term_len - 4) as u64);
        let doc_frequency = cur.read_u32::<LittleEndian>()?;
        let total_term_frequency = cur.read_u64::<LittleEndian>()?;
        let postings_offset = cur.read_u64::<LittleEndian>()?;
        let postings_length = cur.read_u32::<LittleEndian>()?;
        terms.insert(
            term,
            SerialTermPostings {
                doc_frequency,
                total_term_frequency,
                postings_offset,
                postings_length,
            },
        );
    }
    Ok(FieldMeta {
        stats: FieldStats {
            total_docs,
            total_field_length,
        },
        terms,
        has_positions,
        fst_value_format: FstValueFormat::PostingsOffset,
        flat_records: Vec::new(),
    })
}

// ── Multi-valued field input ──────────────────────────────────────────────────

/// Position gap inserted between two values of the same multi-valued field.
///
/// Mirrors Lucene/Elasticsearch's default `position_increment_gap` of 100.
/// Without it, `["alpha bravo", "charlie"]` would put `bravo` at position 1 and
/// `charlie` at position 2, so `match_phrase: "bravo charlie"` would match a
/// phrase that exists in NEITHER value.  100 is large enough that no realistic
/// `slop` bridges the boundary, and small enough to stay in the VByte fast path.
pub const POSITION_INCREMENT_GAP: u32 = 100;

/// The values a single document supplies for a single field.
///
/// A JSON document field is either a scalar or an array, and Elasticsearch
/// treats the array as N independent values of the field — not as one
/// concatenated value.  That distinction is invisible for an analyzed `text`
/// field only by accident (the standard tokenizer re-splits on the joining
/// space); for a `keyword` field, which is indexed with the whole input as one
/// token, joining `["red","blue"]` into `"red blue"` produces a term that
/// matches neither `red` nor `blue`.  See issue #332.
///
/// `One` exists so the overwhelmingly common single-valued case costs no extra
/// allocation on the flush/merge path — the `String` is moved in as-is.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum FieldValues {
    /// Exactly one value (a JSON scalar, or a one-element array).
    One(String),
    /// Two or more values (a JSON array). Never constructed with < 2 elements
    /// by [`FieldValues::from_values`], but tolerated if built directly.
    Many(Vec<String>),
}

impl FieldValues {
    /// Build from an iterator, collapsing the single-value case to `One`.
    pub fn from_values<I: IntoIterator<Item = String>>(values: I) -> Self {
        let mut v: Vec<String> = values.into_iter().collect();
        if v.len() == 1 {
            FieldValues::One(v.pop().unwrap())
        } else {
            FieldValues::Many(v)
        }
    }

    /// Iterate every value in document order.
    pub fn iter(&self) -> impl Iterator<Item = &str> {
        match self {
            FieldValues::One(s) => std::slice::from_ref(s).iter(),
            FieldValues::Many(v) => v.iter(),
        }
        .map(|s| s.as_str())
    }

    /// Number of values.
    pub fn len(&self) -> usize {
        match self {
            FieldValues::One(_) => 1,
            FieldValues::Many(v) => v.len(),
        }
    }

    /// True when the field carries no value at all (only reachable via a
    /// directly-constructed `Many(vec![])`).
    pub fn is_empty(&self) -> bool {
        match self {
            FieldValues::One(s) => s.is_empty(),
            FieldValues::Many(v) => v.iter().all(|s| s.is_empty()),
        }
    }
}

impl From<String> for FieldValues {
    fn from(s: String) -> Self {
        FieldValues::One(s)
    }
}

impl From<&str> for FieldValues {
    fn from(s: &str) -> Self {
        FieldValues::One(s.to_owned())
    }
}

impl From<Vec<String>> for FieldValues {
    fn from(v: Vec<String>) -> Self {
        FieldValues::from_values(v)
    }
}

/// Analyze every value of one field for one document and fold the tokens into
/// `field_data`.
///
/// Shared by [`FtsIndexWriter::add_document`] and
/// [`FtsIndexWriter::add_documents_parallel`] so the serial and parallel paths
/// cannot drift — the two used to hold independent copies of this loop.
///
/// Semantics per value:
/// * positions restart from `base`, which advances past the previous value's
///   last position plus [`POSITION_INCREMENT_GAP`];
/// * the norm (field length) is the SUM of every value's token count, matching
///   Lucene, so BM25 length-normalisation sees the whole field;
/// * exactly one norm entry and one `total_docs` increment per (doc, field),
///   however many values the field has.
fn index_field_values<'a>(
    field_data: &mut FieldData,
    analyzer: &crate::analyzer::AnalyzerPipeline,
    doc_ord: u32,
    values: impl Iterator<Item = &'a str>,
) {
    let mut field_len: u64 = 0;
    let mut base: u32 = 0;
    let mut first = true;
    for value in values {
        if !first {
            base = base.saturating_add(POSITION_INCREMENT_GAP);
        }
        first = false;
        let tokens = analyzer.analyze(value);
        let mut max_position = 0u32;
        for token in &tokens {
            field_data.postings.add_occurrence(
                &token.text,
                doc_ord,
                base.saturating_add(token.position),
            );
            max_position = max_position.max(token.position);
        }
        if !tokens.is_empty() {
            base = base.saturating_add(max_position).saturating_add(1);
        }
        field_len += tokens.len() as u64;
    }

    field_data.norms.push((
        doc_ord,
        norm_u16_to_u8(field_len.min(u16::MAX as u64) as u16),
    ));
    field_data.stats.total_docs += 1;
    field_data.stats.total_field_length += field_len;
}

// ── FtsIndexWriter ────────────────────────────────────────────────────────────

/// Builds the FTS inverted index for one segment.
///
/// Usage:
/// ```text
/// let mut writer = FtsIndexWriter::new(dir, segment_id, registry);
/// for doc in docs { writer.add_document(doc_id, &fields); }
/// if writer.uses_case_distinguished_field_filename_components() {
///     // The engine advances its data-directory format to v3 before this step.
///     writer.publish_case_distinguished_filename_layout()?;
/// } else if writer.uses_encoded_field_filename_components() {
///     // The engine advances its data-directory format to v2 before this step.
///     writer.publish_encoded_filename_layout()?;
/// }
/// writer.finish()?;
/// ```
pub struct FtsIndexWriter {
    segment_dir: PathBuf,
    segment_id: String,
    registry: Arc<AnalyzerRegistry>,
    /// Per-field: (config, postings_writer, field_stats, norms)
    fields: HashMap<String, FieldData>,
    /// Layout marker this writer has durably published, if any.
    published_filename_layout: Option<FilenameLayout>,
    /// Zstd effort for the `.meta` (ZFM4) and `.post` (ZPS1) envelopes.
    /// [`ZSTD_DURABLE_LEVEL`] unless [`Self::with_zstd_level`] raised it.
    zstd_level: i32,
    /// Test-only. When `finish` writes this field, it panics inside the
    /// `catch_unwind` that turns an `fst` builder panic into `Err`. Per
    /// writer, so parallel tests do not share a process-global flag.
    #[cfg(test)]
    panic_on_field: Option<String>,
}

struct FieldData {
    config: FieldIndexConfig,
    postings: PostingsWriter,
    stats: FieldStats,
    /// `(doc_id, quantised norm byte)` in insertion order.
    ///
    /// The quantisation happens HERE rather than in `write_field_static` so
    /// that the merge path can carry a source segment's norm byte through
    /// verbatim.  [`norm_u8_to_u16`] is NOT the inverse of
    /// [`norm_u16_to_u8`] — byte 9 dequantises to length 8, which
    /// re-quantises to byte 8 — so a merge that read lengths back out of a
    /// source segment and re-quantised them would silently change BM25
    /// length normalisation for every merged document.
    norms: Vec<(u32, u8)>,
}

impl FtsIndexWriter {
    /// Create a new writer that will output files to `segment_dir`.
    pub fn new(
        segment_dir: impl AsRef<Path>,
        segment_id: impl Into<String>,
        registry: Arc<AnalyzerRegistry>,
    ) -> Self {
        Self {
            segment_dir: segment_dir.as_ref().to_path_buf(),
            segment_id: segment_id.into(),
            registry,
            fields: HashMap::new(),
            published_filename_layout: None,
            zstd_level: ZSTD_DURABLE_LEVEL,
            #[cfg(test)]
            panic_on_field: None,
        }
    }

    /// The next [`Self::finish`] panics while writing `field`. The panic is
    /// caught and returned as that field's error, which is what an `fst`
    /// `MapBuilder` assert does on this path.
    #[cfg(test)]
    fn panic_while_writing_field(&mut self, field: impl Into<String>) {
        self.panic_on_field = Some(field.into());
    }

    /// The configuration an UNCONFIGURED field is indexed with.
    ///
    /// Pre-#937 this was always [`FieldIndexConfig::default`]
    /// (`standard`). It now resolves the registry's `default` analyzer
    /// when the index settings declared one, so a dynamically-mapped
    /// field that never entered `build_fts_field_configs` is analysed
    /// the same way at flush as the memtable analysed it at insert
    /// (`get_analyzer("default").or_else(standard)`). With no declared
    /// `default` the resolution is `standard` and behaviour is
    /// unchanged.
    fn unconfigured_field_config(registry: &AnalyzerRegistry) -> FieldIndexConfig {
        let analyzer = if registry.get_analyzer("default").is_some() {
            "default"
        } else {
            "standard"
        };
        FieldIndexConfig {
            analyzer: analyzer.to_owned(),
            store_positions: true,
            store_term_vectors: false,
        }
    }

    /// Re-encode this segment's `.meta` / `.post` at `level` instead of the
    /// flush default [`ZSTD_DURABLE_LEVEL`].
    ///
    /// For merge callers only — flush must not raise the level, and
    /// [`ZSTD_DURABLE_LEVEL`] records the measured reason. Both envelopes
    /// stay byte-format-identical across levels (zstd decode does not consult
    /// the level a payload was written at), so this changes only how hard the
    /// encoder works and how large the result is.
    pub fn with_zstd_level(mut self, level: i32) -> Self {
        self.zstd_level = level;
        self
    }

    /// Register a field with its indexing configuration.
    /// Must be called before `add_document` uses this field.
    pub fn configure_field(&mut self, field: impl Into<String>, config: FieldIndexConfig) {
        let postings = if config.store_positions {
            PostingsWriter::new()
        } else {
            PostingsWriter::new_no_positions()
        };
        self.fields.insert(
            field.into(),
            FieldData {
                config,
                postings,
                stats: FieldStats::default(),
                norms: Vec::new(),
            },
        );
    }

    /// Whether finishing this writer can create a v2 digest-derived field
    /// filename (a name that is not a portable literal).
    ///
    /// This is false for a mixed-case literal such as `page_Id`. That name
    /// needs [`Self::uses_case_distinguished_field_filename_components`].
    /// Engine callers use this after configuration/document ingestion and
    /// before [`Self::finish`] to durably advance the data-directory marker.
    pub fn uses_encoded_field_filename_components(&self) -> bool {
        self.fields
            .keys()
            .any(|field| matches!(field_file_component(field), Cow::Owned(_)))
    }

    /// Whether a portable literal in this writer would alias another field
    /// on a case-folding filesystem (`page_Id` / `page_id`, `ı` / `i`).
    pub fn uses_case_distinguished_field_filename_components(&self) -> bool {
        self.fields
            .keys()
            .any(|field| field_needs_case_distinguished_component(field))
    }

    fn required_filename_layout(&self) -> FilenameLayout {
        if self.uses_case_distinguished_field_filename_components() {
            FilenameLayout::CaseDistinguished
        } else if self.uses_encoded_field_filename_components() {
            FilenameLayout::Encoded
        } else {
            FilenameLayout::Legacy
        }
    }

    /// Durably publish this segment's immutable v2 filename discriminator.
    ///
    /// The engine must durably advance the data-directory format first, call
    /// this method second, and call [`Self::finish`] last. `finish` refuses to
    /// emit encoded side-cars without this proof. An existing discriminator is
    /// accepted only when it contains the exact v2 magic. A writer that also
    /// needs layout v3 must call
    /// [`Self::publish_case_distinguished_filename_layout`] instead: a v2
    /// marker would keep `page_Id` literal.
    pub fn publish_encoded_filename_layout(&mut self) -> Result<()> {
        if !self.uses_encoded_field_filename_components() {
            return Ok(());
        }
        if self.uses_case_distinguished_field_filename_components() {
            bail!("case-distinguished FTS field filenames require filename layout v3, not v2");
        }
        self.publish_layout_marker(FilenameLayout::Encoded, FTS_FILENAME_LAYOUT_V2_MARKER_BYTES)
    }

    /// Durably publish this segment's immutable v3 filename discriminator.
    ///
    /// The engine must durably advance the data-directory format to v3 first.
    /// A v2 reader looks `page_Id` up as a literal and would silently skip the
    /// field, so the directory marker has to refuse that binary before any v3
    /// side-car exists. No-op when no field needs the distinction.
    pub fn publish_case_distinguished_filename_layout(&mut self) -> Result<()> {
        if !self.uses_case_distinguished_field_filename_components() {
            return Ok(());
        }
        self.publish_layout_marker(
            FilenameLayout::CaseDistinguished,
            FTS_FILENAME_LAYOUT_V3_MARKER_BYTES,
        )
    }

    fn publish_layout_marker(&mut self, layout: FilenameLayout, magic: &[u8]) -> Result<()> {
        fs::create_dir_all(&self.segment_dir)
            .with_context(|| format!("creating segment dir {:?}", self.segment_dir))?;
        let marker = match layout {
            FilenameLayout::Encoded => {
                segment_filename_layout_v2_marker_path(&self.segment_dir, &self.segment_id)
            }
            FilenameLayout::CaseDistinguished => {
                segment_filename_layout_v3_marker_path(&self.segment_dir, &self.segment_id)
            }
            FilenameLayout::Legacy => return Ok(()),
        };
        match fs::read(&marker) {
            Ok(bytes) if bytes == magic => {
                // A previous attempt can have made the rename visible and
                // then failed its durability confirmation. A fresh writer has
                // no process-local proof, so confirm the directory entry
                // before authorizing encoded side-cars.
                #[cfg(not(windows))]
                xerj_common::fsio::fsync_dir(&self.segment_dir).with_context(|| {
                    format!("confirming FTS filename-layout discriminator {:?}", marker)
                })?;
                // Windows has no parent-directory fsync contract. Replacing
                // the exact marker through MoveFileExW WRITE_THROUGH also
                // repairs a visible discriminator produced by an older build
                // whose Windows directory-sync shim was a no-op.
                #[cfg(windows)]
                xerj_common::fsio::write_file_durable(&marker, magic).with_context(|| {
                    format!("confirming FTS filename-layout discriminator {:?}", marker)
                })?;
            }
            Ok(_) => bail!("corrupt FTS filename-layout discriminator {:?}", marker),
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
                xerj_common::fsio::write_file_durable(&marker, magic).with_context(|| {
                    format!("publishing FTS filename-layout discriminator {:?}", marker)
                })?;
            }
            Err(error) => {
                return Err(error).with_context(|| {
                    format!("reading FTS filename-layout discriminator {:?}", marker)
                });
            }
        }
        self.published_filename_layout = Some(layout);
        Ok(())
    }

    /// Index all text fields of one document.
    ///
    /// `fields` is a map of field name → that field's [`FieldValues`].  Each
    /// value is analyzed independently and separated from the next by
    /// [`POSITION_INCREMENT_GAP`] — a JSON array is N values of the field, not
    /// one joined value (issue #332).
    ///
    /// Fields not previously registered via `configure_field` are indexed
    /// with the default configuration (standard analyzer, positions on).
    pub fn add_document(&mut self, doc_id: u32, fields: &HashMap<String, FieldValues>) {
        for (field_name, values) in fields {
            let registry = Arc::clone(&self.registry);

            // Ensure field entry exists
            if !self.fields.contains_key(field_name) {
                self.fields.insert(
                    field_name.clone(),
                    FieldData {
                        config: Self::unconfigured_field_config(&registry),
                        postings: PostingsWriter::new(),
                        stats: FieldStats::default(),
                        norms: Vec::new(),
                    },
                );
            }

            let field_data = self.fields.get_mut(field_name).unwrap();

            // Resolve analyzer
            let analyzer_name = &field_data.config.analyzer;
            let analyzer = registry
                .get_analyzer(analyzer_name)
                .or_else(|| registry.get_analyzer("standard"))
                .unwrap();

            index_field_values(field_data, &analyzer, doc_id, values.iter());
        }
    }

    /// V4 M4 — **parallel batch** add for flush time.
    ///
    /// Reshapes `(doc_id, field, values)` from row-major (per-doc) into
    /// column-major (per-field) then tokenises + builds per-field
    /// postings in parallel via rayon.  The underlying PostingsWriter
    /// state is still single-threaded per field, but fields run in
    /// parallel, which is the biggest win since nginx logs have ~10
    /// fields and the machine has 32 cores.
    ///
    /// Correctness notes:
    /// - Every field in any doc pre-registers the same `FieldIndexConfig`
    ///   via `configure_field`, so the analyzer resolution is identical
    ///   across threads.
    /// - Doc ordinals are assigned by position in the input `docs` vec,
    ///   matching the row index the caller used with
    ///   `add_document(ordinal, ...)`.
    ///
    /// Generic over the third tuple element (a source payload the caller
    /// keeps alongside for its own use — `serde_json::Value`,
    /// `Arc<serde_json::Value>`, …): this method never reads it.
    pub fn add_documents_parallel<S: Sync>(
        &mut self,
        docs: &[(String, HashMap<String, FieldValues>, S)],
    ) {
        use rayon::prelude::*;
        use std::collections::HashMap as StdHashMap;

        // Column-major reshape: field_name → Vec<(doc_ordinal, values)>.
        // Lookup-first so the common case (field already seen) skips the
        // per-doc-field `field_name.clone()` the `entry()` API forced.
        let mut per_field: StdHashMap<String, Vec<(u32, &FieldValues)>> = StdHashMap::new();
        for (ord, (_id, fields, _src)) in docs.iter().enumerate() {
            for (field_name, values) in fields {
                if let Some(v) = per_field.get_mut(field_name) {
                    v.push((ord as u32, values));
                } else {
                    per_field
                        .entry(field_name.clone())
                        .or_default()
                        .push((ord as u32, values));
                }
            }
        }

        // Pre-register every field so the parallel build picks up the
        // right config.
        for name in per_field.keys() {
            if !self.fields.contains_key(name) {
                self.fields.insert(
                    name.clone(),
                    FieldData {
                        config: Self::unconfigured_field_config(&self.registry),
                        postings: PostingsWriter::new(),
                        stats: FieldStats::default(),
                        norms: Vec::new(),
                    },
                );
            }
        }

        // Process fields in parallel.  Each task owns its own
        // `FieldData` — we swap them back in once the parallel work
        // finishes.
        let registry = Arc::clone(&self.registry);
        let field_configs: StdHashMap<String, FieldIndexConfig> = self
            .fields
            .iter()
            .map(|(k, v)| (k.clone(), v.config.clone()))
            .collect();

        let per_field_vec: Vec<(String, Vec<(u32, &FieldValues)>)> =
            per_field.into_iter().collect();

        let built: Vec<(String, FieldData)> = per_field_vec
            .into_par_iter()
            .map(|(field_name, entries)| {
                let cfg = field_configs
                    .get(&field_name)
                    .cloned()
                    .unwrap_or_else(|| Self::unconfigured_field_config(&registry));
                let analyzer = registry
                    .get_analyzer(&cfg.analyzer)
                    .or_else(|| registry.get_analyzer("standard"))
                    .unwrap();

                let postings = if cfg.store_positions {
                    PostingsWriter::new()
                } else {
                    PostingsWriter::new_no_positions()
                };
                let mut fd = FieldData {
                    config: cfg,
                    postings,
                    stats: FieldStats::default(),
                    norms: Vec::with_capacity(entries.len()),
                };

                for (doc_ord, values) in entries {
                    index_field_values(&mut fd, &analyzer, doc_ord, values.iter());
                }
                (field_name, fd)
            })
            .collect();

        // Swap the built field data back in.
        for (name, fd) in built {
            self.fields.insert(name, fd);
        }
    }

    /// Build every field of this segment by REPLAYING the source segments'
    /// postings, instead of re-analysing their documents.
    ///
    /// This is the merge path.  `write_field_static` has always taken a
    /// `PostingsWriter`, and `PostingsWriter`'s ingest unit has always been a
    /// (term, doc, position) occurrence — never a document — so nothing in
    /// the segment writer needs an analyzer.  The engine's merge nevertheless
    /// walked back to each surviving document's stored JSON, re-extracted its
    /// field values and re-ran the whole analyzer chain, recomputing postings
    /// that were already on disk and already correct.  Under size-tiered
    /// levelling that re-analyses every document O(log N) times (#876).
    ///
    /// What this reproduces exactly, and what it does not:
    ///
    /// * **postings** — doc ids (remapped), term frequencies and positions
    ///   are replayed verbatim from the source `.post` blobs, so `doc_freq`
    ///   and every posting list are identical to a re-analysed merge.
    /// * **norms** — the source's *quantised* byte is carried through
    ///   untouched.  It cannot be recomputed from `field_length`, because
    ///   `norm_u16_to_u8` is lossy and is not invertible.  Every byte a
    ///   reader can observe is the byte re-analysis would have written, but
    ///   the dense array may be SHORTER: byte 0 spells both "field absent"
    ///   and "field length <= 1", `load_norms` drops it on read, so a
    ///   trailing run of byte-0 documents cannot be replayed and the array
    ///   stops at the last non-zero document.  A single-token keyword field
    ///   is entirely byte 0, so its `.norms` shrinks to its header.  Nothing
    ///   a query reads changes — both files load to the identical table.
    /// * **field statistics** — `total_docs` / `total_field_length` are
    ///   carried from the source `.meta` and reduced by the dropped
    ///   documents' contribution.  With no dropped documents (the ordinary
    ///   merge) they are exact.  Two blind spots when documents ARE dropped:
    ///   a dropped document whose value analysed to zero tokens leaves no
    ///   trace in either the postings or the norms, so its `total_docs` seat
    ///   is not reclaimed; and for a docs-only field a dropped document's
    ///   length is read back from the quantised norm byte, which is exact
    ///   only up to length 7.
    /// * **`total_term_frequency`** of a docs-only field becomes its doc
    ///   frequency, because the docs-only `.post` format never stored a
    ///   per-document frequency — its reader synthesises `term_freq = 1`.
    ///   That is the value every reader of the source segment already sees,
    ///   and nothing outside this crate reads `total_term_frequency`.
    ///
    /// Returns `Err` (leaving the writer untouched) when the inputs cannot be
    /// merged this way — a field whose sources disagree about positions, or
    /// whose on-disk shape contradicts the merge-time configuration.  The
    /// caller is expected to fall back to re-analysis rather than to fail the
    /// merge.
    pub fn merge_from_segments(&mut self, sources: &[FtsMergeSource<'_>]) -> Result<()> {
        use rayon::prelude::*;

        let mut field_names: Vec<String> = Vec::new();
        let mut seen: std::collections::HashSet<&str> = std::collections::HashSet::new();
        for source in sources {
            for field in source.reader.indexed_fields() {
                if seen.insert(field) {
                    field_names.push(field.to_owned());
                }
            }
        }
        drop(seen);
        // Deterministic field order keeps a merge reproducible run to run.
        field_names.sort_unstable();

        // Snapshot the configs before the parallel pass so the closure never
        // borrows `self.fields` while the results are being inserted.
        let configs: Vec<FieldIndexConfig> = field_names
            .iter()
            .map(|field| {
                self.fields
                    .get(field)
                    .map(|data| data.config.clone())
                    .unwrap_or_default()
            })
            .collect();

        let built: Vec<Result<FieldData>> = field_names
            .par_iter()
            .zip(configs.par_iter())
            .map(|(field, config)| merge_field_from_segments(field, config, sources))
            .collect();

        // Collect every field before mutating anything: a failure must leave
        // the writer exactly as the caller configured it, so the fallback
        // path starts from a clean slate.
        let mut merged: Vec<(String, FieldData)> = Vec::with_capacity(field_names.len());
        for (field, data) in field_names.into_iter().zip(built) {
            merged.push((field, data?));
        }
        for (field, data) in merged {
            self.fields.insert(field, data);
        }
        Ok(())
    }

    /// Flush all data to disk and return field stats for the segment manifest.
    ///
    /// Field writes run in parallel via Rayon — each thread owns one field's
    /// FST + postings + meta + norms build and writes its four side-car
    /// files independently.  On a 2-text-field nginx log this halves the
    /// flush stall; on a 10-text-field catalog index it's closer to 5×.
    pub fn finish(self) -> Result<HashMap<String, FieldStats>> {
        use rayon::prelude::*;

        let layout = self.required_filename_layout();
        if layout != FilenameLayout::Legacy && self.published_filename_layout != Some(layout) {
            bail!(
                "FTS filename layout {layout:?} requires a durable per-segment layout discriminator"
            );
        }

        fs::create_dir_all(&self.segment_dir)
            .with_context(|| format!("creating segment dir {:?}", self.segment_dir))?;

        let segment_dir = self.segment_dir.clone();
        let segment_id = self.segment_id.clone();
        let zstd_level = self.zstd_level;
        #[cfg(test)]
        let panic_on_field = self.panic_on_field.clone();

        // Drain fields into a Vec so we can parallelise the iterator.
        // Cloning `stats` before consuming `field_data` — `stats` goes into
        // the returned map, `field_data` goes into the writer.
        let fields: Vec<(String, FieldStats, FieldData)> = self
            .fields
            .into_iter()
            .map(|(name, fd)| {
                let stats = fd.stats.clone();
                (name, stats, fd)
            })
            .collect();

        // #937 — record which analyzer each field's postings were built
        // with, but only when some field deviates from `standard`. The
        // engine's merge gate reads this to refuse replaying postings
        // into a term space they were not produced by (a pre-#937
        // `standard` segment inside an index that now honours a declared
        // `default`). An index that declares nothing writes no marker, so
        // its flushes stay byte- and directory-identical to a pre-#937
        // build.
        let recorded: HashMap<&str, &str> = fields
            .iter()
            .map(|(name, _stats, fd)| (name.as_str(), fd.config.analyzer.as_str()))
            .filter(|(_name, analyzer)| *analyzer != "standard")
            .collect();
        // Every side-car of this segment is staged (temp file written and
        // synced) and published together at the end: see `publish_staged`
        // for why that is as durable as one durable write per file, and for
        // the cost it removes (two device flushes per file on Apple targets).
        let mut staged: Vec<xerj_common::fsio::StagedFile> = Vec::new();
        if !recorded.is_empty() {
            #[derive(serde::Serialize)]
            struct Marker<'a> {
                fields: HashMap<&'a str, &'a str>,
            }
            let bytes = serde_json::to_vec(&Marker { fields: recorded })
                .with_context(|| "encoding FTS analyzer marker")?;
            let path = segment_analyzer_marker_path(&segment_dir, &segment_id);
            staged.push(
                xerj_common::fsio::stage_file(&path, &bytes)
                    .with_context(|| format!("writing FTS analyzer marker {:?}", path))?,
            );
        }

        // Parallel field writes.  `write_field_static` is a pure function
        // of its inputs and touches only files named after the field, so
        // there's no cross-thread contention.
        let results: Vec<Result<(String, FieldStats, Vec<xerj_common::fsio::StagedFile>)>> = fields
            .into_par_iter()
            .map(|(field_name, stats, field_data)| {
                // A panic inside `fst::MapBuilder` (its `assert!(out.is_zero())`
                // on a duplicate key the checker missed) or in the meta
                // encoder used to escape the rayon worker and `resume_unwind`
                // the flush task. Indexing then died with no path and no OS
                // error. The same failure is now this field's `Err`.
                #[cfg(test)]
                let panic_this_field = panic_on_field.as_deref() == Some(field_name.as_str());
                let outcome = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                    #[cfg(test)]
                    if panic_this_field {
                        panic!("simulated fst merge panic");
                    }
                    Self::write_field_static(
                        &segment_dir,
                        &segment_id,
                        &field_name,
                        field_data,
                        zstd_level,
                        layout,
                    )
                }));
                match outcome {
                    Ok(result) => {
                        let files =
                            result.with_context(|| format!("writing field '{field_name}'"))?;
                        Ok((field_name, stats, files))
                    }
                    Err(payload) => {
                        bail!(
                            "writing field '{field_name}' panicked: {}",
                            panic_payload_message(&payload)
                        )
                    }
                }
            })
            .collect();

        // Surface any error (dropping `staged` removes every temp file);
        // otherwise build the stats map and publish the side-cars.
        let mut all_stats = HashMap::new();
        for r in results {
            let (name, stats, files) = r?;
            staged.extend(files);
            all_stats.insert(name, stats);
        }
        xerj_common::fsio::publish_staged(&segment_dir, staged)
            .with_context(|| format!("publishing FTS side-cars in {:?}", segment_dir))?;

        Ok(all_stats)
    }

    fn write_field_static(
        segment_dir: &Path,
        segment_id: &str,
        field_name: &str,
        field_data: FieldData,
        zstd_level: i32,
        layout: FilenameLayout,
    ) -> Result<Vec<xerj_common::fsio::StagedFile>> {
        let mut staged = Vec::with_capacity(4);
        // NOTE: `PathBuf::with_extension` replaces the final `.ext` in the path,
        // so using `segment_dir.join("segment_id.field_name")` followed by
        // `with_extension("fst")` would strip `.field_name` and collapse every
        // field to the same file. The shared helper also keeps untrusted field
        // names from becoming paths.
        let filename = |ext: &str| {
            field_sidecar_path_for_layout(segment_dir, segment_id, field_name, ext, layout)
        };
        let fst_path = filename("fst");
        let post_path = filename("post");
        let meta_path = filename("meta");
        let norms_path = filename("norms");

        // 1. Build posting data and collect (term → TermPostings) in sorted order
        let mut post_data: Vec<u8> = Vec::new();
        let mut term_postings: HashMap<String, TermPostings> = HashMap::new();

        // Collect sorted terms (FST requires lexicographic order)
        let mut sorted_terms: Vec<String> =
            field_data.postings.terms().map(|s| s.to_owned()).collect();
        sorted_terms.sort_unstable();

        // Pre-compute per-term (doc_freq, ttf) ONCE.  The previous code
        // called `term_stats().find(..)` INSIDE the per-term loop — an
        // O(T²) scan that also re-summed every candidate's ttf on each
        // probe.  On numeric-heavy segments (thousands of distinct terms
        // per field, e.g. `latency_ms`/`@timestamp` string tokens) this
        // was the dominant flush-finalize CPU cost.
        let stats_by_term: HashMap<&str, (u32, u64)> = field_data
            .postings
            .term_stats()
            .map(|(t, df, ttf)| (t, (df, ttf)))
            .collect();

        for term in &sorted_terms {
            if let Some((offset, _skip)) = field_data.postings.encode_term(term, &mut post_data) {
                // Calculate doc_freq and ttf from the writer's internal stats
                let (doc_freq, ttf) = stats_by_term.get(term.as_str()).copied().unwrap_or((0, 0));

                let end_offset = post_data.len() as u64;
                let length = (end_offset - offset) as u32;

                term_postings.insert(
                    term.clone(),
                    TermPostings {
                        doc_frequency: doc_freq,
                        total_term_frequency: ttf,
                        postings_offset: offset,
                        postings_length: length,
                    },
                );
            }
        }

        // 2. Write postings file, wrapped in the `ZPS2` Zstd envelope.
        //
        // Bit-packed doc-id blocks look high-entropy to casual eyes
        // but the residual sections, vbyte run-lengths, and block-
        // level `num_bits` headers carry enough repetition that the
        // wrapper is worth it.  Zstd-19 squeezes ~1.4× tighter than
        // LZ4 on the XERJ bench's keyword-heavy postings (`name`
        // and `k` fields dominate).  Old segments using the ZPS1/ZPL1
        // envelopes and the pre-magic raw mmap path are still
        // readable — see the open path's auto-detect block.
        //
        // Layout:
        //   "ZPS2"             4 bytes magic (also the inner-framing version)
        //   uncompressed_len   u32 little-endian
        //   payload            compressed_len bytes (zstd)
        let post_bytes_wrapped: Vec<u8> = if post_data.is_empty() {
            Vec::new()
        } else {
            let uncompressed_len = post_data.len() as u32;
            let compressed = zstd::bulk::compress(&post_data, zstd_level)
                .with_context(|| "ZPS2 zstd compress")?;
            let mut out = Vec::with_capacity(4 + 4 + compressed.len());
            out.extend_from_slice(POST_MAGIC_ZSTD_V2);
            out.write_u32::<LittleEndian>(uncompressed_len).unwrap();
            out.extend_from_slice(&compressed);
            out
        };
        // RC4 W1 #10 — every FTS side-car below is staged (synced temp file)
        // and published durably by `finish` through `fsio::publish_staged`:
        // rename and parent-directory fsync on Unix, write-through
        // replacement on Windows. These files are part of the segment publish
        // chain: the WAL entries they cover are pruned ~1 s after the flush,
        // so side-cars sitting only in the volatile page cache meant a power
        // loss could leave a registered segment with missing/torn FTS data
        // (silently wrong query results or unreadable fields) with no WAL to
        // recover from.
        staged.push(
            xerj_common::fsio::stage_file(&post_path, &post_bytes_wrapped)
                .with_context(|| format!("writing postings to {:?}", post_path))?,
        );

        // 3. Build and write FST (term → meta byte offset).
        //
        // Pre-ZFM3 the FST value was `postings_offset` and the reader
        // had to look up `{df, ttf, length}` via a second HashMap<String,
        // TermPostings> lookup in the meta file.  Storing term strings
        // twice (once in the FST, once in the meta) was pure overhead on
        // high-cardinality keyword fields (~20 B/term).  Now the FST
        // value is the byte offset of the term's fixed-24-byte record
        // inside the meta's flat array — `meta[offset..offset + 24]`
        // holds df + ttf + postings_offset + length, so one FST hit →
        // one bounded mmap read.
        // FST streams into a same-directory temp file; fsync + rename +
        // platform-specific durable replacement publishes it (RC4 W1 #10 —
        // see the postings note above).
        let fst_tmp = unique_temp_sibling(&fst_path);
        // Declared before the builder so unwind drops the file (closes it)
        // and only then deletes the temp. Armed until `stage_written_file`
        // takes ownership.
        let mut fst_tmp_cleanup = DeleteOnDrop::arm(fst_tmp.clone());
        let fst_file = BufWriter::new(
            File::create(&fst_tmp).with_context(|| format!("creating FST file {:?}", fst_tmp))?,
        );
        let mut fst_builder = MapBuilder::new(fst_file).with_context(|| "creating FST builder")?;

        // The i-th sorted term gets record slot `i`, whose byte offset
        // inside the flat meta array is `ZFM3_HEADER_LEN + i * 24`.  We
        // iterate the same sorted_terms list that built the meta body,
        // so ordering is consistent.
        for (i, term) in sorted_terms.iter().enumerate() {
            if term_postings.contains_key(term) {
                let meta_offset = (ZFM3_HEADER_LEN + i * ZFM3_RECORD_LEN) as u64;
                fst_builder
                    .insert(term.as_bytes(), meta_offset)
                    .with_context(|| format!("inserting term '{}' into FST", term))?;
            }
        }
        let mut fst_out = fst_builder.into_inner().with_context(|| "finishing FST")?;
        fst_out.flush().with_context(|| "flushing FST")?;
        staged.push(
            xerj_common::fsio::stage_written_file(&fst_tmp, &fst_path, fst_out.get_ref())
                .with_context(|| "fsyncing FST")?,
        );
        fst_tmp_cleanup.disarm();
        drop(fst_out);

        // 4. Write meta in the ZFM5 format — columnar varint streams
        //    (df, ttf-delta, gaps, lengths) under the Zstd envelope;
        //    ZFM3-compatible header so `lookup_term` can expand once at
        //    open time and use the in-memory `flat_records` Vec exactly
        //    as before.
        let has_positions = field_data.config.store_positions;
        let meta_bytes = encode_field_meta_v5(
            &field_data.stats,
            has_positions,
            &sorted_terms,
            &term_postings,
            zstd_level,
        )?;
        staged.push(
            xerj_common::fsio::stage_file(&meta_path, &meta_bytes)
                .with_context(|| format!("writing meta to {:?}", meta_path))?,
        );

        // 5. Write norms file — V4 M4.7 compact format.
        //
        // Old format was `(u32 doc_id, u16 norm)` pairs = 6 B per live
        // doc per field.  On 66.5 M nginx × 10 fields that was 3.99 GB
        // for norms alone (60 B/doc).  The new format stores ONE byte
        // per doc at the implicit index `doc_id`, using Lucene's
        // logarithmic quantisation: `byte ≈ norm_to_byte(field_len)`.
        // Missing docs get byte 0 (norm = 0).  Sparse fields still benefit
        // because the file is LZ4-compressed when > 1 KB of runs-of-zeros
        // make it worthwhile.
        //
        // Layout:
        //   "ZNM1"     4 bytes magic
        //   u8         encoding: 0 = dense u8, 1 = dense u8 + LZ4
        //   u32        max_doc_id + 1   (size of implicit array)
        //   u32        payload_len
        //   payload    dense array (u8 × max_doc_id+1) or LZ4(dense)
        let mut norms = field_data.norms;
        norms.sort_unstable_by_key(|(doc_id, _)| *doc_id);
        let max_doc_id: u32 = norms.last().map(|(d, _)| *d).unwrap_or(0);
        let dense_len = (max_doc_id as usize).saturating_add(1);
        let mut dense: Vec<u8> = vec![0u8; dense_len];
        for (doc_id, norm_byte) in &norms {
            dense[*doc_id as usize] = *norm_byte;
        }

        // Try LZ4 when the dense array is big enough for compression
        // to pay off (long runs of identical norms on low-entropy fields
        // like nginx `method` compress ~8×).
        let lz4_try = lz4_flex::compress_prepend_size(&dense);
        let (encoding, payload): (u8, &[u8]) = if dense.len() > 1024 && lz4_try.len() < dense.len()
        {
            (1, &lz4_try[..])
        } else {
            (0, &dense[..])
        };

        let mut norms_bytes: Vec<u8> = Vec::with_capacity(4 + 1 + 4 + 4 + payload.len());
        norms_bytes.extend_from_slice(NORMS_MAGIC);
        norms_bytes.push(encoding);
        norms_bytes.extend_from_slice(&(dense_len as u32).to_le_bytes());
        norms_bytes.extend_from_slice(&(payload.len() as u32).to_le_bytes());
        norms_bytes.extend_from_slice(payload);
        staged.push(
            xerj_common::fsio::stage_file(&norms_path, &norms_bytes)
                .with_context(|| format!("writing norms to {:?}", norms_path))?,
        );

        Ok(staged)
    }
}

/// One input segment of a postings-level merge.
///
/// See [`FtsIndexWriter::merge_from_segments`].
pub struct FtsMergeSource<'a> {
    /// A full (NOT `open_stats_only`) reader over the source segment.
    pub reader: &'a FtsIndexReader,
    /// Source document ordinal → merged document ordinal, `None` for a
    /// document the merge drops.  Exactly one entry per document in the
    /// source segment, in that segment's own ordinal order — which is the
    /// order its stored section holds, the same alignment the doc-values
    /// side-car already relies on.
    pub doc_map: &'a [Option<u32>],
}

/// Build one merged field by replaying every source segment's postings.
fn merge_field_from_segments(
    field: &str,
    config: &FieldIndexConfig,
    sources: &[FtsMergeSource<'_>],
) -> Result<FieldData> {
    let inputs: Vec<&FtsMergeSource<'_>> = sources
        .iter()
        .filter(|source| source.reader.field_stats(field).is_some())
        .collect();

    let Some(first) = inputs.first() else {
        return Ok(FieldData {
            config: config.clone(),
            postings: if config.store_positions {
                PostingsWriter::new()
            } else {
                PostingsWriter::new_no_positions()
            },
            stats: FieldStats::default(),
            norms: Vec::new(),
        });
    };

    // A posting list's on-disk shape decides how it decodes, so every input
    // must agree with every other AND with what this writer would emit.
    // Anything else would be a re-encode, not a merge — the caller
    // re-analyses instead.
    let has_positions = first.reader.field_has_positions(field);
    for source in &inputs {
        if source.reader.field_has_positions(field) != has_positions {
            bail!("FTS merge: sources disagree on positions for field '{field}'");
        }
    }
    if has_positions != config.store_positions {
        bail!(
            "FTS merge: field '{field}' is stored with store_positions={has_positions} but the \
             merge configuration asks for {}",
            config.store_positions
        );
    }

    let mut postings = if has_positions {
        PostingsWriter::new()
    } else {
        PostingsWriter::new_no_positions()
    };
    let mut norms: Vec<(u32, u8)> = Vec::new();
    let mut stats = FieldStats::default();

    for source in &inputs {
        let source_stats = source
            .reader
            .field_stats(field)
            .expect("filtered to the sources that carry this field")
            .clone();
        let doc_count = source.doc_map.len();
        // One flag per source document: which documents the postings mention.
        // A dropped document that no posting mentions had zero tokens, and
        // its `total_docs` seat is unreclaimable — see the method docs.
        let mut had_posting = vec![false; doc_count];
        let mut dropped_token_count: u64 = 0;
        let mut failure: Option<String> = None;

        source.reader.for_each_term(field, |term| {
            let Some(term_postings) = source.reader.lookup_term(field, term) else {
                failure = Some(format!(
                    "term '{term}' of field '{field}' is in the FST but not in the .meta"
                ));
                return false;
            };
            let Some(data) = source.reader.postings_data(field, &term_postings) else {
                failure = Some(format!(
                    "field '{field}' has no postings bytes for term '{term}' (a stats-only \
                     reader cannot be merged)"
                ));
                return false;
            };
            let codec = if source.reader.field_post_block_v2(field) {
                crate::postings::PostCodec::v2_for(
                    has_positions,
                    term_postings.total_term_frequency,
                    term_postings.doc_frequency,
                )
            } else {
                crate::postings::PostCodec::V1
            };
            let mut decoded = crate::postings::PostingsReader::new_with_codec(
                data,
                term_postings.doc_frequency,
                has_positions,
                codec,
            );
            // One run per (source, term), handed to the writer in one call:
            // a per-occurrence hand-off would re-descend the term BTreeMap
            // for every token in the corpus.
            let mut run: Vec<crate::postings::DecodedPosting> =
                Vec::with_capacity(term_postings.doc_frequency as usize);
            while let Some(mut posting) = decoded.next() {
                let ordinal = posting.doc_id as usize;
                if ordinal >= doc_count {
                    failure = Some(format!(
                        "field '{field}' has a posting for doc {ordinal}, past the {doc_count} \
                         documents the caller mapped"
                    ));
                    return false;
                }
                had_posting[ordinal] = true;
                match source.doc_map[ordinal] {
                    Some(merged) => {
                        posting.doc_id = merged;
                        run.push(posting);
                    }
                    None => dropped_token_count += posting.term_freq as u64,
                }
            }
            postings.extend_postings(term, run);
            true
        });
        if let Some(message) = failure {
            bail!("FTS merge: {message}");
        }
        // An input that maps no documents puts nothing into the output, so it
        // contributes no statistics either.  Any input that DOES have
        // postings while mapping no documents was already refused above.
        if doc_count == 0 {
            continue;
        }

        let mut norm_bytes = vec![0u8; doc_count];
        for (doc_id, byte) in source.reader.field_norm_bytes(field) {
            let ordinal = doc_id as usize;
            if ordinal >= doc_count {
                bail!(
                    "FTS merge: field '{field}' has a norm for doc {ordinal}, past the \
                     {doc_count} documents the caller mapped"
                );
            }
            norm_bytes[ordinal] = byte;
        }

        let mut dropped_docs: u64 = 0;
        let mut dropped_quantised_length: u64 = 0;
        for (ordinal, &byte) in norm_bytes.iter().enumerate() {
            match source.doc_map[ordinal] {
                // Byte 0 is how the dense norms array spells BOTH "field
                // absent" and "field length 1", and `load_norms` drops it on
                // read, so a byte-0 entry cannot be recovered here and is not
                // pushed.  Every byte a reader can observe is therefore the
                // byte a re-analysing writer would have written — but NOT the
                // array's length: re-analysis pushes an entry for every doc
                // that CARRIES the field, byte 0 included, and
                // `write_field_static` sizes the dense array from the last
                // entry.  When the highest-ordinal doc carrying the field
                // quantises to 0 (field length <= 1: every single-token
                // keyword field), the replayed `.norms` stops at the last
                // NON-zero doc and is shorter, with the difference being
                // trailing zeros only.  `load_norms` filters `b != 0`, so both
                // files load to the identical norms table and no hit, score or
                // `field_length` moves.  Pinned by
                // `merge_postings_equivalence.rs::
                // a_single_token_field_replays_an_equivalent_shorter_norms_array`.
                Some(merged) => {
                    if byte != 0 {
                        norms.push((merged, byte));
                    }
                }
                None => {
                    if had_posting[ordinal] {
                        dropped_docs += 1;
                        dropped_quantised_length += norm_u8_to_u16(byte) as u64;
                    }
                }
            }
        }

        stats.total_docs += source_stats.total_docs.saturating_sub(dropped_docs);
        // A positioned field knows each dropped document's exact token count
        // (the sum of its term frequencies).  A docs-only field does not —
        // its `.post` never stored one — so its dropped length comes from the
        // quantised norm byte, which is exact up to length 7.
        let dropped_length = if has_positions {
            dropped_token_count
        } else {
            dropped_quantised_length
        };
        stats.total_field_length += source_stats
            .total_field_length
            .saturating_sub(dropped_length);
    }

    // The inputs' surviving documents interleave in the merged ordinal space,
    // so a term shared by several of them arrives as several ascending runs.
    postings.sort_postings_by_doc();

    Ok(FieldData {
        config: config.clone(),
        postings,
        stats,
        norms,
    })
}

/// Every field name each of `segment_ids` holds FTS side-cars for, in the same
/// order as `segment_ids`.
///
/// A segment's field set is whatever its documents happened to carry, so it is
/// not derivable from the mapping; the merge path needs it to know which
/// readers to open.  A portable field name IS its own filename component and
/// reads straight back; a digest-encoded component is resolved against
/// `known_fields`, and an unresolvable one is an error rather than a silent
/// omission — dropping a field here would drop its postings from the merged
/// segment and silently stop its terms matching.
///
/// Takes the whole batch at once because it costs ONE directory scan. A
/// converging index keeps thousands of segments in this directory (tens of
/// thousands of side-car files), and a merge batch has up to sixteen inputs:
/// scanning per input would re-walk that directory sixteen times per batch.
pub fn segments_indexed_field_names(
    segment_dir: &Path,
    segment_ids: &[&str],
    known_fields: &[String],
) -> Result<Vec<Vec<String>>> {
    let mut encoded: HashMap<String, &str> = HashMap::new();
    for name in known_fields {
        // v2 and v3 hash unsafe names identically. v3 also hashes case-unstable
        // literals (`page_Id`) that v2 stored under the raw spelling, so a
        // directory scan has to recognize both components.
        for component in [field_file_component(name), field_file_component_v3(name)] {
            if let Cow::Owned(component) = component {
                encoded.insert(component, name.as_str());
            }
        }
    }

    let prefixes: Vec<String> = segment_ids.iter().map(|id| format!("{id}.")).collect();
    let mut per_segment: Vec<Vec<String>> = vec![Vec::new(); segment_ids.len()];
    let mut seen: Vec<std::collections::HashSet<String>> =
        vec![std::collections::HashSet::new(); segment_ids.len()];

    let entries = fs::read_dir(segment_dir)
        .with_context(|| format!("listing segment dir {:?}", segment_dir))?;
    for entry in entries {
        let entry = entry.with_context(|| format!("reading segment dir {:?}", segment_dir))?;
        let file_name = entry.file_name();
        let Some(file_name) = file_name.to_str() else {
            continue;
        };
        for (index, prefix) in prefixes.iter().enumerate() {
            let Some(rest) = file_name.strip_prefix(prefix.as_str()) else {
                continue;
            };
            // Only the FST is enumerated: it is the file `FtsIndexReader::open`
            // gates a field's existence on, and taking one extension keeps a
            // four-file family from being counted four times.  `.fst.tmp`
            // leftovers fall out here too — their final component is `tmp`.
            let Some((component, extension)) = rest.rsplit_once('.') else {
                break;
            };
            if extension != "fst" || component.is_empty() {
                break;
            }
            let name = if component.starts_with(ENCODED_FIELD_COMPONENT_PREFIX) {
                match encoded.get(component) {
                    Some(name) => (*name).to_owned(),
                    None => bail!(
                        "segment {} has an FTS side-car component that no known field name \
                         digests to: {component}",
                        segment_ids[index]
                    ),
                }
            } else {
                component.to_owned()
            };
            if seen[index].insert(name.clone()) {
                per_segment[index].push(name);
            }
            break;
        }
    }

    for names in &mut per_segment {
        names.sort_unstable();
    }
    Ok(per_segment)
}

/// [`segments_indexed_field_names`] for a single segment.
pub fn segment_indexed_field_names(
    segment_dir: &Path,
    segment_id: &str,
    known_fields: &[String],
) -> Result<Vec<String>> {
    let mut names = segments_indexed_field_names(segment_dir, &[segment_id], known_fields)?;
    Ok(names.pop().unwrap_or_default())
}

const NORMS_MAGIC: &[u8; 4] = b"ZNM1";

/// Lucene-style logarithmic norm quantisation: maps a u16 field length
/// onto a u8.  Exactly 256 values with finer resolution at short lengths
/// (where BM25 is most sensitive).  Inverse loses precision at long
/// lengths, same as Lucene's `SmallFloat`.
#[inline]
fn norm_u16_to_u8(len: u16) -> u8 {
    if len == 0 {
        return 0;
    }
    // Clamp short lengths [1..8] to direct encoding (0..7).
    if len < 8 {
        return (len - 1) as u8 & 0x07;
    }
    // Logarithmic scale beyond 8.
    let l = (len as f64).log2();
    let v = ((l - 3.0) * 32.0 + 8.0) as i32;
    v.clamp(0, 255) as u8
}

#[inline]
fn norm_u8_to_u16(b: u8) -> u16 {
    if b < 8 {
        return (b + 1) as u16;
    }
    let l = ((b - 8) as f64) / 32.0 + 3.0;
    let v = l.exp2();
    v.min(u16::MAX as f64) as u16
}

// ── FtsIndexReader ────────────────────────────────────────────────────────────

/// Provides term lookup into a segment's FTS data.
///
/// Designed for mmap-friendly usage: the FST and postings data can be backed
/// by `memmap2::Mmap` buffers; only the meta JSON and norms are read eagerly.
pub struct FtsIndexReader {
    #[allow(dead_code)]
    segment_dir: PathBuf,
    #[allow(dead_code)]
    segment_id: String,
    /// Loaded per-field data
    fields: HashMap<String, LoadedField>,
    /// Set by [`FtsIndexReader::open_stats_only`]: the postings envelope and
    /// the norms table were NOT loaded, so this reader can answer
    /// `field_stats` / `term_doc_freq` (FST + `.meta` only) and nothing else.
    /// `postings_data` and `field_length` fail closed (`None`) rather than
    /// silently returning empty payloads — a stats-only reader handed to the
    /// searcher must produce zero hits, never wrong ones.
    stats_only: bool,
}

/// Backing storage for a field's postings bytes.
///
/// We prefer `Mmap` so `FtsIndexReader::open` allocates almost nothing per
/// segment and the OS page cache serves hot byte ranges.  Falls back to an
/// owned `Vec<u8>` when the file is in a read-only filesystem / tmpfs that
/// refuses to mmap (rare in practice but safer than panicking).
enum PostData {
    Mmap(Mmap),
    Owned(Vec<u8>),
}

impl PostData {
    #[inline]
    fn as_bytes(&self) -> &[u8] {
        match self {
            PostData::Mmap(m) => &m[..],
            PostData::Owned(v) => v.as_slice(),
        }
    }
}

/// Backing storage for a field's FST (term dictionary).
///
/// `fst::Map` is generic over `T: AsRef<[u8]>`.  `Mmap` implements
/// `AsRef<[u8]>` so `Map<Mmap>` is the mmap-backed fast path;
/// `Map<Vec<u8>>` is the owned fallback for filesystems that refuse mmap.
enum FstData {
    Mmap(Map<Mmap>),
    Owned(Map<Vec<u8>>),
}

impl FstData {
    #[inline]
    fn get(&self, key: &[u8]) -> Option<u64> {
        match self {
            FstData::Mmap(m) => m.get(key),
            FstData::Owned(m) => m.get(key),
        }
    }
}

struct LoadedField {
    /// FST term dictionary — mmap'd where possible.
    fst: FstData,
    /// Raw postings bytes — mmap'd where possible.
    post_data: PostData,
    /// The envelope magic said `ZPS2`: the inner block framing is the
    /// frame-of-reference layout (see `xerj_fts::postings`).  Every other
    /// envelope (ZPS1, ZPL1, raw) predates it and decodes as `PostCodec::V1`.
    post_block_v2: bool,
    /// Pre-parsed metadata (term postings, field stats) — small, stays owned.
    meta: FieldMeta,
    /// `(doc_id, field_length, quantised norm byte)`, sorted by doc_id.
    ///
    /// The raw byte rides along beside the dequantised length because the
    /// merge path must reproduce the source segment's norms file byte for
    /// byte: `norm_u16_to_u8(norm_u8_to_u16(b)) != b` for most `b`, so
    /// re-quantising the length would move BM25's length normalisation on
    /// every merged document.  `(u32, u16, u8)` still occupies 8 bytes
    /// after padding, so this costs no memory over the old `(u32, u16)`.
    norms: Vec<(u32, u16, u8)>,
}

impl FtsIndexReader {
    /// Load an existing segment's FTS data from disk.
    pub fn open(
        segment_dir: impl AsRef<Path>,
        segment_id: impl Into<String>,
        field_names: &[&str],
    ) -> Result<Self> {
        Self::open_inner(segment_dir, segment_id, field_names, false)
    }

    /// Upper estimate of the heap a full [`Self::open`] of `field_names`
    /// would retain, read from file headers and sizes only (#2427/#1122).
    ///
    /// Lets the engine reserve read memory *before* it pays the postings
    /// decompress. Per field: the uncompressed postings length from the
    /// `ZPS1`/`ZPS2`/`ZPL1` envelope header (or the file length of a raw
    /// `.post`), the `.fst` file length, 8 bytes per dense norms entry, and
    /// the decoded `.meta` term records (`num_terms` from its header). A field whose files are
    /// missing or unreadable counts as zero — `open` will fail or skip it.
    pub fn estimate_open_bytes(
        segment_dir: impl AsRef<Path>,
        segment_id: &str,
        field_names: &[&str],
    ) -> u64 {
        use std::io::Read;
        let segment_dir = segment_dir.as_ref();
        let Ok(layout) = segment_filename_layout(segment_dir, segment_id) else {
            return 0;
        };
        let head = |path: &Path, n: usize| -> Option<Vec<u8>> {
            let mut buf = vec![0u8; n];
            let mut file = fs::File::open(path).ok()?;
            file.read_exact(&mut buf).ok()?;
            Some(buf)
        };
        let mut total: u64 = 0;
        for &field_name in field_names {
            let filename = |ext: &str| -> Option<PathBuf> {
                match layout {
                    FilenameLayout::Legacy => {
                        legacy_field_sidecar_path(segment_dir, segment_id, field_name, ext)
                    }
                    FilenameLayout::Encoded | FilenameLayout::CaseDistinguished => {
                        Some(field_sidecar_path_for_layout(
                            segment_dir,
                            segment_id,
                            field_name,
                            ext,
                            layout,
                        ))
                    }
                }
            };
            total = total.saturating_add(field_name.len() as u64);
            if let Some(post) = filename("post") {
                if let Some(h) = head(&post, 8) {
                    let magic = &h[..4];
                    if magic == POST_MAGIC_ZSTD_V2
                        || magic == POST_MAGIC_ZSTD
                        || magic == POST_MAGIC_LZ4
                    {
                        let len = u32::from_le_bytes([h[4], h[5], h[6], h[7]]);
                        total = total.saturating_add(u64::from(len));
                    } else {
                        // Raw postings: mmap'd or read whole; count the file.
                        let len = fs::metadata(&post).map(|m| m.len()).unwrap_or(0);
                        total = total.saturating_add(len);
                    }
                }
            }
            if let Some(fst) = filename("fst") {
                // An FST that cannot be mmap'd is read whole.
                let len = fs::metadata(&fst).map(|m| m.len()).unwrap_or(0);
                total = total.saturating_add(len);
            }
            if let Some(norms) = filename("norms") {
                let entries = match head(&norms, 9) {
                    Some(h) if &h[..4] == NORMS_MAGIC => {
                        u64::from(u32::from_le_bytes([h[5], h[6], h[7], h[8]]))
                    }
                    _ => fs::metadata(&norms).map(|m| m.len()).unwrap_or(0),
                };
                total = total.saturating_add(entries.saturating_mul(8));
            }
            if let Some(meta) = filename("meta") {
                // `num_terms` sits at byte 20 of every ZFM header.
                // ZFM3/4/5 expand to 24-byte flat records; legacy ZFM1/2
                // keep a term map (`retained_bytes` counts 64 B per term)
                // plus the term strings, which the file length covers.
                let len = fs::metadata(&meta).map(|m| m.len()).unwrap_or(0);
                let add = match head(&meta, 24) {
                    Some(h) => {
                        let terms = u64::from(u32::from_le_bytes([h[20], h[21], h[22], h[23]]));
                        let magic = &h[..4];
                        if magic == META_MAGIC_V1 || magic == META_MAGIC_V2 {
                            terms.saturating_mul(64).saturating_add(len)
                        } else {
                            terms.saturating_mul(ZFM3_RECORD_LEN as u64)
                        }
                    }
                    None => len.saturating_mul(4),
                };
                total = total.saturating_add(add);
            }
        }
        total
    }

    /// Open ONLY what BM25 collection statistics need: the FST term
    /// dictionary (mmap'd) and the small `.meta` side-car.
    ///
    /// Skips the two expensive parts of a full [`Self::open`]:
    ///
    ///  * the postings envelope — a whole-file `fs::read` plus a zstd
    ///    decompress of every posting list in the field, O(index bytes);
    ///  * the norms table — a whole-file `fs::read` plus decode, O(docs).
    ///
    /// That makes the per-segment `field_stats` + `term_doc_freq` pre-pass
    /// the index-wide scorer needs (#188) cost, per field, one mmap plus one
    /// `.meta` read-and-decode — for the current ZFM4 format that decode is
    /// a zstd decompress of the `num_terms × 24`-byte records section, i.e.
    /// O(field vocabulary), cheap but not free (#193) — instead of re-paying
    /// the full open a second time.
    ///
    /// The returned reader can answer [`Self::field_stats`],
    /// [`Self::term_doc_freq`] and [`Self::lookup_term`]; [`Self::postings_data`]
    /// and [`Self::field_length`] return `None` on it by construction, so
    /// handing one to a searcher yields zero hits rather than wrong ones.
    pub fn open_stats_only(
        segment_dir: impl AsRef<Path>,
        segment_id: impl Into<String>,
        field_names: &[&str],
    ) -> Result<Self> {
        Self::open_inner(segment_dir, segment_id, field_names, true)
    }

    fn open_inner(
        segment_dir: impl AsRef<Path>,
        segment_id: impl Into<String>,
        field_names: &[&str],
        stats_only: bool,
    ) -> Result<Self> {
        let segment_dir = segment_dir.as_ref().to_path_buf();
        let segment_id = segment_id.into();
        let layout = segment_filename_layout(&segment_dir, &segment_id)?;
        let mut fields = HashMap::new();

        for &field_name in field_names {
            // The immutable segment discriminator is the sole authority.
            // Existence is deliberately irrelevant: otherwise a v1 field
            // whose literal name equals another field's digest component can
            // alias, and partial or stray files can alter layout selection.
            // A v2 marker keeps mixed-case literals (`page_Id.fst`) on the
            // v2 path; only a v3 marker looks up the case-distinguished digest.
            let filename = |ext: &str| -> Option<PathBuf> {
                match layout {
                    FilenameLayout::Legacy => {
                        legacy_field_sidecar_path(&segment_dir, &segment_id, field_name, ext)
                    }
                    FilenameLayout::Encoded | FilenameLayout::CaseDistinguished => {
                        Some(field_sidecar_path_for_layout(
                            &segment_dir,
                            &segment_id,
                            field_name,
                            ext,
                            layout,
                        ))
                    }
                }
            };
            let Some(fst_path) = filename("fst") else {
                continue;
            };
            let post_path =
                filename("post").expect("FTS family path containment is extension-invariant");
            let meta_path =
                filename("meta").expect("FTS family path containment is extension-invariant");
            let norms_path =
                filename("norms").expect("FTS family path containment is extension-invariant");

            // Skip fields that haven't been indexed yet
            if !fst_path.exists() {
                continue;
            }

            // ── FST ──────────────────────────────────────────────────
            // Prefer mmap; fall back to fs::read if mmap fails (tmpfs etc.).
            let fst = match Self::mmap_file(&fst_path) {
                Ok(mmap) => {
                    FstData::Mmap(Map::new(mmap).with_context(|| "parsing FST map (mmap)")?)
                }
                Err(_) => {
                    let fst_bytes = fs::read(&fst_path)
                        .with_context(|| format!("reading FST {:?}", fst_path))?;
                    FstData::Owned(Map::new(fst_bytes).with_context(|| "parsing FST map (owned)")?)
                }
            };

            // ── Postings ─────────────────────────────────────────────
            //
            // Format detection (in priority order):
            //   * `ZPS2` magic → Zstd envelope, ZPS2 inner framing (FOR
            //     blocks, derived lengths, freq elision on ttf == df).
            //     Current writer.
            //   * `ZPS1` magic → legacy Zstd envelope with the old inner
            //     framing; same decompress path, `PostCodec::V1` decode.
            //   * `ZPL1` magic → legacy LZ4 envelope; same path,
            //     different codec.  Old segments stay readable.
            //   * No magic → pre-envelope raw bytes; mmap if the FS
            //     allows it, otherwise read into an owned buffer.
            //
            // The query path references `post_data` by slice in all
            // cases, so there's no per-query decompress cost.
            //
            // STATS-ONLY: skip the read + decompress entirely — the caller
            // only wants `field_stats`/`term_doc_freq`, both of which live
            // in `.meta`/`.fst`.
            let raw_post = if stats_only {
                Vec::new()
            } else {
                fs::read(&post_path).with_context(|| format!("reading postings {:?}", post_path))?
            };
            let zstd_envelope = raw_post.len() >= 8
                && (&raw_post[..4] == POST_MAGIC_ZSTD_V2 || &raw_post[..4] == POST_MAGIC_ZSTD);
            let post_block_v2 = raw_post.len() >= 4 && &raw_post[..4] == POST_MAGIC_ZSTD_V2;
            let post_data = if zstd_envelope {
                let mut len_buf = [0u8; 4];
                len_buf.copy_from_slice(&raw_post[4..8]);
                let uncompressed_len = u32::from_le_bytes(len_buf) as usize;
                let decompressed = zstd::bulk::decompress(&raw_post[8..], uncompressed_len)
                    .map_err(|e| anyhow::anyhow!("ZPS postings decompress failed: {e}"))?;
                PostData::Owned(decompressed)
            } else if raw_post.len() >= 4 && &raw_post[..4] == POST_MAGIC_LZ4 {
                let decompressed = lz4_flex::decompress_size_prepended(&raw_post[4..])
                    .map_err(|e| anyhow::anyhow!("ZPL1 postings decompress failed: {e}"))?;
                PostData::Owned(decompressed)
            } else if !raw_post.is_empty() {
                // Legacy raw path — prefer mmap, fall back to owned.
                match Self::mmap_file(&post_path) {
                    Ok(mmap) => PostData::Mmap(mmap),
                    Err(_) => PostData::Owned(raw_post),
                }
            } else {
                PostData::Owned(Vec::new())
            };

            // ── Meta + norms — small, read eagerly ───────────────────
            // Auto-detect the on-disk format: ZFM1 binary (new) vs
            // legacy pretty-JSON (from pre-M4.7 segments).  We keep the
            // JSON fallback so upgrades don't require a reindex.
            let meta_bytes =
                fs::read(&meta_path).with_context(|| format!("reading meta {:?}", meta_path))?;
            let is_binary = meta_bytes.len() >= 4
                && (&meta_bytes[..4] == META_MAGIC_V1
                    || &meta_bytes[..4] == META_MAGIC_V2
                    || &meta_bytes[..4] == META_MAGIC_V3
                    || &meta_bytes[..4] == META_MAGIC_V4
                    || &meta_bytes[..4] == META_MAGIC_V5);
            let meta: FieldMeta = if is_binary {
                decode_field_meta_binary(&meta_bytes)
                    .with_context(|| "parsing binary field meta")?
            } else {
                // Legacy JSON path — same shape as before the refactor.
                #[derive(Deserialize)]
                struct LegacyFieldMeta {
                    stats: FieldStats,
                    terms: HashMap<String, LegacyTermPostings>,
                }
                #[derive(Deserialize)]
                struct LegacyTermPostings {
                    doc_frequency: u32,
                    total_term_frequency: u64,
                    postings_offset: u64,
                    postings_length: u32,
                }
                let legacy: LegacyFieldMeta = serde_json::from_slice(&meta_bytes)
                    .with_context(|| "parsing legacy field meta JSON")?;
                FieldMeta {
                    stats: legacy.stats,
                    terms: legacy
                        .terms
                        .into_iter()
                        .map(|(k, v)| {
                            (
                                k,
                                SerialTermPostings {
                                    doc_frequency: v.doc_frequency,
                                    total_term_frequency: v.total_term_frequency,
                                    postings_offset: v.postings_offset,
                                    postings_length: v.postings_length,
                                },
                            )
                        })
                        .collect(),
                    has_positions: true, // legacy segments always had positions
                    fst_value_format: FstValueFormat::PostingsOffset,
                    flat_records: Vec::new(),
                }
            };

            // STATS-ONLY: the norms table is a whole-file read + decode that
            // is O(docs); the statistics pre-pass never asks for a doc length.
            let norms = if stats_only {
                Vec::new()
            } else {
                Self::load_norms(&norms_path)?
            };

            fields.insert(
                field_name.to_owned(),
                LoadedField {
                    fst,
                    post_data,
                    post_block_v2,
                    meta,
                    norms,
                },
            );
        }

        Ok(Self {
            segment_dir,
            segment_id,
            fields,
            stats_only,
        })
    }

    /// Memory-map a file.
    ///
    /// SAFETY: mmap is unsafe in Rust because another process could mutate
    /// the file under us.  In xerj segment files are written once to a
    /// staging path and `rename`d atomically; after rename they're
    /// immutable until merged away.  We only mmap these stable files, so
    /// this is safe in practice.
    fn mmap_file(path: &Path) -> Result<Mmap> {
        let file = File::open(path).with_context(|| format!("opening {:?} for mmap", path))?;
        // Zero-length files would panic — short-circuit.
        let len = file.metadata().with_context(|| "stat for mmap")?.len();
        if len == 0 {
            return Err(anyhow::anyhow!("empty file"));
        }
        let mmap = unsafe { Mmap::map(&file) }.with_context(|| format!("mmap {:?}", path))?;
        Ok(mmap)
    }

    fn load_norms(path: &Path) -> Result<Vec<(u32, u16, u8)>> {
        let bytes = fs::read(path).with_context(|| format!("opening norms {:?}", path))?;
        // V4 M4.7 compact format starts with `NORMS_MAGIC`; legacy starts
        // with a raw u32 count (whose first byte almost never matches 'Z').
        if bytes.len() >= 4 && &bytes[..4] == NORMS_MAGIC {
            if bytes.len() < 4 + 1 + 4 + 4 {
                return Err(anyhow::anyhow!("norms: truncated ZNM1 header"));
            }
            let encoding = bytes[4];
            let dense_len = u32::from_le_bytes(bytes[5..9].try_into().unwrap()) as usize;
            let payload_len = u32::from_le_bytes(bytes[9..13].try_into().unwrap()) as usize;
            let payload = &bytes[13..13 + payload_len];
            let dense: Vec<u8> = match encoding {
                0 => payload.to_vec(),
                1 => lz4_flex::decompress_size_prepended(payload)
                    .map_err(|e| anyhow::anyhow!("norms: lz4 decompress: {e}"))?,
                _ => return Err(anyhow::anyhow!("norms: unknown encoding {}", encoding)),
            };
            if dense.len() != dense_len {
                return Err(anyhow::anyhow!(
                    "norms: dense length mismatch {} != {}",
                    dense.len(),
                    dense_len
                ));
            }
            // Materialise (doc_id, norm) pairs only for live docs so the
            // rest of the engine (which expects `Vec<(u32, u16)>`) is
            // unchanged.  Zero bytes → missing.
            let mut norms = Vec::new();
            for (doc_id, &b) in dense.iter().enumerate() {
                if b != 0 {
                    norms.push((doc_id as u32, norm_u8_to_u16(b), b));
                }
            }
            Ok(norms)
        } else {
            // Legacy path (pre-M4.7): u32 count + count × (u32 doc_id, u16 norm).
            let mut cur = std::io::Cursor::new(&bytes[..]);
            let count = cur.read_u32::<LittleEndian>()? as usize;
            let mut norms = Vec::with_capacity(count);
            for _ in 0..count {
                let doc_id = cur.read_u32::<LittleEndian>()?;
                let norm = cur.read_u16::<LittleEndian>()?;
                // The pre-M4.7 format stored an unquantised length; the byte a
                // writer would emit for it is what a merge must carry forward.
                norms.push((doc_id, norm, norm_u16_to_u8(norm)));
            }
            Ok(norms)
        }
    }

    /// Heap bytes this reader retains, for the segment-cache budget.
    ///
    /// Only *owned* allocations are counted. `Mmap` backings are deliberately
    /// excluded: they are page-cache pages the kernel can reclaim, not heap the
    /// process is responsible for, and charging them would make the budget
    /// refuse to cache readers that cost almost nothing to hold.
    ///
    /// The dominant terms are the two decompressed blobs. A compressed `.post`
    /// (`ZPS1`) or `.meta` (`ZFM4`) cannot be mmap'd — it must be inflated into
    /// an owned `Vec` at open time — so on a modern segment this is essentially
    /// `post_uncompressed + meta_uncompressed`.
    pub fn retained_bytes(&self) -> u64 {
        let mut total: u64 = 0;
        for (name, f) in &self.fields {
            total += name.len() as u64;
            if let PostData::Owned(v) = &f.post_data {
                total += v.len() as u64;
            }
            if let FstData::Owned(m) = &f.fst {
                total += m.as_fst().as_bytes().len() as u64;
            }
            total += f.meta.flat_records.len() as u64;
            // `norms` is Vec<(u32, u16, u8)>, which pads to 8 bytes per element.
            total += (f.norms.len() as u64) * 8;
            // Legacy ZFM1/ZFM2 keep per-term metadata in a HashMap instead of
            // the flat array; approximate it rather than walking every entry.
            total += (f.meta.terms.len() as u64) * 64;
        }
        total
    }

    /// Look up a term in a field.
    ///
    /// Returns `Some(TermPostings)` if the term exists, `None` otherwise.
    pub fn lookup_term(&self, field: &str, term: &str) -> Option<TermPostings> {
        let loaded = self.fields.get(field)?;
        let fst_value = loaded.fst.get(term.as_bytes())?;
        match loaded.meta.fst_value_format {
            FstValueFormat::MetaByteOffset => {
                // ZFM3: the FST value is the byte offset of a 24-byte
                // record inside the flat `.meta` array.
                let off = fst_value as usize;
                let end = off.checked_add(ZFM3_RECORD_LEN)?;
                let rec = loaded
                    .meta
                    .flat_records
                    .get(off.checked_sub(ZFM3_HEADER_LEN)?..end.checked_sub(ZFM3_HEADER_LEN)?)?;
                // rec is exactly 24 bytes: df(4) ttf(8) off(8) len(4).
                let mut cur = std::io::Cursor::new(rec);
                let doc_frequency = cur.read_u32::<LittleEndian>().ok()?;
                let total_term_frequency = cur.read_u64::<LittleEndian>().ok()?;
                let postings_offset = cur.read_u64::<LittleEndian>().ok()?;
                let postings_length = cur.read_u32::<LittleEndian>().ok()?;
                Some(TermPostings {
                    doc_frequency,
                    total_term_frequency,
                    postings_offset,
                    postings_length,
                })
            }
            FstValueFormat::PostingsOffset => {
                // Legacy ZFM1/ZFM2: term metadata lives in `terms`,
                // keyed by term string.
                let _ = fst_value;
                let serial = loaded.meta.terms.get(term)?;
                Some(TermPostings {
                    doc_frequency: serial.doc_frequency,
                    total_term_frequency: serial.total_term_frequency,
                    postings_offset: serial.postings_offset,
                    postings_length: serial.postings_length,
                })
            }
        }
    }

    /// Get the raw postings bytes for a term (to hand to `PostingsReader`).
    ///
    /// Always `None` on a [`Self::open_stats_only`] reader — it never read the
    /// postings envelope, so a caller that got this far would otherwise decode
    /// an empty buffer and silently see zero postings.
    pub fn postings_data<'a>(&'a self, field: &str, tp: &TermPostings) -> Option<&'a [u8]> {
        if self.stats_only {
            return None;
        }
        let loaded = self.fields.get(field)?;
        let start = tp.postings_offset as usize;
        let end = start + tp.postings_length as usize;
        loaded.post_data.as_bytes().get(start..end)
    }

    /// Build the postings iterator for one term, choosing the inner block
    /// codec the way the segment writer chose it.
    ///
    /// This is the sanctioned constructor for searchers and re-readers:
    /// the codec comes from the envelope magic this reader already
    /// decoded, and the freq-elision flag from the SAME `ttf == df`
    /// predicate the writer applied — facts the caller would otherwise
    /// have to thread through manually, and get wrong on the first
    /// mixed-version index.
    pub fn postings_reader<'a>(
        &'a self,
        field: &str,
        tp: &TermPostings,
    ) -> Option<crate::postings::PostingsReader<'a>> {
        let data = self.postings_data(field, tp)?;
        let has_positions = self.field_has_positions(field);
        let codec = if self.field_post_block_v2(field) {
            crate::postings::PostCodec::v2_for(
                has_positions,
                tp.total_term_frequency,
                tp.doc_frequency,
            )
        } else {
            crate::postings::PostCodec::V1
        };
        Some(crate::postings::PostingsReader::new_with_codec(
            data,
            tp.doc_frequency,
            has_positions,
            codec,
        ))
    }

    /// Whether this field's `.post` envelope is ZPS2 (FOR inner framing).
    fn field_post_block_v2(&self, field: &str) -> bool {
        self.fields
            .get(field)
            .map(|loaded| loaded.post_block_v2)
            .unwrap_or(false)
    }

    /// Per-segment document frequency for a term (number of docs containing
    /// the term in this segment's postings).  Returns `None` if the term is
    /// not present in the segment's FST.
    ///
    /// This is the O(1) hook used by the `shortcut_total_hit_count` fast
    /// path: `sum across segments` → total doc count for a `term` query
    /// without touching a single posting list.  Mirrors Lucene's
    /// `TermsEnum.docFreq()` contract.
    pub fn term_doc_freq(&self, field: &str, term: &str) -> Option<u32> {
        // Re-use the full lookup path — it handles ZFM3's flat-record
        // decode and ZFM1/ZFM2's HashMap lookup uniformly.
        self.lookup_term(field, term).map(|tp| tp.doc_frequency)
    }

    /// Get the field stats (for BM25 scorer construction).
    pub fn field_stats(&self, field: &str) -> Option<&FieldStats> {
        self.fields.get(field).map(|f| &f.meta.stats)
    }

    /// `true` when the field's posting lists carry term freqs + positions.
    /// `false` for docs-only fields (keyword, numeric, ip), in which case
    /// the caller must construct a `PostingsReader` with `has_positions
    /// = false` so the decoder synthesises freq=1 per posting.
    ///
    /// Returns `true` for unknown fields (safe default matching legacy
    /// ZFM1 segments).
    pub fn field_has_positions(&self, field: &str) -> bool {
        self.fields
            .get(field)
            .map(|f| f.meta.has_positions)
            .unwrap_or(true)
    }

    /// Look up the field length (norm) for a specific document.
    /// Returns `None` if the document has no data for this field — which is
    /// every document on a [`Self::open_stats_only`] reader, whose norms
    /// table was deliberately not loaded.
    pub fn field_length(&self, field: &str, doc_id: u32) -> Option<u16> {
        let loaded = self.fields.get(field)?;
        // Binary search by doc_id
        loaded
            .norms
            .binary_search_by_key(&doc_id, |(id, _, _)| *id)
            .ok()
            .map(|idx| loaded.norms[idx].1)
    }

    /// Every `(doc_id, quantised norm byte)` this field records, ascending by
    /// doc id.  Docs whose norm byte is zero are absent — the dense on-disk
    /// array cannot tell "field missing" from "field length 1" (both encode
    /// as byte 0), and neither can this.
    ///
    /// Exists for the merge path: a merged segment must write the SAME norm
    /// byte the source segment holds, and [`Self::field_length`]'s
    /// dequantised `u16` cannot be re-quantised back to it.
    pub fn field_norm_bytes(&self, field: &str) -> impl Iterator<Item = (u32, u8)> + '_ {
        self.fields.get(field).into_iter().flat_map(|loaded| {
            loaded
                .norms
                .iter()
                .map(|(doc_id, _, byte)| (*doc_id, *byte))
        })
    }

    /// Stream every term of `field` through `f` in lexicographic order,
    /// stopping as soon as `f` returns `false`.
    ///
    /// Unlike [`Self::all_terms`] this never materialises the dictionary —
    /// multi-term expansion (prefix/wildcard/fuzzy) walks dictionaries with
    /// millions of entries, and building a `Vec<String>` first both doubles
    /// the walk cost and makes the whole enumeration an uninterruptible
    /// unit (RC4 blocker 12: search `timeout` could never fire during
    /// expansion). The callback's `bool` return is the cooperative
    /// cancellation hook.
    pub fn for_each_term<F: FnMut(&str) -> bool>(&self, field: &str, mut f: F) {
        let Some(loaded) = self.fields.get(field) else {
            return;
        };
        use fst::Streamer;
        match &loaded.fst {
            FstData::Mmap(m) => {
                let mut stream = m.stream();
                while let Some((key, _)) = stream.next() {
                    if let Ok(s) = std::str::from_utf8(key) {
                        if !f(s) {
                            return;
                        }
                    }
                }
            }
            FstData::Owned(m) => {
                let mut stream = m.stream();
                while let Some((key, _)) = stream.next() {
                    if let Ok(s) = std::str::from_utf8(key) {
                        if !f(s) {
                            return;
                        }
                    }
                }
            }
        }
    }

    /// Enumerate all terms in a field (lexicographic order, for debugging/admin).
    pub fn all_terms(&self, field: &str) -> Vec<String> {
        let Some(loaded) = self.fields.get(field) else {
            return Vec::new();
        };
        use fst::Streamer;
        let mut terms = Vec::new();
        match &loaded.fst {
            FstData::Mmap(m) => {
                let mut stream = m.stream();
                while let Some((key, _)) = stream.next() {
                    if let Ok(s) = std::str::from_utf8(key) {
                        terms.push(s.to_owned());
                    }
                }
            }
            FstData::Owned(m) => {
                let mut stream = m.stream();
                while let Some((key, _)) = stream.next() {
                    if let Ok(s) = std::str::from_utf8(key) {
                        terms.push(s.to_owned());
                    }
                }
            }
        }
        terms
    }

    /// Returns `true` if a term exists in the field's FST (O(m) where m = term length).
    pub fn term_exists(&self, field: &str, term: &str) -> bool {
        self.fields
            .get(field)
            .map(|f| f.fst.get(term.as_bytes()).is_some())
            .unwrap_or(false)
    }

    pub fn indexed_fields(&self) -> Vec<&str> {
        self.fields.keys().map(|s| s.as_str()).collect()
    }
}

