    fn make_registry() -> Arc<AnalyzerRegistry> {
        Arc::new(AnalyzerRegistry::default())
    }

    /// A registry built the way the engine builds one for
    /// `settings.analysis.analyzer.default = {"type": "english"}` — the
    /// built-in `english` pipeline registered under the name `default`.
    fn english_default_registry() -> Arc<AnalyzerRegistry> {
        let mut registry = AnalyzerRegistry::default();
        registry.apply_settings(&serde_json::json!({
            "analysis": {"analyzer": {"default": {"type": "english"}}}
        }));
        assert!(
            registry.get_analyzer("default").is_some(),
            "fixture: the declared default must resolve"
        );
        Arc::new(registry)
    }

    /// #937: a writer whose registry declares a `default` analyzer records
    /// it per field; a writer with no declaration writes no marker at all
    /// (byte- and directory-identical flushes for indexes that declare
    /// nothing).
    #[test]
    fn analyzer_marker_written_only_for_non_standard_analysis() {
        let plain = TempDir::new().unwrap();
        let mut writer = FtsIndexWriter::new(plain.path(), "seg0", make_registry());
        writer.configure_field(
            "body",
            FieldIndexConfig {
                analyzer: "standard".to_owned(),
                store_positions: true,
                store_term_vectors: false,
            },
        );
        let document = [("body".to_owned(), FieldValues::from("fast car"))]
            .into_iter()
            .collect();
        writer.add_document(0, &document);
        writer.finish().unwrap();
        assert!(
            segment_recorded_analyzers(plain.path(), "seg0").is_none(),
            "an all-standard segment must not grow a marker file"
        );
        assert!(
            !plain.path().join("seg0.ftsan").exists(),
            "the directory must stay identical to a pre-#937 flush"
        );

        let declared = TempDir::new().unwrap();
        let registry = english_default_registry();
        let mut writer = FtsIndexWriter::new(declared.path(), "seg0", Arc::clone(&registry));
        writer.configure_field(
            "body",
            FieldIndexConfig {
                analyzer: "default".to_owned(),
                store_positions: true,
                store_term_vectors: false,
            },
        );
        writer.configure_field(
            "tag",
            FieldIndexConfig {
                analyzer: "keyword".to_owned(),
                store_positions: false,
                store_term_vectors: false,
            },
        );
        let document = [
            ("body".to_owned(), FieldValues::from("the bagels")),
            ("tag".to_owned(), FieldValues::from("GET")),
        ]
        .into_iter()
        .collect();
        writer.add_document(0, &document);
        writer.finish().unwrap();
        let recorded = segment_recorded_analyzers(declared.path(), "seg0")
            .expect("a segment with non-standard fields records its analyzers");
        assert_eq!(recorded.get("body").map(String::as_str), Some("default"));
        assert_eq!(recorded.get("tag").map(String::as_str), Some("keyword"));
    }

    /// #937: an UNCONFIGURED field is analysed with the registry's declared
    /// `default` (matching the memtable's insert path), and with `standard`
    /// when nothing is declared.
    #[test]
    fn unconfigured_field_follows_the_declared_default() {
        let dir = TempDir::new().unwrap();

        // Declared english default: `bagels` stems to `bagel`, `the` drops.
        let registry = english_default_registry();
        let mut writer = FtsIndexWriter::new(dir.path(), "seg0", registry);
        let document = [("t".to_owned(), FieldValues::from("the bagels"))]
            .into_iter()
            .collect();
        writer.add_document(0, &document);
        writer.finish().unwrap();
        let reader = FtsIndexReader::open(dir.path(), "seg0", &["t"]).unwrap();
        assert!(reader.term_exists("t", "bagel"), "stemmed token present");
        assert!(!reader.term_exists("t", "bagels"), "unstemmed token absent");
        assert!(!reader.term_exists("t", "the"), "stop-word dropped");
        let recorded = segment_recorded_analyzers(dir.path(), "seg0").unwrap();
        assert_eq!(recorded.get("t").map(String::as_str), Some("default"));

        // No declaration: `standard` keeps `bagels` whole and `the` present.
        let dir2 = TempDir::new().unwrap();
        let mut writer = FtsIndexWriter::new(dir2.path(), "seg0", make_registry());
        let document = [("t".to_owned(), FieldValues::from("the bagels"))]
            .into_iter()
            .collect();
        writer.add_document(0, &document);
        writer.finish().unwrap();
        let reader = FtsIndexReader::open(dir2.path(), "seg0", &["t"]).unwrap();
        assert!(reader.term_exists("t", "bagels"));
        assert!(reader.term_exists("t", "the"));
        assert!(segment_recorded_analyzers(dir2.path(), "seg0").is_none());
    }

    /// #2427/#1122: the engine reserves read memory from this estimate before
    /// a full open, so it must not undercount what the open retains.
    #[test]
    fn estimate_open_bytes_covers_the_retained_postings_and_norms() {
        let dir = TempDir::new().unwrap();
        let mut writer = FtsIndexWriter::new(dir.path(), "seg-est", make_registry());
        for i in 0..2_000u32 {
            let text = format!("doc {i} alpha beta gamma term{} other{}", i % 97, i % 13);
            let doc: HashMap<String, FieldValues> = [("body".to_owned(), FieldValues::from(text))]
                .into_iter()
                .collect();
            writer.add_document(i, &doc);
        }
        writer.finish().unwrap();
        let reader = FtsIndexReader::open(dir.path(), "seg-est", &["body"]).unwrap();
        let estimate = FtsIndexReader::estimate_open_bytes(dir.path(), "seg-est", &["body"]);
        let retained = reader.retained_bytes();
        assert!(retained > 0);
        assert!(
            estimate >= retained,
            "estimate {estimate} must cover the {retained} bytes the open retains"
        );
        assert_eq!(
            FtsIndexReader::estimate_open_bytes(dir.path(), "seg-missing", &["body"]),
            "body".len() as u64,
            "a segment without side-cars costs (almost) nothing"
        );
    }

    #[test]
    fn write_and_read_single_field() {
        let dir = TempDir::new().unwrap();
        let registry = make_registry();

        let mut writer = FtsIndexWriter::new(dir.path(), "seg0", registry);

        let docs: Vec<HashMap<String, FieldValues>> = vec![
            [("body".to_owned(), FieldValues::from("the quick brown fox"))]
                .into_iter()
                .collect(),
            [("body".to_owned(), FieldValues::from("the lazy dog"))]
                .into_iter()
                .collect(),
            [("body".to_owned(), FieldValues::from("quick fox lazy dog"))]
                .into_iter()
                .collect(),
        ];

        for (i, doc) in docs.iter().enumerate() {
            writer.add_document(i as u32, doc);
        }

        let stats = writer.finish().unwrap();
        assert!(stats.contains_key("body"));
        assert_eq!(stats["body"].total_docs, 3);

        // Read back
        let reader = FtsIndexReader::open(dir.path(), "seg0", &["body"]).unwrap();

        // "fox" should appear in docs 0 and 2 (after stemming by standard analyzer → "fox")
        // "quick" → "quick" (not stemmed significantly)
        let all_terms = reader.all_terms("body");
        assert!(!all_terms.is_empty(), "should have indexed terms");

        // "lazi" is the Snowball stem of "lazy"
        let lazi_exists = reader.term_exists("body", "lazi") || reader.term_exists("body", "lazy");
        assert!(
            lazi_exists,
            "lazy/lazi should be indexed; terms={:?}",
            all_terms
        );

        // Field stats round-trip
        let fs = reader.field_stats("body").unwrap();
        assert_eq!(fs.total_docs, 3);

        // Norms: each doc should have a norm entry
        for i in 0u32..3 {
            let norm = reader.field_length("body", i);
            assert!(norm.is_some(), "doc {} should have a norm", i);
            assert!(norm.unwrap() > 0, "norm should be non-zero for doc {}", i);
        }
    }

    /// #332 — a `keyword`-analyzed field with N values must produce N terms,
    /// and must NOT produce the space-joined concatenation of them.
    #[test]
    fn keyword_field_indexes_each_value_as_its_own_term() {
        let dir = TempDir::new().unwrap();
        let mut writer = FtsIndexWriter::new(dir.path(), "seg-mv-kw", make_registry());
        writer.configure_field(
            "tags",
            FieldIndexConfig {
                analyzer: "keyword".to_owned(),
                ..Default::default()
            },
        );
        writer.add_document(
            0,
            &[(
                "tags".to_owned(),
                FieldValues::from(vec!["red".to_owned(), "blue".to_owned()]),
            )]
            .into_iter()
            .collect(),
        );
        writer.finish().unwrap();

        let reader = FtsIndexReader::open(dir.path(), "seg-mv-kw", &["tags"]).unwrap();
        let mut terms = reader.all_terms("tags");
        terms.sort();
        assert_eq!(
            terms,
            vec!["blue".to_owned(), "red".to_owned()],
            "each array element is its own keyword term, and \"red blue\" is not a term"
        );
        // The norm is the SUM over values, as in Lucene: one token each.
        assert_eq!(reader.field_length("tags", 0), Some(2));
        // One (doc, field) pair, however many values it carried.
        assert_eq!(reader.field_stats("tags").unwrap().total_docs, 1);
    }

    /// #332 — consecutive values are separated by `POSITION_INCREMENT_GAP`, so
    /// a phrase cannot straddle the boundary between two array elements.
    #[test]
    fn position_increment_gap_separates_consecutive_values() {
        let dir = TempDir::new().unwrap();
        let mut writer = FtsIndexWriter::new(dir.path(), "seg-mv-pos", make_registry());
        writer.configure_field(
            "notes",
            FieldIndexConfig {
                analyzer: "whitespace".to_owned(),
                ..Default::default()
            },
        );
        writer.add_document(
            0,
            &[(
                "notes".to_owned(),
                FieldValues::from(vec!["alpha bravo".to_owned(), "charlie delta".to_owned()]),
            )]
            .into_iter()
            .collect(),
        );
        writer.finish().unwrap();

        let reader = FtsIndexReader::open(dir.path(), "seg-mv-pos", &["notes"]).unwrap();
        let position_of = |term: &str| -> u32 {
            let tp = reader.lookup_term("notes", term).expect("term present");
            let mut pr = reader.postings_reader("notes", &tp).expect("postings");
            let p = pr.next().expect("one posting");
            p.positions[0]
        };

        // Value 0 occupies positions 0 and 1.
        assert_eq!(position_of("alpha"), 0);
        assert_eq!(position_of("bravo"), 1);
        // Value 1 restarts one past the previous value, plus the gap.
        assert_eq!(position_of("charlie"), 2 + POSITION_INCREMENT_GAP);
        assert_eq!(position_of("delta"), 3 + POSITION_INCREMENT_GAP);
        // `bravo charlie` is therefore 100 positions apart, not adjacent —
        // no realistic `slop` bridges it.
        assert_eq!(position_of("charlie") - position_of("bravo"), 101);
    }

    #[test]
    fn term_lookup_returns_correct_metadata() {
        let dir = TempDir::new().unwrap();
        let registry = make_registry();

        let mut writer = FtsIndexWriter::new(dir.path(), "seg1", registry);

        // Use keyword analyzer to avoid stemming surprises
        let cfg = FieldIndexConfig {
            analyzer: "whitespace".to_owned(),
            ..Default::default()
        };
        writer.configure_field("title", cfg);

        let docs = [
            [("title".to_owned(), FieldValues::from("hello world"))]
                .into_iter()
                .collect(),
            [("title".to_owned(), FieldValues::from("hello rust"))]
                .into_iter()
                .collect(),
        ];
        for (i, doc) in docs.iter().enumerate() {
            writer.add_document(i as u32, doc);
        }
        writer.finish().unwrap();

        let reader = FtsIndexReader::open(dir.path(), "seg1", &["title"]).unwrap();

        // "hello" appears in both docs
        let tp = reader
            .lookup_term("title", "hello")
            .expect("'hello' should be in index");
        assert_eq!(tp.doc_frequency, 2);
        assert_eq!(tp.total_term_frequency, 2);

        // "world" appears in 1 doc
        let tp = reader
            .lookup_term("title", "world")
            .expect("'world' should be in index");
        assert_eq!(tp.doc_frequency, 1);

        // Postings data retrievable
        let tp = reader.lookup_term("title", "hello").unwrap();
        let data = reader.postings_data("title", &tp);
        assert!(data.is_some() && !data.unwrap().is_empty());
    }

    /// The current writer stamps the `ZFM5` meta format, and lookups
    /// round-trip through the expanded flat records: a repeated term
    /// (ttf > df) exercises the ttf stream, a keyword field with all
    /// ttf == df exercises the elided-stream path, and both must agree
    /// with the postings envelope's own view of the data.
    #[test]
    fn zfm5_envelope_written_and_lookup_roundtrips() {
        let dir = TempDir::new().unwrap();
        let mut writer = FtsIndexWriter::new(dir.path(), "seg-zfm5", make_registry());
        writer.configure_field(
            "title",
            FieldIndexConfig {
                analyzer: "whitespace".to_owned(),
                ..Default::default()
            },
        );
        writer.configure_field(
            "tag",
            FieldIndexConfig {
                analyzer: "keyword".to_owned(),
                ..Default::default()
            },
        );
        let doc = |title: &str, tag: &str| -> HashMap<String, FieldValues> {
            vec![
                ("title".to_owned(), FieldValues::from(title)),
                ("tag".to_owned(), FieldValues::from(tag)),
            ]
            .into_iter()
            .collect()
        };
        writer.add_document(0, &doc("hello hello world", "alpha"));
        writer.add_document(1, &doc("hello rust", "beta"));
        writer.finish().unwrap();

        let meta = fs::read(dir.path().join("seg-zfm5.title.meta")).unwrap();
        assert_eq!(&meta[..4], META_MAGIC_V5, "writer must stamp ZFM5");

        let reader = FtsIndexReader::open(dir.path(), "seg-zfm5", &["title", "tag"]).unwrap();
        let tp = reader.lookup_term("title", "hello").unwrap();
        assert_eq!(tp.doc_frequency, 2);
        assert_eq!(tp.total_term_frequency, 3); // ttf stream carries 3 − 2
        let data = reader.postings_data("title", &tp).unwrap();
        assert!(!data.is_empty());
        let tp = reader.lookup_term("tag", "alpha").unwrap();
        assert_eq!(tp.doc_frequency, 1);
        assert_eq!(tp.total_term_frequency, 1); // elided stream ⇒ df + 0
        assert!(reader.postings_data("tag", &tp).is_some());
    }

    /// Stream-level properties: the ttf stream is elided only when every
    /// term has ttf == df, expansion reproduces the ZFM3 record layout
    /// byte-for-byte, and non-contiguous postings gaps reconstruct
    /// exactly.  The elided file must not be larger than the streamed one.
    #[test]
    fn zfm5_stream_elision_and_record_expansion_match_zfm3_layout() {
        let stats = FieldStats {
            total_docs: 9,
            total_field_length: 40,
        };
        // `a_extra`/`c_extra` are ttf−df deltas: (0, 0) keeps every term
        // at ttf == df (the elided shape); any non-zero forces the stream.
        let mk = |a_ttf: u64, c_extra: u64| {
            let mut map = HashMap::new();
            // Non-contiguous on purpose: gaps of 0, 7 and 90 bytes.
            map.insert(
                "a".to_owned(),
                TermPostings {
                    doc_frequency: 3,
                    total_term_frequency: 3 + a_ttf,
                    postings_offset: 100,
                    postings_length: 10,
                },
            );
            map.insert(
                "b".to_owned(),
                TermPostings {
                    doc_frequency: 1,
                    total_term_frequency: 1,
                    postings_offset: 117,
                    postings_length: 20,
                },
            );
            map.insert(
                "c".to_owned(),
                TermPostings {
                    doc_frequency: 0x2000_0001, // forces a 5-byte varint lane
                    total_term_frequency: 0x2000_0001 + c_extra,
                    postings_offset: 200,
                    postings_length: 5,
                },
            );
            map
        };
        let terms = ["a".to_owned(), "b".to_owned(), "c".to_owned()];
        let elided = encode_field_meta_v5(&stats, true, &terms, &mk(0, 0), 3).unwrap();
        let streamed = encode_field_meta_v5(&stats, true, &terms, &mk(1, 0), 3).unwrap();
        assert_eq!(&elided[..4], META_MAGIC_V5);
        // flags byte sits right after has_positions.
        assert_eq!(elided[25] & ZFM5_FLAG_TTF_STREAM, 0, "ttf==df must elide");
        assert_eq!(streamed[25] & ZFM5_FLAG_TTF_STREAM, ZFM5_FLAG_TTF_STREAM);
        assert!(elided.len() <= streamed.len());

        let decoded = decode_field_meta_binary(&elided).unwrap();
        let mut expected: Vec<u8> = Vec::new();
        for tp in [&mk(0, 0)["a"], &mk(0, 0)["b"], &mk(0, 0)["c"]] {
            expected
                .write_u32::<LittleEndian>(tp.doc_frequency)
                .unwrap();
            expected
                .write_u64::<LittleEndian>(tp.total_term_frequency)
                .unwrap();
            expected
                .write_u64::<LittleEndian>(tp.postings_offset)
                .unwrap();
            expected
                .write_u32::<LittleEndian>(tp.postings_length)
                .unwrap();
        }
        assert_eq!(decoded.flat_records, expected);
        assert_eq!(decoded.stats.total_docs, 9);
        assert!(decoded.has_positions);
    }

    /// Malformed input fails closed: truncated header, wrong
    /// uncompressed_len, trailing payload, trailing stream varints, and
    /// a missing section.  The encoder likewise refuses non-monotone
    /// offsets rather than silently clamping the gap.
    #[test]
    fn zfm5_rejects_malformed_and_non_monotone() {
        let stats = FieldStats {
            total_docs: 2,
            total_field_length: 4,
        };
        let mut map = HashMap::new();
        map.insert(
            "a".to_owned(),
            TermPostings {
                doc_frequency: 1,
                total_term_frequency: 1,
                postings_offset: 10,
                postings_length: 4,
            },
        );
        let terms = ["a".to_owned()];
        let good = encode_field_meta_v5(&stats, false, &terms, &map, 3).unwrap();

        // (prev_end = 10 + 4 = 14) > 0 — offset must not go backwards.
        let backwards = {
            let mut m = map.clone();
            m.get_mut("a").unwrap().postings_offset = 10;
            m.insert(
                "b".to_owned(),
                TermPostings {
                    doc_frequency: 1,
                    total_term_frequency: 1,
                    postings_offset: 5,
                    postings_length: 1,
                },
            );
            encode_field_meta_v5(&stats, false, &["a".to_owned(), "b".to_owned()], &m, 3)
        };
        assert!(backwards.is_err());

        assert!(decode_field_meta_binary(&good[..good.len() - 1]).is_err());
        let mut bad_len = good.clone();
        bad_len[26..30].copy_from_slice(&999u32.to_le_bytes()); // uncompressed_len
        assert!(decode_field_meta_binary(&bad_len).is_err());
        let mut trailing = good.clone();
        trailing.push(0);
        assert!(decode_field_meta_binary(&trailing).is_err());

        // Hand-assembled stream sections: one extra varint ⇒ trailing bytes.
        use crate::postings::uvarint_encode;
        let assemble = |flags: u8, streams: &[u8]| {
            let compressed = zstd::bulk::compress(streams, 3).unwrap();
            let mut out = Vec::new();
            out.extend_from_slice(META_MAGIC_V5);
            out.write_u64::<LittleEndian>(2).unwrap();
            out.write_u64::<LittleEndian>(4).unwrap();
            out.write_u32::<LittleEndian>(1).unwrap();
            out.push(0);
            out.push(flags);
            out.write_u32::<LittleEndian>(24).unwrap();
            out.write_u32::<LittleEndian>(compressed.len() as u32)
                .unwrap();
            out.extend_from_slice(&compressed);
            out
        };
        let mut extra = Vec::new();
        uvarint_encode(1, &mut extra); // df
        uvarint_encode(10, &mut extra); // gap
        uvarint_encode(4, &mut extra); // len
        uvarint_encode(9, &mut extra); // stray
        assert!(decode_field_meta_binary(&assemble(0, &extra)).is_err());
        let mut missing = Vec::new();
        uvarint_encode(1, &mut missing);
        uvarint_encode(10, &mut missing); // len stream absent
        assert!(decode_field_meta_binary(&assemble(0, &missing)).is_err());

        // A ttf delta is an untrusted varint up to u64::MAX.  df + delta
        // must fail closed rather than wrap — a wrapped ttf < df would
        // flip the ZPS2 freq-elision predicate downstream.
        let mut wrap = Vec::new();
        uvarint_encode(1, &mut wrap); // df
        uvarint_encode(u64::MAX, &mut wrap); // ttf delta
        uvarint_encode(10, &mut wrap); // gap
        uvarint_encode(4, &mut wrap); // len
        let error = decode_field_meta_binary(&assemble(ZFM5_FLAG_TTF_STREAM, &wrap)).unwrap_err();
        assert!(
            error.to_string().contains("ttf overflow"),
            "must reject the wrapped delta, got: {error}"
        );
    }

    /// The current writer stamps the `ZPS2` envelope, and the reader
    /// factory threads the codec that implies: a positioned term with
    /// ttf == df decodes with synthesised freqs (its freq stream was
    /// elided), a term with repeats keeps real freqs, and a docs-only
    /// keyword field synthesises freq 1 as it always has.
    #[test]
    fn zps2_envelope_written_and_factory_roundtrips() {
        let dir = TempDir::new().unwrap();
        let mut writer = FtsIndexWriter::new(dir.path(), "seg-zps2", make_registry());
        writer.configure_field(
            "body",
            FieldIndexConfig {
                analyzer: "whitespace".to_owned(),
                store_positions: true,
                store_term_vectors: false,
            },
        );
        writer.configure_field(
            "tag",
            FieldIndexConfig {
                analyzer: "keyword".to_owned(),
                store_positions: false,
                store_term_vectors: false,
            },
        );
        let docs: Vec<HashMap<String, FieldValues>> = (0..300)
            .map(|i| {
                [
                    (
                        "body".to_owned(),
                        FieldValues::from(format!("solo echo echo {i}")),
                    ),
                    ("tag".to_owned(), FieldValues::from(format!("tag{}", i % 7))),
                ]
                .into_iter()
                .collect()
            })
            .collect();
        for (i, doc) in docs.iter().enumerate() {
            writer.add_document(i as u32, doc);
        }
        writer.finish().unwrap();

        let raw = fs::read(dir.path().join("seg-zps2.body.post")).unwrap();
        assert_eq!(
            &raw[..4],
            b"ZPS2",
            "current writer stamps the ZPS2 envelope"
        );

        let reader = FtsIndexReader::open(dir.path(), "seg-zps2", &["body", "tag"]).unwrap();

        let tp = reader.lookup_term("body", "solo").unwrap();
        assert_eq!(tp.doc_frequency, 300);
        assert_eq!(tp.total_term_frequency, 300, "ttf == df => freqs elided");
        let mut pr = reader.postings_reader("body", &tp).unwrap();
        for i in 0u32..300 {
            let p = pr.next().expect("300 postings");
            assert_eq!(p.doc_id, i);
            assert_eq!(p.term_freq, 1, "elided freqs synthesise 1");
            assert_eq!(p.positions, vec![0], "solo is the first token");
        }
        assert!(pr.next().is_none());

        let tp = reader.lookup_term("body", "echo").unwrap();
        assert_eq!(tp.total_term_frequency, 600);
        let mut pr = reader.postings_reader("body", &tp).unwrap();
        let p = pr.next().unwrap();
        assert_eq!(p.term_freq, 2, "a term with repeats keeps real freqs");
        assert_eq!(p.positions, vec![1, 2]);

        let tp = reader.lookup_term("tag", "tag3").unwrap();
        let mut pr = reader.postings_reader("tag", &tp).unwrap();
        let mut count = 0u32;
        while let Some(p) = pr.next() {
            assert_eq!(p.term_freq, 1, "docs-only synthesises freq 1");
            count += 1;
        }
        assert_eq!(count, 43, "docs 3, 10, … 296 carry tag3");
    }

    /// A segment whose `.post` still carries the `ZPS1` envelope and the old
    /// inner framing decodes through `PostCodec::V1`.  The fixture rewrites
    /// one docs-only field's postings into a hand-built ZPS1 block stream
    /// (one full block, deltas all 1) and repairs the meta record to point
    /// at it — exactly the shape an on-disk segment written before the ZPS2
    /// bump has.
    #[test]
    fn zps1_envelope_segment_still_decodes() {
        let dir = TempDir::new().unwrap();
        let mut writer = FtsIndexWriter::new(dir.path(), "seg-zps1", make_registry());
        writer.configure_field(
            "tag",
            FieldIndexConfig {
                analyzer: "keyword".to_owned(),
                store_positions: false,
                store_term_vectors: false,
            },
        );
        for i in 0..128u32 {
            let document = [("tag".to_owned(), FieldValues::from("needle"))]
                .into_iter()
                .collect();
            writer.add_document(i, &document);
        }
        writer.finish().unwrap();

        // V1 inner blob: [num_bits = 1][u32 byte_len = 16][lanes 0,1,1,…]
        // (lane 0 = 0 = gap from prev doc 0; the rest hold delta 1).
        let mut inner: Vec<u8> = Vec::new();
        inner.push(1u8);
        inner.extend_from_slice(&16u32.to_le_bytes());
        inner.push(0xFE);
        inner.extend(std::iter::repeat_n(0xFFu8, 15));
        let mut wrapped: Vec<u8> = Vec::new();
        wrapped.extend_from_slice(POST_MAGIC_ZSTD);
        wrapped.extend_from_slice(&(inner.len() as u32).to_le_bytes());
        wrapped.extend_from_slice(&zstd::bulk::compress(&inner, 1).unwrap());
        fs::write(dir.path().join("seg-zps1.tag.post"), &wrapped).unwrap();

        // The original ZPS2 blob was 2 bytes (width-0 constant block); the
        // meta record's length must describe the replacement.
        let mut term_postings: HashMap<String, TermPostings> = HashMap::new();
        term_postings.insert(
            "needle".to_owned(),
            TermPostings {
                doc_frequency: 128,
                total_term_frequency: 128,
                postings_offset: 0,
                postings_length: inner.len() as u32,
            },
        );
        let rewritten = encode_field_meta_v4(
            &FieldStats {
                total_docs: 128,
                total_field_length: 128,
            },
            false,
            &["needle".to_owned()],
            &term_postings,
            1,
        )
        .unwrap();
        fs::write(dir.path().join("seg-zps1.tag.meta"), &rewritten).unwrap();

        let reader = FtsIndexReader::open(dir.path(), "seg-zps1", &["tag"]).unwrap();
        let tp = reader.lookup_term("tag", "needle").unwrap();
        assert_eq!(tp.doc_frequency, 128);
        assert_eq!(tp.postings_length, 21);
        let mut pr = reader.postings_reader("tag", &tp).unwrap();
        for i in 0u32..128 {
            let p = pr.next().expect("128 postings out of the legacy block");
            assert_eq!(p.doc_id, i, "contiguous deltas of 1 reconstruct 0..127");
            assert_eq!(p.term_freq, 1);
        }
        assert!(pr.next().is_none());
    }

