        }
        let mut writer = FtsIndexWriter::new(&segment_dir, "seg-unsafe", make_registry());
        let document: HashMap<String, FieldValues> = fields
            .iter()
            .enumerate()
            .map(|(index, field)| {
                (
                    (*field).to_owned(),
                    FieldValues::One(format!("needle{index}")),
                )
            })
            .collect();
        writer.add_document(0, &document);
